return {
[0]={id=0,name="-Active Effects",plural="-Active Effects",description="",category=2},
[2]={id=2,name="Palborough Mines logs",plural="Palborough Mines logs",description="\nThese logs tell the tale of the\npioneers who dug the Palborough\nMines.\nThe history of Palborough is said to\nsymbolize the peak of Bastok's\nindustrial revolution.",category=0},
[3]={id=3,name="blue acidity tester",plural="blue acidity testers",description="\nAn acidity tester given to you by Cid.\nIt is currently blue.",category=2},
[4]={id=4,name="red acidity tester",plural="red acidity testers",description="\nAn acidity tester given to you by Cid.\nIts color has changed from blue\nto red.",category=2},
[5]={id=5,name="letter to the consuls",plural="letters to the consuls",description="\nIssued by the Kingdom of San d'Oria.\nA letter of introduction to the\nconsulates in Bastok and Windurst.\n\nNeeded to complete missions in\nthose countries.",category=2},
[6]={id=6,name="letter to the consuls",plural="letters to the consuls",description="\nIssued by the Republic of Bastok.\nA letter of introduction to the\nconsulates in San d'Oria and\nWindurst.\n\nNeeded to complete missions in\nthose countries.",category=2},
[7]={id=7,name="letter to the consuls",plural="letters to the consuls",description="\nIssued by the Federation of Windurst.\nA letter of introduction to the\nconsulates in Bastok and San d'Oria.\n\nNeeded to complete missions in\nthose countries.\n",category=2},
[8]={id=8,name="airship pass",plural="airship passes",description="\nThis pass allows you to ride airships\nto San d'Oria, Bastok, and Windurst\nfrom Jeuno.",category=3},
[9]={id=9,name="airship pass for Kazham",plural="airship passes for Kazham",description="\nThis pass allows you to ride the\nairship between Kazham and Jeuno.",category=3},
[10]={id=10,name="overdue book notification",plural="overdue book notifications",description="\nThis letter reads:\n\"This is your final notification to\nreturn the following overdue book\nto the Optistery's Library of Magic:\n  'Art For Everyone.'\nFailure to return this book immediately\nwill result in a string of fearsome\ncurses being cast in your direction.\nYours sinisterly,\n  Tosuka-Porika, Librarian.\"\n",category=3},
[11]={id=11,name="letter from Domien",plural="letters from Domien",description="\nThis letter reads:\n\"I do not do business with a\npromise-breaker.\"\n                      -Domien",category=0},
[12]={id=12,name="C. L. report",plural="C. L. reports",description="\n\"As I suspected, the crystal resonance\naround the 'crag' is much stronger\nthan normal. I believe it is safe to\nsurmise that the same level of crystal\nresonance can be found near\nSan d'Oria and Windurst, extending\nstraight toward Jeuno.\"\n                              -Cid",category=0},
[13]={id=13,name="Kindred crest",plural="Kindred crests",description="\nA crest you found deep in one of\nthe beastmen's lairs.\nIt may be a sign of the return\nof the Kindred.",category=2},
[14]={id=14,name="Magicite: Optistone",plural="Magicite: Optistone",description="\nA crystal you found in Davoi.\nIt is glowing eerily.",category=2},
[15]={id=15,name="Magicite: Aurastone",plural="Magicite: Aurastone",description="\nA crystal you found in Beadeaux.\nIt is glowing eerily.",category=2},
[16]={id=16,name="Magicite: Orastone",plural="Magicite: Orastone",description="\nA crystal you found in Castle Oztroja.\nIt is glowing eerily.",category=2},
[17]={id=17,name="food offering",plural="food offerings",description="\nA bag full of food the Yagudo like.\nA present as a symbol of Windurst's\nfriendship with the Yagudo.\nYour orders are to hand this to one\nof the Yagudo who stand by the two\naltars of offerings in Giddeus.\n",category=2},
[18]={id=18,name="drink offering",plural="drink offerings",description="\nA bag full of drinks the Yagudo like.\nA present as a symbol of Windurst's\nfriendship with the Yagudo.\nYour orders are to hand this to one\nof the Yagudo who stand by the two\naltars of offerings in Giddeus.\n",category=2},
[19]={id=19,name="clock tower oil",plural="clock tower oil",description="\nOil for Jeuno's clock tower.\nApparently, its gears won't\nrun smoothly without this.",category=4},
[20]={id=20,name="Yagudo torch",plural="Yagudo torches",description="\nA torch used by beastmen.\nUse it to venture further into\nCastle Oztroja.",category=2},
[21]={id=21,name="crest of Davoi",plural="crests of Davoi",description="\nNeeded to break the Orcs'\nbarrier in Davoi.",category=2},
[22]={id=22,name="letter to Aldo",plural="letters to Aldo",description="\nA letter from Kam'lanaut, Archduke\nof Jeuno. It is addressed to a certain\n\"Aldo\" of the Tenshodo.",category=2},
[23]={id=23,name="bouquet for the pioneers",plural="bouquets for the pioneers",description="\nA traveler named Elki has asked you\nto take this bouquet to the monument\nin Gustaberg where his great-\ngrandfather Omran is buried.",category=2},
[24]={id=24,name="old toolbox",plural="old toolboxes",description="\nThis toolbox contains eleven sets\nof tools.\nThe first set has the name \"Omran\"\ninscribed on it, while the name on\nthe last set reads \"Vigilant Owl.\"",category=3},
[25]={id=25,name="note from Hariga-Origa",plural="notes from Hariga-Origa",description="\nA note you received from Hariga-Origa\nin the Optistery's Manuscript Room.\nIt simply contains the glyph that\nHariga-Origa couldn't read.\n",category=2},
[26]={id=26,name="note from Ipupu",plural="notes from Ipupu",description="\nA note you received from Ipupu who\nis out on expedition to the Horutoto\nRuins.\nIt not-so-simply contains an\nexplanation of the glyph that\nHariga-Origa couldn't read.\n",category=2},
[27]={id=27,name="\"Art For Everyone\"",plural="\"Art For Everyone\"",description="\nThe book from the Library of Magic\nthat a Hume named Orn had out on\nloan.\nIt is easy to read, with many\nillustrations, but is thick and heavy.",category=0},
[28]={id=28,name="cracked Mana Orb",plural="cracked Mana Orbs",description="\nA Mana Orb you obtained from the\nHorutoto Ruins.\nIt is fractured, with many large\ncracks in it.\n",category=2},
[29]={id=29,name="Kindred report",plural="Kindred reports",description="\nA report from the consulate, stating\nthat there seems to be a new force\ninfluencing the beastmen from the\nshadows.\n",category=0},
[30]={id=30,name="letter to the ambassador",plural="letters to the ambassador",description="\nAn important document that proves\nyou have been dispatched as an\nenvoy to the embassy in Jeuno.\n",category=2},
[31]={id=31,name="sword offering",plural="sword offerings",description="\nAn offering from Windurst to the\nbeastmen.\nYou received it from Heavens Tower\nwith the instructions to deliver it to\nthe treasure chamber in Giddeus.\n",category=2},
[32]={id=32,name="shield offering",plural="shield offerings",description="\nAn offering from Windurst to the\nbeastmen.\nYou received it from Heavens Tower\nwith the instructions to deliver it to\nthe treasure chamber in Giddeus.\n",category=2},
[33]={id=33,name="dull sword",plural="dull swords",description="\nAn ordinary sword that the Bastokan\nConsulate switched for the real\nsword offering.\nYou seriously wonder whether the\nYagudo of Giddeus will accept this\nor not.\n",category=2},
[34]={id=34,name="dark key",plural="dark keys",description="\nThis key allows you to enter the\ndeepest part of Giddeus in order to\ndefeat the fearsome monster that\nhas appeared there.\n",category=2},
[35]={id=35,name="Adventurer's Certificate",plural="Adventurer's Certificates",description="\nThis certification is given to\nadventurers who have distinguished\nthemselves in all three countries.",category=3},
[36]={id=36,name="Starway Stairway bauble",plural="Starway Stairway baubles",description="\nThis key opens the door\nto the Starway Stairway from the\nClerical Chamber in Heavens Tower.\n",category=2},
[37]={id=37,name="first dark Mana Orb",plural="first dark Mana Orb",description="\nA Mana Orb that the Manustery is\nin charge of maintaining.\nIt hasn't been filled with magic, so\nit doesn't glow.\n",category=0},
[38]={id=38,name="\"Creature Counter\" magic doll",plural="\"Creature Counter\" magic dolls",description="\nA magic doll you received from the\nAurastery. It has a spell cast on it\nthat enables it to count the number\nof monsters that the bearer defeats.\nBe warned that the magic wears off\nafter a certain amount of time!\n",category=2},
[39]={id=39,name="off offering",plural="off offerings",description="\nA bag full of drinks presented to the\nYagudo as a symbol of Windurst's\nfriendship. Chef Ranpi-Monpi, from\nthe Culinarians' Guild, accidentally\nmixed in some apple vinegar,\ncausing it to reek hideously.\n",category=3},
[40]={id=40,name="Windurst Waters scoop",plural="Windurst Waters scoops",description="\n\"The Great Beast...A Life In Ruins?\"\n                    ...by Kyume-Romeh\n The rumors of the great beast, said\nto be sealed inside the Horutoto\nRuins, have died down.\nBut where does the fearsome beast\nreally lie? Kyume-Romeh finds out\nin this exclusive report.\n",category=0},
[41]={id=41,name="Windurst Walls scoop",plural="Windurst Walls scoops",description="\n\"Zubaba's Forbidden Lover\"\n                     ...by Hiwon-Biwon\n The head lady-in-waiting, yes, the\nold battle-axe Zubaba herself, is\nrumored to have a secret lover!\nHow can she, having supposedly\ndevoted herself to the Star Sibyl?\nA reveal-it-all story of forbidden\npassion in the most holy of places.\n",category=0},
[42]={id=42,name="Port Windurst scoop",plural="Port Windurst scoops",description="\n\"Who's Watching the Children?\"\n                             ...by Yujuju\n What is that small group of Tarutaru\nand Mithra children up to in the Port\nArea? Are they a gang of deadbeat\nlayabouts, a front for some crime\nsyndicate, or much worse?\nYujuju goes directly to the source\nand asks...\"Do their mothers know?\"\n",category=0},
[43]={id=43,name="Windurst Woods scoop",plural="Windurst Woods scoops",description="\n\"Where the Cat Burglar Hides her Kitty\"\n                               ...by Umumu\n The Cat Burglar roams free because\nthe stolen booty is never found. When\nCapt. Rakoh Buuma searched her house,\nthere was nothing there. So where does\nthe Cat hide the goods? This reporter\nknows it is hidden deep beneath the\neastern magic tower of the Horutoto\nRuins...maybe...I think...well kinda...?\n",category=0},
[44]={id=44,name="Temple Knights' Davoi report",plural="Temple Knights' Davoi reports",description="\nVital intelligence on Orcish activity\nthroughout Davoi, gathered by the\nTemple Knights.",category=2},
[45]={id=45,name="silver bell",plural="silver bells",description="\nA mythril bell, said to soothe the soul\nof even the fiercest Quadav.\n\nNeeded to open the door to the deeper\nparts of Beadeaux.",category=2},
[46]={id=46,name="coruscant rosary",plural="coruscant rosaries",description="\nA rosary that glows with an eerie light.\nIt has the power to weaken magic\nseals.\n\nNeeded to open the door to the deeper\nparts of Beadeaux.",category=2},
[47]={id=47,name="black matinee necklace",plural="black matinee necklaces",description="\nA long necklace made from dark bone.\nIt has the power to break the\nstrongest magic seals.\n\nNeeded to open the door to the deeper\nparts of Beadeaux.",category=2},
[48]={id=48,name="Ducal Guard's lantern",plural="Ducal Guard's lanterns",description="\nA lantern lent to you by a guard\nin Jeuno.\nHe said that obtaining flames from\nthe four braziers in the stonework\nrooms of the Eldieme Necropolis\nwill banish evil spirits.",category=2},
[49]={id=49,name="Ducal Guard's lantern",plural="Ducal Guard's lanterns",description="\nA lantern lent to you by a guard\nin Jeuno. He said it has the power\nto banish evil spirits.\n\nIt is burning brightly.",category=2},
[50]={id=50,name="holy candle",plural="holy candles",description="\nA candle from the Temple of\nthe Goddess.\n",category=2},
[51]={id=51,name="second dark Mana Orb",plural="second dark Mana Orb",description="\nA Mana Orb that the Manustery is\nin charge of maintaining.\nIt hasn't been filled with magic, so\nit doesn't glow.\n",category=0},
[52]={id=52,name="third dark Mana Orb",plural="third dark Mana Orb",description="\nA Mana Orb that the Manustery is\nin charge of maintaining.\nIt hasn't been filled with magic, so\nit doesn't glow.\n",category=0},
[53]={id=53,name="fourth dark Mana Orb",plural="fourth dark Mana Orb",description="\nA Mana Orb that the Manustery is\nin charge of maintaining.\nIt hasn't been filled with magic, so\nit doesn't glow.\n",category=0},
[54]={id=54,name="fifth dark Mana Orb",plural="fifth dark Mana Orb",description="\nA Mana Orb that the Manustery is\nin charge of maintaining.\nIt hasn't been filled with magic, so\nit doesn't glow.\n",category=0},
[55]={id=55,name="sixth dark Mana Orb",plural="sixth dark Mana Orb",description="\nA Mana Orb that the Manustery is\nin charge of maintaining.\nIt hasn't been filled with magic, so\nit doesn't glow.\n",category=0},
[56]={id=56,name="archducal audience permit",plural="archducal audience permits",description="\nRequired before seeking audience\nwith the Archduke of Jeuno.",category=3},
[57]={id=57,name="super soup pot",plural="super soup pots",description="\nA special cooking pot that can only\nbe obtained from the Culinarians' Guild\nin Windurst.\n",category=2},
[58]={id=58,name="Two of Swords",plural="Two of Swords",description="\nThe Cardian from Panta-Putta's place.\nHe seems to have shut himself down.\n",category=0},
[59]={id=59,name="first glowing Mana Orb",plural="first glowing Mana Orb",description="\nA Mana Orb that the Manustery is\nin charge of maintaining.\nIt has been recharged with magic\nat the Horutoto Ruins, so it glows\nbrilliantly.\n",category=0},
[60]={id=60,name="second glowing Mana Orb",plural="second glowing Mana Orb",description="\nA Mana Orb that the Manustery is\nin charge of maintaining.\nIt has been recharged with magic\nat the Horutoto Ruins, so it glows\nbrilliantly.\n",category=0},
[61]={id=61,name="third glowing Mana Orb",plural="third glowing Mana Orb",description="\nA Mana Orb that the Manustery is\nin charge of maintaining.\nIt has been recharged with magic\nat the Horutoto Ruins, so it glows\nbrilliantly.\n",category=0},
[62]={id=62,name="fourth glowing Mana Orb",plural="fourth glowing Mana Orb",description="\nA Mana Orb that the Manustery is\nin charge of maintaining.\nIt has been recharged with magic\nat the Horutoto Ruins, so it glows\nbrilliantly.\n",category=0},
[63]={id=63,name="fifth glowing Mana Orb",plural="fifth glowing Mana Orb",description="\nA Mana Orb that the Manustery is\nin charge of maintaining.\nIt has been recharged with magic\nat the Horutoto Ruins, so it glows\nbrilliantly.\n",category=0},
[64]={id=64,name="sixth glowing Mana Orb",plural="sixth glowing Mana Orb",description="\nA Mana Orb that the Manustery is\nin charge of maintaining.\nIt has been recharged with magic\nat the Horutoto Ruins, so it glows\nbrilliantly.\n",category=0},
[65]={id=65,name="rescue training certificate",plural="rescue training certificates",description="\nThe bearer of this certificate\nhas successfully completed\nrescue training on the La Theine\nPlateau.\n",category=2},
[66]={id=66,name="charm of light",plural="charms of light",description="\nThe key to opening the door to the\nroom of light beneath the central\ntower of the Horutoto Ruins.\nIt is said that inside this room,\npart of the talisman that seals\nCastle Zvahl is stored.\n",category=0},
[67]={id=67,name="hideout key",plural="hideout keys",description="\nThe key to the Cat Burglar's\nhideout in the Horutoto Ruins.\n",category=0},
[68]={id=68,name="lapis coral",plural="lapis coral",description="\nA piece of coral you found in the\nMaze of Shakhrami that glitters\nlike lapis lazuli.\n",category=2},
[69]={id=69,name="message to Jeuno",plural="messages to Jeuno",description="\n\"Attempted assassination at the\nChateau d'Oraguille.\nRoyaulais unconscious and in poor\ncondition.\nReturn to San d'Oria immediately.\"\n",category=0},
[70]={id=70,name="message to Jeuno",plural="messages to Jeuno",description="\n\"An intruder snuck into the President's\nOffice in Bastok.\nThe President himself was attacked.\nReturn to Bastok immediately.\"\n",category=0},
[71]={id=71,name="message to Jeuno",plural="messages to Jeuno",description="\n\"A grave matter has occurred\nbeneath the central magic tower\nof the Horutoto Ruins, in the\nfacility guarded by Heavens Tower.\nYour instructions are to return to\nWindurst posthaste.\"\n",category=0},
[72]={id=72,name="new Fei'Yin seal",plural="new Fei'Yin seals",description="\nA new magical parchment to replace\nthe old one that is feared to have\nfailed in Fei'Yin.\n",category=0},
[73]={id=73,name="burnt seal",plural="burnt seals",description="\nThe remains of the magical\nparchment that sealed off the lands\nbeyond Fei'Yin twenty years ago.\nIt has lost its power after being\nburned to ashes by a powerful spell.\n",category=2},
[74]={id=74,name="shadow fragment",plural="shadow fragments",description="\nA small part of the\nShadow Lord's body.\nIt still emanates some\nof his dark aura.\n",category=2},
[75]={id=75,name="Ronfaure supplies",plural="Ronfaure supplies",description="\nDeliver these supplies to the guards\nmanning the Ronfaure Outpost\nbefore the next conquest results\nare tallied.\n",category=0},
[76]={id=76,name="Zulkheim supplies",plural="Zulkheim supplies",description="\nDeliver these supplies to the guards\nmanning the Zulkheim Outpost\nbefore the next conquest results\nare tallied.\n",category=0},
[77]={id=77,name="Norvallen supplies",plural="Norvallen supplies",description="\nDeliver these supplies to the guards\nmanning the Norvallen Outpost\nbefore the next conquest results\nare tallied.\n",category=0},
[78]={id=78,name="Gustaberg supplies",plural="Gustaberg supplies",description="\nDeliver these supplies to the guards\nmanning the Gustaberg Outpost\nbefore the next conquest results\nare tallied.\n",category=0},
[79]={id=79,name="Derfland supplies",plural="Derfland supplies",description="\nDeliver these supplies to the guards\nmanning the Derfland Outpost\nbefore the next conquest results\nare tallied.\n",category=0},
[80]={id=80,name="Sarutabaruta supplies",plural="Sarutabaruta supplies",description="\nDeliver these supplies to the guards\nmanning the Sarutabaruta Outpost\nbefore the next conquest results\nare tallied.\n",category=0},
[81]={id=81,name="Kolshushu supplies",plural="Kolshushu supplies",description="\nDeliver these supplies to the guards\nmanning the Kolshushu Outpost\nbefore the next conquest results\nare tallied.\n",category=0},
[82]={id=82,name="Aragoneu supplies",plural="Aragoneu supplies",description="\nDeliver these supplies to the guards\nmanning the Aragoneu Outpost\nbefore the next conquest results\nare tallied.\n",category=0},
[83]={id=83,name="Fauregandi supplies",plural="Fauregandi supplies",description="\nDeliver these supplies to the guards\nmanning the Fauregandi Outpost\nbefore the next conquest results\nare tallied.\n",category=0},
[84]={id=84,name="Valdeaunia supplies",plural="Valdeaunia supplies",description="\nDeliver these supplies to the guards\nmanning the Valdeaunia Outpost\nbefore the next conquest results\nare tallied.\n",category=0},
[85]={id=85,name="Li'Telor supplies",plural="Li'Telor supplies",description="\nDeliver these supplies to the guards\nmanning the Li'Telor Outpost\nbefore the next conquest results\nare tallied.\n",category=0},
[86]={id=86,name="Kuzotz supplies",plural="Kuzotz supplies",description="\nDeliver these supplies to the guards\nmanning the Kuzotz Outpost\nbefore the next conquest results\nare tallied.\n",category=0},
[87]={id=87,name="Vollbow supplies",plural="Vollbow supplies",description="\nDeliver these supplies to the guards\nmanning the Vollbow Outpost\nbefore the next conquest results\nare tallied.\n",category=0},
[88]={id=88,name="lapis monocle",plural="lapis monocles",description="\nAn eyeglass lent to you by Nanaa\nMihgo. Looking through this\nsupposedly enables the wearer to\ndetect the existence of lapis coral.\n",category=2},
[89]={id=89,name="donation envelope",plural="donation envelopes",description="\nA bulky envelope addressed to Arnau.\nFind him in the cathedral.\n",category=2},
[90]={id=90,name="Aragoneu pizza",plural="Aragoneu pizzas",description="\nBaked by Rycharde, chef of Mhaura.",category=3},
[91]={id=91,name="land crab bisque",plural="land crab bisque",description="\nCooked by Valgeir, chef of Selbina.",category=4},
[92]={id=92,name="Mhauran couscous",plural="Mhauran couscous",description="\nMade by Rycharde, chef of Mhaura.",category=4},
[93]={id=93,name="etched ring",plural="etched rings",description="\nA shining silver ring with a name\nengraved on the inside.",category=3},
[94]={id=94,name="trader's sack",plural="trader's sacks",description="\nProperty of two merchants, Serafin\nand Evrard, before they were captured\nby the Quadav. Deliver to Thunder Hawk.",category=2},
[95]={id=95,name="fake moustache",plural="fake moustaches",description="\nA false moustache made from Saruta\nCotton that has been scorched by\nmagic. It is fuzzy-wuzzy to the touch\nand has a splendid handlebar shape.\nIt really makes you look like a world-\nrenowned detective.\n",category=2},
[96]={id=96,name="Gardenia pass",plural="Gardenia passes",description="\n\"The bearer of this sigil\nshall be allowed access\nthrough Ranguemont Pass.\"",category=2},
[97]={id=97,name="weapons order",plural="weapons orders",description="\nAn order for a weapons trader named\nAlexius. Find him somewhere in\nJugner Forest.\n",category=2},
[98]={id=98,name="weapons receipt",plural="weapons receipts",description="\nAn order confirmation for Helbort's\nBlades in Southern San d'Oria.",category=2},
[99]={id=99,name="small bag",plural="small bags",description="\nA small bag of unknown contents,\npicked up in Mhaura at the request\nof the Rhinostery staff in Windurst.\n\"Handle with care!\" is written on it\nin bold letters.\n",category=2},
[100]={id=100,name="Ranpi-Monpi's special stew",plural="Ranpi-Monpi's special stew",description="\nA special stew that the Culinarians'\nGuild chef, Ranpi-Monpi, made to the\nbest of his cookery skill.\nIt has been carefully prepared from\n32 select ingredients and smells\nabsolutely delicious. However, it\ndoesn't look like something a person\nwould dare eat...\n",category=2},
[101]={id=101,name="ferry ticket",plural="ferry tickets",description="\nA ticket that allows you to board\nthe ferry ship between Mhaura and\nSelbina, or Mhaura and Al Zahbi.",category=2},
[102]={id=102,name="stamp sheet",plural="stamp sheets",description="\n\"Discover Bastok! Get stamps from\nthe guards stationed near the off-\nlimits area and the small archway in\nthe Mines District, the West Gate in\nthe Markets District, the drawbridge\nand bottom doors of the warehouses,\nthe Goddess statue, and the Cannonry\nin the Metalworks.\"",category=2},
[103]={id=103,name="lost document",plural="lost documents",description="\nThis is the last page\nof the Davoi Report.",category=0},
[104]={id=104,name="East Block code",plural="East Block codes",description="\nA note with codes for the\nEast Block of Davoi.\n",category=0},
[105]={id=105,name="South Block code",plural="South Block codes",description="\nA note with codes for the\nSouth Block of Davoi.\n",category=0},
[106]={id=106,name="North Block code",plural="North Block codes",description="\nA note with codes for the\nNorth Block of Davoi.\n",category=0},
[107]={id=107,name="letter from Roh Latteh",plural="letters from Roh Latteh",description="\n\"Dear Mom,\nThank you for all the presents\nyou bring me, I like them a lot...but\nI'd be more happy if you came home\nearly sometimes, even if you don't\nbring me back anything.\"\n                              -Roh",category=2},
[108]={id=108,name="painting of a windmill",plural="paintings of a windmill",description="\nThis painting of a windmill is painted\nwith a unique touch, but it is in\nvery bad condition.",category=2},
[109]={id=109,name="tattered mission orders",plural="tattered mission orders",description="\nOrders apparently issued by San d'Oria.\nThe writing is no longer legible.",category=0},
[110]={id=110,name="Monastic Cavern key",plural="Monastic Cavern keys",description="\nA key that opens a door in the\nMonastic Caverns in Davoi.",category=0},
[111]={id=111,name="moon crystal",plural="moon crystals",description="\nThis is needed to pass through\nthe gate that only opens at a certain\ndate and time.",category=2},
[112]={id=112,name="southeastern star charm",plural="southeastern star charms",description="\nA key to the laboratory that lies\nbeneath the southeastern magic\ntower of the Horutoto Ruins.\nIt magically disappears upon use.\n",category=2},
[113]={id=113,name="Wonder Magic Set",plural="Wonder Magic Sets",description="\nThis set rivals Airship Stamp Rally\nfor the hearts of kids everywhere.",category=2},
[114]={id=114,name="unfinished letter",plural="unfinished letters",description="\n\"Dear Cid,\nI'm soon going to be able to open\nthat restaurant I told you about.\nI'm glad you accepted my resignation.\nI regret not being able to help you\nwith your work anymore, but I'm sure\nthere are plenty of engineers--\"\nThe letter ends here.",category=3},
[115]={id=115,name="new model hat",plural="new model hats",description="\nThe latest in headwear fashion by\nBaren-Moren the hatter, who has\nasked you to advertise it to the\nlocal townsfolk. It has a feather on\none side and is really quite stylish.\n",category=2},
[116]={id=116,name="Angelica's autograph",plural="Angelica's autographs",description="\nThe signature of the artist Angelica,\nwho is staying at the hostelry in\nWindurst Waters.\nYou aren't sure which way is up.\n",category=0},
[117]={id=117,name="old tiger's fang",plural="old tiger's fangs",description="\nA fang you plucked from the carcass\nof a tiger.\n",category=3},
[118]={id=118,name="Tenshodo Member's Card",plural="Tenshodo Member's Cards",description="\nPlease present this card to gain\naccess to the Tenshodo.",category=2},
[119]={id=119,name="receipt for the prince",plural="receipts for the prince",description="\nA receipt from the armorer.\nThe customer's name is written so\nflamboyantly, it is completely illegible.",category=0},
[120]={id=120,name="magic trash",plural="magic trash",description="\nChululu forgot to put this out on\nmagic trash day.",category=4},
[121]={id=121,name="Tenshodo application form",plural="Tenshodo application forms",description="\nAn application for the exclusive shop,\nthe Tenshodo. Take it to\nheadquarters to become a member.",category=2},
[122]={id=122,name="sharp gray stone",plural="sharp gray stones",description="\nA rock you received from the Cat\nBurglar. At first glance it seems like\nany other gray stone, but on closer\ninspection you can see that it\nsparkles when held at certain angles.\nIt must contain traces of some metal.\n",category=2},
[123]={id=123,name="cathedral donation",plural="cathedral donations",description="\nA great sum of money from\nMadame Hinaree.",category=2},
[124]={id=124,name="Qufim supplies",plural="Qufim supplies",description="\nDeliver these supplies to the guards\nmanning the Qufim Outpost\nbefore the next conquest results\nare tallied.",category=4},
[125]={id=125,name="tattered test sheet",plural="tattered test sheets",description="\nA torn and tattered answer sheet.\nYou can't tell whose test it was, but\nProfessor Koru-Moru has written the\nfollowing on it:\n\"Learn from your mistakes, and never\ntry and cover one wrong with another.\nThink about what you've done.\"\n",category=2},
[126]={id=126,name="\"A Song of Love\"",plural="\"A Song of Love\"",description="\nA romance novel with the picture of\na man and a woman making out under\nthe moonlight. It has the blurb:\n\"They thought only the moon bore\n witness to their forbidden love,\n until one fateful night...\"\n",category=0},
[127]={id=127,name="Steaming Sheep invitation",plural="Steaming Sheep invitations",description="\n\"Dear Sir,\nThank you for visiting us the other\nday. We have been able to procure\nthe ingredients for that dish you\nordered.\nPlease drop by the Steaming Sheep\nRestaurant whenever you have time.\"\n                              -Hilda",category=2},
[128]={id=128,name="broken wand",plural="broken wands",description="\nA snapped wand you received from\nMashira at the magic incinerator in\nGarlaige Citadel. It looks like some-\none used too much force and broke\nit. It is probably worthless, but the\nMinister of the Orastery is said to\nbe attached to it for some reason.\n",category=2},
[129]={id=129,name="Gulemont's document",plural="Gulemont's documents",description="\nA bond dropped by Gulemont. Find\nhim in the tavern in Port San d'Oria.",category=2},
[130]={id=130,name="old ring",plural="old rings",description="\nAn old ring found in Castle Oztroja.\nIt seems to be engraved with the\nseal of the Optistery in Windurst.",category=3},
[131]={id=131,name="white orb",plural="white orbs",description="\nAn orb from the mage in Davoi. Place\nit into four red pools around Davoi.\n",category=2},
[132]={id=132,name="pink orb",plural="pink orbs",description="\nThe orb from the mage in Davoi.\nIt has absorbed magic from one\nred pool.\n",category=2},
[133]={id=133,name="red orb",plural="red orbs",description="\nThe orb from the mage in Davoi.\nIt has absorbed magic from two\nred pools.\n",category=2},
[134]={id=134,name="blood orb",plural="blood orbs",description="\nThe orb from the mage in Davoi.\nIt has absorbed magic from three\nred pools.\n",category=2},
[135]={id=135,name="cursed orb",plural="cursed orbs",description="\nThe orb from the mage in Davoi.\nIt is now cursed by the magic\nof the red pools.\n",category=2},
[136]={id=136,name="crimson orb",plural="crimson orbs",description="\nThe orb from the mage in Davoi.\nIt now has the power to break\nthe seal at the far end of Davoi.\n",category=2},
[137]={id=137,name="key to the Oztroja mines",plural="keys to the Oztroja mines",description="\nA key taken from the Yagudo guarding\nthe mines of Castle Oztroja.",category=2},
[138]={id=138,name="chocobo license",plural="chocobo licenses",description="\nThis license is issued to certified\nchocobo riders.\n\nValid until the end of time.",category=2},
[139]={id=139,name="cursepaper",plural="cursepaper",description="\nThis paper copies the effects of any\ncurse its holder receives.",category=2},
[140]={id=140,name="corrupted dirt",plural="corrupted dirt",description="\nA clump of dirt sampled from\na polluted patch of earth in\nBeadeaux.",category=4},
[141]={id=141,name="stalactite dew",plural="stalactite dew",description="\nA drop of condensation from a\nstalactite in Ordelle's Caves.\n",category=4},
[142]={id=142,name="squire certificate",plural="squire certificates",description="\nThe bearer of this certificate is\nhereby recognized as a squire,\nwith all its rights and privileges.",category=2},
[143]={id=143,name="Book of Tasks",plural="Book of Tasks",description="\nThe greatest knights in all the land\nAre watched by others from high nest.\nThe watchers know the task at hand.\nWhen lost go East to know the West.",category=0},
[144]={id=144,name="Book of the East",plural="Book of the East",description="\nFrom the island lake,\nSouth runs the flow.\nWhere it goes,\nOnly beastmen know.",category=0},
[145]={id=145,name="Book of the West",plural="Book of the West",description="\nThere is one whose body breaks.\nDeath it deals and death it reaps.\nAnd in the sky a beacon makes,\nWhere it sits, the knight's soul sleeps.",category=0},
[146]={id=146,name="knight's soul",plural="knight's soul",description="\nThe blade of this ancient\nsword has melted away.",category=0},
[147]={id=147,name="cold medicine",plural="cold medicine",description="\nThe old woman's medicine.\nIt works like magic on colds.\n",category=4},
[148]={id=148,name="Amaura's formula",plural="Amaura's formula",description="\nCold Medicine Formula:\n One chunk of zinc ore\n One insect wing\n One malboro vine\n",category=0},
[149]={id=149,name="overdue book notification",plural="overdue book notifications",description="\nThis letter reads:\n\"This is your final notification to return\nthe following overdue library book to\nthe Optistery's Library of Magic:\n  'A Song of Love'\nFailure to return this book immediately\nwill result in a string of fearsome\ncurses being cast in your direction.\nYours sinisterly,\n  Tosuka-Porika, Librarian.\"",category=3},
[150]={id=150,name="Scripture of Water",plural="Scripture of Water",description="\nThe content of this scripture\nis too cryptic for you to decipher.",category=0},
[151]={id=151,name="Scripture of Wind",plural="Scripture of Wind",description="\nThe content of this scripture\nis too cryptic for you to decipher.",category=0},
[152]={id=152,name="Tami's note",plural="Tami's notes",description="\n\"Go to the Bat's Lair Inn\nand buy us the usual thing.\n\n              -Tami\"",category=0},
[153]={id=153,name="thyme moss",plural="thyme moss",description="\nThis moss thrives in dark, damp places.\nIt helps suppress coughs, apparently.\n",category=4},
[154]={id=154,name="cough medicine",plural="cough medicine",description="\nA concoction from that old woman,\nAmaura.\n",category=4},
[155]={id=155,name="scroll of treasure",plural="scrolls of treasure",description="\nWest is a gate,\n North lies a stream.\nStand on the spot\n To see what I mean.",category=2},
[156]={id=156,name="Code of Beastmasters",plural="Code of Beastmasters",description="\nAll who would command beasts of\nnature must heed the wisdom\ninscribed herein.\n",category=0},
[157]={id=157,name="Orcish hut key",plural="Orcish hut keys",description="\nThe key to a small hut\nin the Ghelsba Outpost.",category=3},
[158]={id=158,name="star crested summons",plural="star crested summons",description="\nA writ of summons with the emblem\nof a white star on it. The cursive\nwriting on it twinkles like starlight.\nIt reads:\n \"Your presence is requested\n immediately at the Vestal\n Chambers of Heavens Tower.\"\n",category=2},
[159]={id=159,name="Brugaire goods",plural="Brugaire goods",description="\nContraband from Portaure of the\nBrugaire Consortium. If caught,\nsmugglers face temporary suspension\nof airship boarding rights, so be\ncareful.\n",category=0},
[160]={id=160,name="small teacup",plural="small teacups",description="\nA beautifully-decorated teacup.\nIt is marked with a family crest.\n",category=2},
[161]={id=161,name="suspicious envelope",plural="suspicious envelopes",description="\nA white envelope without name or\naddress. Take it to Monarlais Halver.\n",category=2},
[162]={id=162,name="carrier pigeon letter",plural="carrier pigeon letters",description="\n\"Does your heart still long\n              for the stars of Ifrit,\nWhile my soul lingers\n     on the ground far beneath...?\"\n                              -Carmelo",category=2},
[163]={id=163,name="Carmelo's song sheet",plural="Carmelo's song sheets",description="\nA capriccio titled \"Love and Ice\"\nwritten by the bard Carmelo.\nIt is dedicated to someone named\nDariah.",category=0},
[164]={id=164,name="Curilla's bottle",plural="Curilla's bottles",description="\nA bottle from General Curilla.\nFill it at the hot spring that\nflows from the Horlais Peak.",category=0},
[165]={id=165,name="Curilla's bottle",plural="Curilla's bottles",description="\nThe bottle from General Curilla.\nIt is full of water from the hot spring\nthat flows from the Horlais Peak.",category=0},
[166]={id=166,name="neutralizer",plural="neutralizers",description="\nA neutralizer for poison,\nkindly concocted by Novalmauge.\n",category=0},
[167]={id=167,name="goldsmithing order",plural="goldsmithing orders",description="\n\"For the procurement of a fine work\nof mythril, traditional in form but\nnovel in spirit.\"\n                               -Femitte\n",category=2},
[168]={id=168,name="mythril hearts",plural="mythril hearts",description="\nA pendant crafted by the goldsmith\nMichea.\nThe emblems of Bastok and San d'Oria\nare etched side by side.",category=0},
[169]={id=169,name="testimonial",plural="testimonials",description="\n\"This certifies that you have gathered\nno less than ten thousand carp.\nPlease spend your time in a manner\nmore beneficial to society.\nYour achievement is noteworthy\nfor its utter lack of meaning.\"\n\n            With heartfelt disapproval,\n            Gallijaux & Joulet",category=2},
[170]={id=170,name="letter from Zeid",plural="letters from Zeid",description="\n\"Make your blade shine with even\ndeeper darkness, and go to the lost\nmines. Once there, drown your blade\nin the waters that call the horrid\nbeast. Only then shall I give you the\npower you so thirst for. If you lose\nyour blade, go to the place we met,\nand it shall find you.\"      -Zeid",category=0},
[171]={id=171,name="Shantotto's new spell",plural="Shantotto's new spells",description="\nA new and improved black magic spell\nthat Doctor Shantotto modified.\nIt looks like it still has its magical\npower.\n",category=0},
[172]={id=172,name="Shantotto's ex-spell",plural="Shantotto's ex-spells",description="\nA new and improved black magic spell\nthat Doctor Shantotto modified...or\nwhat's left of it, now that it has lost\nits magical power...\n",category=0},
[173]={id=173,name="bucket of divine paint",plural="buckets of divine paint",description="\nA bucket of special paint you found\nin the Garlaige Citadel.\nIt is needed to restore the statue\nof Altana to Her former glory.",category=2},
[174]={id=174,name="letter from Virnage",plural="letters from Virnage",description="\nA letter of introduction from Friar\nVirnage to Eperdur in the cathedral.",category=0},
[175]={id=175,name="spirit incense",plural="spirit incense",description="\nIncense created by the friar,\nGantineux. It has the power to calm\nthe souls of revenants.",category=2},
[176]={id=176,name="Gantineux's letter",plural="Gantineux's letters",description="\nA letter of introduction from Friar\nGantineux to Eperdur in the cathedral.",category=0},
[177]={id=177,name="seal of banishing",plural="seals of banishing",description="\nA seal to banish the miasma of the\ndead through the white magic of\nthe San d'Orian Cathedral.",category=2},
[178]={id=178,name="magical pattern",plural="magical patterns",description="\nA magical pattern that models itself\nto fit the person who finds it.\n",category=2},
[179]={id=179,name="Fei'Yin magic tome",plural="Fei'Yin magic tomes",description="\nA tome of ancient magic that you\nfound in the depths of Fei'Yin.",category=0},
[180]={id=180,name="\"Sluice Surveyor Mk. I\"",plural="\"Sluice Surveyor Mk. I\"",description="\nA magic doll entrusted to you\nby Professor Koru-Moru.\nIt has been modified to help\nsurvey the Toraimarai Canal.\nIt doesn't talk much, but makes a\nlot of annoying beeping sounds.\n",category=2},
[181]={id=181,name="\"Foe Finder Mk. I\"",plural="\"Foe Finder Mk. I\"",description="\nThe magic doll that was shut up\ninside of Castle Zvahl.\nTwenty years ago it was the life of\nDoctor Shantotto's exploration party\n...or so it thought.\n",category=2},
[182]={id=182,name="earthen charm",plural="earthen charms",description="\nThe key to the Gate of Earth that\nexists below the central tower of\nthe Horutoto Ruins.\n",category=3},
[183]={id=183,name="letter from the Tenshodo",plural="letters from the Tenshodo",description="\n\"Thief of renown, I have a job for you.\nPayment will be an item of premium\nquality. Let's make a deal that is\nmutually beneficial.\"\n\n               Vauderame of the Tenshodo",category=2},
[184]={id=184,name="Tenshodo envelope",plural="Tenshodo envelopes",description="\nA sealed document. It reads:\n\"I hereby enter into contract with\nthe Tenshodo.\"\nFor some reason, there is no signature.\nThe package is addressed to Sneaking\nTiger.",category=2},
[185]={id=185,name="signed envelope",plural="signed envelopes",description="\nA document with Sneaking Tiger's\nsignature. A new clause was added to\nthe end. It reads, \"I agree to all of\nthe above. Signed, V.\"",category=2},
[186]={id=186,name="gang whereabouts note",plural="gang whereabouts notes",description="\nA note you received from Nanaa Mihgo.\nIt has the whereabouts of the two\nremaining members of Atarefaunet's\nband of thieves written on it.\nThe first is at the top of an old\ntower on the Sauromugue Champaign.\nThe second is at the Goblins' Goblet\nin Jeuno.\n",category=2},
[187]={id=187,name="first forged envelope",plural="first forged envelope",description="\nDocuments forged by Nanaa Mihgo.\nThey're so well done that you cannot\ntell the difference between this and\nthe Tenshodo's original envelope and\nletter.",category=0},
[188]={id=188,name="second forged envelope",plural="second forged envelope",description="\nDocuments forged by Nanaa Mihgo.\nThey're so well done that you cannot\ntell the difference between this and\nthe Tenshodo's original envelope and\nletter.",category=0},
[189]={id=189,name="first signed forged envelope",plural="first signed forged envelope",description="\nForged documents signed by Linzaza,\none of the few remaining infamous\ngang members, whom you found at the\ntop of a tower on the Sauromugue\nChampaign.\n",category=0},
[190]={id=190,name="second signed forged envelope",plural="second signed forged envelope",description="\nForged documents signed by Pauluart,\none of the few remaining infamous\ngang members, whom you gambled\nwith at dice in Jeuno.\n",category=0},
[191]={id=191,name="letter from Dalzakk",plural="letters from Dalzakk",description="\n\"Please retrieve the 'San d'Orian\nmartial arts scroll' from a tent\nin Davoi, then bring it to my master,\nOggbi.\"\n                           -Dalzakk",category=2},
[192]={id=192,name="San d'Orian martial arts scroll",plural="San d'Orian martial arts scrolls",description="\nThe content of this scroll\ndescribes in detail a form of\nmartial art practiced by the\npeople of San d'Oria.",category=0},
[193]={id=193,name="bomb incense",plural="bomb incense",description="\nA little something from Hagain, the\nold Tenshodo thief from the Sailor's\nStay in Mhaura.\nThis is needed to smoke out bomb\nmonsters from the ceiling of the\nGarlaige Citadel.\n",category=2},
[194]={id=194,name="Perchond's envelope",plural="Perchond's envelopes",description="\nAn envelope containing \"glittersand\"\nthat you were asked to find by a\nknight called Perchond at the\nRanguemont Pass.\nSir Perchond has also included a\npersonal letter, addressed to Semih\nLafihna.\n",category=0},
[195]={id=195,name="portal charm",plural="portal charms",description="\nA key that allows you to enter the\nSealed Portal beneath the central\ntower of the Horutoto Ruins\nby yourself.",category=2},
[196]={id=196,name="Orcish dried food",plural="Orcish dried food",description="\nOrcish rations left to dry. While edible,\nthey do not look appetizing.",category=4},
[197]={id=197,name="old pocket watch",plural="old pocket watches",description="\nCurilla's father, the red mage\nRainemard, once used this watch.\nIt ticks no more.",category=3},
[198]={id=198,name="old boots",plural="old boots",description="\nThese boots were given in return for\nthe old watch. For some reason, they\nrefuse to be worn.",category=4},
[199]={id=199,name="Balga champion certificate",plural="Balga champion certificates",description="\nA certificate that testifies the\nholder's victory over the Yagudo\nchampion at the Balga Contest.\nThe certificate is signed by Kaa\nToru the Just.",category=2},
[200]={id=200,name="Holy One's oath",plural="Holy One's oath",description="\nA document received from Kaa Toru\nthe Just. This document, written by\nthe Yagudo Holy One, is addressed\nto the Star Sibyl of Windurst, and\ncontains details pertaining to the\nOztroja offerings.",category=0},
[201]={id=201,name="crawler blood",plural="crawler blood",description="\nBlood believed to cleanse the foulest\nof things when poured on the earth of\nthe Crawlers' Nest.\n",category=4},
[202]={id=202,name="Cat Burglar's note",plural="Cat Burglar's notes",description="\nA memo you received from Nanaa\nMihgo. It gives the whereabouts of\ntwo of the eight thieves from the\nTenshodo:\n ・ Yatniel is casing the shop,\n    'Gems by Kshama,' in Jeuno.\n ・ Hagain is resting at the\n    Sailor's Stay in Mhaura.\n",category=2},
[203]={id=203,name="chieftainness's twinstone earring",plural="chieftainness's twinstone earrings",description="\nOne of the pair of matching twin-\nstone earrings that the Mithra tribal\nchieftainness, Perih Vashai, entrusted\nyou with.\nYou have been asked to hand it to\nSemih Lafihna.\n",category=0},
[204]={id=204,name="northern vine",plural="northern vines",description="\nA rough-skinned vine taken from the\nnorthern side of the Firebloom Tree.",category=2},
[205]={id=205,name="southern vine",plural="southern vines",description="\nA smooth-skinned vine taken from the\nsouthern side of the Firebloom Tree.",category=2},
[206]={id=206,name="eastern vine",plural="eastern vines",description="\nA shiny-skinned vine taken from the\neastern side of the Firebloom Tree.",category=3},
[207]={id=207,name="western vine",plural="western vines",description="\nA prickly-skinned vine taken from the\nwestern side of the Firebloom Tree.",category=2},
[208]={id=208,name="sword grip material",plural="sword grip material",description="\nA rare material used to strengthen\nsword hilts.",category=4},
[209]={id=209,name="Yasin's sword",plural="Yasin's swords",description="\nA sword that belonged to Phara's son.\nShe has asked you to deliver it\nto her grandson, \"Naji the Doorman.\"",category=0},
[210]={id=210,name="old gauntlets",plural="old gauntlets",description="\nA pair of old and filthy gauntlets.\nEven if you could, you wouldn't\nwant to equip them.",category=4},
[211]={id=211,name="shadow flames",plural="shadow flames",description="\nFlames from a torch in Castle Zvahl.\nBorghertz has asked you to bring these\nto him.",category=4},
[212]={id=212,name="Firebloom Tree wood",plural="Firebloom Tree wood",description="\nWood from the Firebloom Tree\nlocated in the Yuhtunga Jungle.\nThis special material will not burn,\neven in the hottest of flames.",category=4},
[213]={id=213,name="letter to Angelica",plural="letters to Angelica",description="\nA letter written by Kazham\nchieftainness Jakoh Wahcondalo to\nthe Windurstian artist, Angelica.\nIt explains, in detail, the horrors that\nlie within the Temple of Uggalepih.",category=2},
[214]={id=214,name="\"Final Fantasy\"",plural="\"Final Fantasy\"",description="\nA powerful painting done by the\naspiring young artist, Angelica.\nAccording to her, it is her most\nmoving piece to date.",category=0},
[215]={id=215,name="ripped \"Final Fantasy\" painting",plural="ripped \"Final Fantasy\" painting",description="\nThe torn remains of Angelica's\n\"most moving piece to date.\"",category=2},
[216]={id=216,name="\"Final Fantasy Part II\"",plural="\"Final Fantasy Part II\"",description="\nAn even more powerful painting done\nby the aspiring young artist, Angelica.\nObviously, it was not the \"final\"\n\"Final Fantasy.\"",category=0},
[217]={id=217,name="tamer's whistle",plural="tamer's whistles",description="\nA whistle used in ancient times to\ntame the most ferocious beasts.",category=2},
[218]={id=218,name="knight's boots",plural="knight's boots",description="\nA pair of boots you found in the\nbowels of a fish. They're too filthy\nand worn to wear.",category=4},
[219]={id=219,name="Mique's paintbrush",plural="Mique's paintbrushes",description="\nThe brush used by legendary artist\nMique. Desired by painters everywhere.",category=2},
[220]={id=220,name="strange sheet of paper",plural="strange sheets of paper",description="\nIt appears to be blank.",category=2},
[221]={id=221,name="knight's confession",plural="knight's confessions",description="\nA secret letter from Royal Knight\nChursarlaud to his captain, Exoroche.\nIn it, he confesses to conspiring with\nhis fellow knight Vilbert to betray the\nknights. The words appear only when\nsoaked with water from the Orcs' well.",category=2},
[222]={id=222,name="round frigicite",plural="round frigicite",description="\nA piece of frigicite found in a dark\ncave in Xarcabard.",category=2},
[223]={id=223,name="square frigicite",plural="square frigicite",description="\nA piece of frigicite found in a dark\ncave in Xarcabard.",category=2},
[224]={id=224,name="triangular frigicite",plural="triangular frigicite",description="\nA piece of frigicite found in a dark\ncave in Xarcabard.",category=2},
[225]={id=225,name="star ring",plural="star rings",description="\nA ring given to you by the spirit of\na bard in the Eldieme Necropolis.\nIt is too tarnished to read\nthe inscription.",category=2},
[226]={id=226,name="star ring",plural="star rings",description="\nA ring given to you by the spirit of\na bard in the Eldieme Necropolis.\nYou cannot decipher the inscription\non it.",category=2},
[227]={id=227,name="moon ring",plural="moon rings",description="\nThis ring was formerly owned by\na queen of San d'Oria.\nIt is a pair with the star ring.",category=2},
[228]={id=228,name="Mertaire's bracelet",plural="Mertaire's bracelets",description="\nA bracelet given to Mertaire\nby a lost love.",category=0},
[229]={id=229,name="aquaflora",plural="aquafloras",description="\nA flower offered to the spirits of\nanimals that died in battle.\nOne of a set of three.",category=3},
[230]={id=230,name="aquaflora",plural="aquafloras",description="\nA flower offered to the spirits of\nanimals that died in battle.\nOne of a set of three.",category=3},
[231]={id=231,name="aquaflora",plural="aquafloras",description="\nA flower offered to the spirits of\nanimals that died in battle.\nOne of a set of three.",category=3},
[232]={id=232,name="guiding bell",plural="guiding bells",description="\nThis bell is believed to guide\nthe souls of pets to Paradise.",category=2},
[233]={id=233,name="Ordelle whetstone",plural="Ordelle whetstones",description="\nA stone from Ordelle's Caves.\nCan make even the dullest blade razor-\nsharp. Prized by chefs everywhere.",category=3},
[234]={id=234,name="letter from the Darksteel Forge",plural="letters from the Darksteel Forge",description="\nThis letter requests for the book \non darksteel manufacturing to be \nreturned to the forge.",category=2},
[235]={id=235,name="\"Darksteel Formula\"",plural="\"Darksteel Formula\"",description="\nA Galkan book describing the intricate\nprocess of manufacturing darksteel.\nThe author's name is Gerwitz.",category=0},
[236]={id=236,name="Koh's letter",plural="Koh's letters",description="\nA letter from Koh Lenbalalako\nof Mhaura. A gold earring is enclosed.",category=2},
[237]={id=237,name="Royal Knights' Davoi report",plural="Royal Knights' Davoi reports",description="\nVital intelligence on Orcish activity\nthroughout Davoi, gathered by the\nRoyal Knights.",category=0},
[238]={id=238,name="Sacrificial Chamber key",plural="Sacrificial Chamber keys",description="\nThis key opens the door to the\nSacrificial Chamber located deep in\nthe Temple of Uggalepih.\nIt was entrusted to you by the Kazham\nchieftainness, Jakoh Wahcondalo.",category=2},
[239]={id=239,name="fire fragment",plural="fire fragments",description="\nThis crystal fragment, retrieved from\nthe cermet headstone in the Yuhtunga\nJungle, glows red with the power of\nfire.\nThere are eight fragments in total.",category=2},
[240]={id=240,name="water fragment",plural="water fragments",description="\nThis crystal fragment, retrieved from\nthe cermet headstone in the La\nTheine Plateau, glows blue with the\npower of water.\nThere are eight fragments in total.",category=2},
[241]={id=241,name="earth fragment",plural="earth fragments",description="\nThis crystal fragment, retrieved from\nthe cermet headstone in the\nWestern Altepa Desert, glows yellow\nwith the power of earth.\nThere are eight fragments in total.",category=3},
[242]={id=242,name="wind fragment",plural="wind fragments",description="\nThis crystal fragment, retrieved from\nthe cermet headstone in Cape\nTeriggan, glows green with the power\nof wind.\nThere are eight fragments in total.",category=2},
[243]={id=243,name="lightning fragment",plural="lightning fragments",description="\nThis crystal fragment, retrieved from\nthe cermet headstone in the\nBehemoth's Dominion, glows purple\nwith the power of lightning.\nThere are eight fragments in total.",category=2},
[244]={id=244,name="ice fragment",plural="ice fragments",description="\nThis crystal fragment, retrieved from\nthe cermet headstone in the Cloister\nof Frost, glows blue with the power\nof ice.\nThere are eight fragments in total.",category=3},
[245]={id=245,name="light fragment",plural="light fragments",description="\nThis crystal fragment, retrieved from\nthe cermet headstone in the\nSanctuary of Zi'Tah, glows white\nwith the power of light.\nThere are eight fragments in total.",category=2},
[246]={id=246,name="dark fragment",plural="dark fragments",description="\nThis crystal fragment, given to you\nby Grav'iton, glows with the power\nof darkness.\nThere are eight fragments in total.",category=2},
[247]={id=247,name="prismatic fragment",plural="prismatic fragments",description="\nThis crystal fragment, given to you\nby the Dawnmaidens, glows with all\nthe colors of the rainbow.",category=2},
[248]={id=248,name="southwestern star charm",plural="southwestern star charms",description="\nA key to the laboratory that lies\nbeneath the southwestern magic\ntower of the Horutoto Ruins.\nIt magically disappears upon use.\n",category=2},
[249]={id=249,name="Holy One's invitation",plural="Holy One's invitations",description="\nAn invitation to the Balga Contest\nheld at the Balga's Dais in Giddeus.\nBalga's Dais cannot be entered\nwithout this invitation.",category=2},
[250]={id=250,name="Optistery ring",plural="Optistery rings",description="\nThe ring entrusted to the Minister\nof the Optistery. It bears the\nOptistery's mark.",category=0},
[251]={id=251,name="blank Book of the Gods",plural="blank Book of the Gods",description="\nThe Optistery minister, Tosuka-Porika,\nhas entrusted you with this Book of\nthe Gods that has gone blank.",category=2},
[252]={id=252,name="Book of the Gods",plural="Book of the Gods",description="\nSome of the magical properties of this\nbook have been restored by a wise\nwoman whom you met at the Temple\nof Uggalepih. You sense an evil force\nrunning through the book, but it is not\nstrong enough to cause any fatalities.",category=2},
[253]={id=253,name="Nonberry's knife",plural="Nonberry's knives",description="\nA knife found on a Tonberry\ncook in Temple of Uggalepih.\nIt can cut almost anything!",category=2},
[254]={id=254,name="sublime statue of the Goddess",plural="sublime statues of the Goddess",description="\nA statue of the Dawn Goddess, made\nby the sculptor Mulaujeant from a slab\nof Elshimo marble. The sheer beauty\nof this masterpiece strikes a chord in\nthe hearts of all who lay their eyes\nupon it.",category=2},
[255]={id=255,name="Rauteinot's parcel",plural="Rauteinot's parcels",description="\nA parcel from Rauteinot, a young\nmissionary sent to Kazham by the\nSan d'Orian Cathedral.\nThe package contains a slab of\nElshimo marble and a letter to the\nSan d'Orian sculptor, Mulaujeant.",category=0},
[256]={id=256,name="treasure map",plural="treasure maps",description="\nA piece of paper Magriffon calls \"a\nmap to hidden pirate treasure.\" Some\nstrange numbers are written upon it.\n\n(F-7)(H-10)(I-12)",category=2},
[257]={id=257,name="strangely shaped coral",plural="strangely shaped coral",description="\nA strangely shaped piece of coral you\nfound in the Korroloka Tunnel.",category=4},
[258]={id=258,name="sealed dagger",plural="sealed daggers",description="\nA seal has been placed upon\nthis blade, making it impossible\nto unsheathe.",category=2},
[259]={id=259,name="Angelica's letter",plural="Angelica's letters",description="\nA letter written by Windurstian artist\nAngelica to the Kazham chieftainness.\nThe handwriting is so terrible, it is\nalmost impossible to read.",category=0},
[260]={id=260,name="empty barrel",plural="empty barrels",description="\nAn empty barrel you received\nfrom Washu.",category=3},
[261]={id=261,name="barrel of Opo-Opo brew",plural="barrels of Opo-Opo brew",description="\nThis barrel from Washu contains a\nspecial brew made by the Opo-opos.",category=2},
[262]={id=262,name="Elshimo Lowlands supplies",plural="Elshimo Lowlands supplies",description="\nDeliver these supplies to the guards\nmanning the Elshimo Lowlands Outpost\nbefore the next conquest results\nare tallied.\n",category=0},
[263]={id=263,name="Elshimo Uplands supplies",plural="Elshimo Uplands supplies",description="\nDeliver these supplies to the guards\nmanning the Elshimo Uplands Outpost\nbefore the next conquest results\nare tallied.\n",category=0},
[264]={id=264,name="joker card",plural="joker cards",description="\nA card you found in the Toraimarai\nCanal. The pierrot drawn on the front\nis dancing a strange jig.",category=2},
[265]={id=265,name="Orastery ring",plural="Orastery rings",description="\nThe ring entrusted to the Minister\nof the Orastery. It bears the\nOrastery's mark.",category=0},
[266]={id=266,name="Altepa moonpebble",plural="Altepa moonpebbles",description="\nThis stone you found in the\nAltepa Desert glows only at night.",category=3},
[267]={id=267,name="Rhinostery certificate",plural="Rhinostery certificates",description="\nThis certificate with the signature of\nfour researchers states you have been\nofficially licensed by the Rhinostery.\nNow you should have clearance to\nthe area behind the Priming Gate in\nWindurst Walls.",category=2},
[268]={id=268,name="dreamrose",plural="dreamroses",description="\nIn her will, the late Queen Leaute\nasked that this flower forever bloom\nin her chateau garden. The pollen of\nthe dreamrose is said to cause\nhallucinations.",category=2},
[269]={id=269,name="ancient San d'Orian book",plural="ancient San d'Orian books",description="\nAn ancient tome discovered in the\nalleged true tomb of King Ranperre.\nNot only is it written in ancient\nSan d'Orian, but it is also in code.",category=3},
[270]={id=270,name="piece of paper",plural="pieces of paper",description="\nA message found in Queen Leaute's\ngarden. It reads, \"When faced with\ndeceit, often the truth lies behind\nyour back.\"",category=2},
[271]={id=271,name="invisible man sticker",plural="invisible man stickers",description="\nJust stick it on and fade from\nview! One of the seven items from\nthe Junior Investigator's Toolkit\nmade by Chamama. Not to be used\nfor pranks.",category=3},
[272]={id=272,name="paintbrush of souls",plural="paintbrushes of souls",description="\nA large paintbrush found in the\nlibrary of the Temple of Uggalepih.\nIt appears to harbor some\nmysterious power...",category=2},
[273]={id=273,name="old rusty key",plural="old rusty keys",description="\nA key found in the library of the\nTemple of Uggalepih.",category=3},
[274]={id=274,name="ancient tablet fragment",plural="ancient tablet fragments",description="\nA flat piece of stone found in\nthe Quicksand Caves. It has ancient\nwriting on it and seems to be part\nof a tablet.",category=3},
[275]={id=275,name="\"Star Seeker\"",plural="\"Star Seeker\"",description="\nA magic doll lent to you by the\nAurastery. It is empowered to track\nthe magical emanations of the ring\nof the Aurastery minister. The doll\nwill suddenly give directions when\nyou change areas, so you must be\ncareful to pay attention.",category=2},
[276]={id=276,name="Aurastery ring",plural="Aurastery rings",description="\nThe ring entrusted to the Minister\nof the Aurastery. It bears the\nAurastery's mark.",category=0},
[277]={id=277,name="tablet of ancient magic",plural="tablets of ancient magic",description="\nA tablet reconstructed from pieces\nfound in the Quicksand Caves.\nAncient magic is inscribed on its\nsurface.",category=2},
[278]={id=278,name="letter from Alfesar",plural="letters from Alfesar",description="\nA letter of introduction from\nFriar Alfesar to Charlaimagnat\nin the cathedral.",category=2},
[279]={id=279,name="magic-drained \"Star Seeker\" ",plural="magic-drained \"Star Seeker\" ",description="\nA magic doll lent to you by the\nAurastery. The magic in the doll\nhas been drained by Sedal-Godjal.",category=2},
[280]={id=280,name="Rhinostery ring",plural="Rhinostery rings",description="\nThe ring entrusted to the Minister\nof the Rhinostery. It bears the\nRhinostery's mark.",category=0},
[281]={id=281,name="Manustery ring",plural="Manustery rings",description="\nThe ring entrusted to the Minister\nof the Manustery. It bears the\nManustery's mark.",category=0},
[282]={id=282,name="glove of perpetual twilight",plural="gloves of perpetual twilight",description="\nThis glove must be worn in order to\nutilize the power of the five\nministry rings. Each ring is worn on\na different finger. Apururu is the\nonly Tarutaru capable of putting on\nthe glove.",category=2},
[283]={id=283,name="ancient San d'Orian tablet",plural="ancient San d'Orian tablets",description="\nA tablet inscribed with a code written\nin ancient San d'Orian. The characters\nare beyond comprehension.",category=3},
[284]={id=284,name="crystal dowser",plural="crystal dowsers",description="\nAn instrument comprising a crystal\nattached to a string. Orcs used this\nto search for Lightbringer.",category=2},
[285]={id=285,name="piece of a broken key",plural="pieces of a broken key",description="\nA piece of a broken key found in\nthe Temple of Uggalepih.",category=2},
[286]={id=286,name="piece of a broken key",plural="pieces of a broken key",description="\nA piece of a broken key found in\nthe Temple of Uggalepih.",category=2},
[287]={id=287,name="piece of a broken key",plural="pieces of a broken key",description="\nA piece of a broken key found in\nthe Temple of Uggalepih.",category=2},
[288]={id=288,name="drops of Amnio",plural="drops of Amnio",description="\nWater used in the d'Oraguille coming-\nof-age ceremony. They say one enters\nadulthood when the water breaks.",category=4},
[289]={id=289,name="reinforced cermet",plural="reinforced cermet",description="\nThis cermet has been reinforced with\nancient Zilart techniques.",category=4},
[290]={id=290,name="letter from Werei",plural="letters from Werei",description="\n\"To my dear friend Gumbah...\n\n                                  Werei\"",category=2},
[291]={id=291,name="Tonberry key",plural="Tonberry keys",description="\nA key to a small room in the Temple\nof Uggalepih where a Tonberry priest\nsits trapped.",category=2},
[292]={id=292,name="thesis on alchemy",plural="theses on alchemy",description="\nA graduation thesis written on the\nsubject of alchemy. However, the\nAurastery student who turned this in\nforgot to put their name on it.\n\"See me in my office, immediately!\"\nis printed on the bottom in red ink.",category=2},
[293]={id=293,name="old piece of wood",plural="old pieces of wood",description="\n\"To whoever may find this...\n\n                                  Werei\"",category=3},
[294]={id=294,name="dragon curse remedy",plural="dragon curse remedies",description="\nA folk remedy said to remove a\ndragon's curse. Its efficacy is\nhighly dubious.",category=2},
[295]={id=295,name="sealed iron box",plural="sealed iron boxes",description="\nThis locked metallic box looks\nimpossible to open by normal means.",category=2},
[296]={id=296,name="sea serpent statue",plural="sea serpent statues",description="\nThe Sahagin are said to worship this\nstatue of a sea serpent.",category=2},
[297]={id=297,name="Altepa polishing stone",plural="Altepa polishing stones",description="\nSaid to be the only stone capable\nof restoring a sheen to metals that\nare no longer used.",category=3},
[298]={id=298,name="challenge to the Royal Knights",plural="challenges to the Royal Knights",description="\nA letter addressed to the Royal\nKnights. \"The helm of the last\ndragoon is already in my\npossession. I will lay bare the\ninadequacies of the Royal Knights'\ncurrent leadership and their\ninability to defend San d'Oria...\"",category=2},
[299]={id=299,name="Ranchuriome's legacy",plural="Ranchuriome's legacy",description="\nBrugaire's inheritance from his\nfather, Ranchuriome. It is a wooden\nbox containing some sort of heavy\nobject.",category=0},
[300]={id=300,name="Ronfaure EF insignia",plural="Ronfaure EF insignias",description="\nAn insignia of the expeditionary force.\nThe inscription on the back reads,\n\"Perform the following:\n  -Locate and destroy the enemy.\n  -Raid the target's treasure chests.\n  -Seek battles yielding high experience.\n You will be rewarded upon your\n victory.\"",category=2},
