[328]={id=328,name="tuning fork of fire",plural="tuning forks of fire",description="\nResearchers in the Rhinostery designed\nthis tuning fork to awaken the giant\nprotocrystals located around Vana'diel\nby resonating with them.",category=2},
[329]={id=329,name="tuning fork of earth",plural="tuning forks of earth",description="\nResearchers in the Rhinostery designed\nthis tuning fork to awaken the giant\nprotocrystals located around Vana'diel\nby resonating with them.",category=2},
