[333]={id=333,name="tuning fork of lightning",plural="tuning forks of lightning",description="\nResearchers in the Rhinostery designed\nthis tuning fork to awaken the giant\nprotocrystals located around Vana'diel\nby resonating with them.",category=2},
[334]={id=334,name="moon bauble",plural="moon baubles",description="\nThe six whispers have transformed\nCarbuncle's Ruby into an instrument\ncapable of drawing Fenrir to the\nFull Moon Fountain.",category=2},
[335]={id=335,name="vial of dream incense",plural="vials of dream incense",description="\nDeveloped by researchers\nat Windurst's Rhinostery,\nthe intoxicating aroma of\nthis incense puts whoever\nsmells it into a momentary trance.",category=2},
[336]={id=336,name="Orcish crest",plural="Orcish crests",description="\nAn Orcish crest obtained in the\nMonastic Cavern.",category=3},
[337]={id=337,name="Quadav crest",plural="Quadav crests",description="\nAn Quadav crest obtained in the\nQulun Dome.",category=2},
[338]={id=338,name="Yagudo crest",plural="Yagudo crests",description="\nA Yagudo crest obtained in\nCastle Oztroja.",category=2},
[339]={id=339,name="\"Un Moment\"",plural="\"Un Moment\"",description="\nOne of the three movements in the\n\"Chanson de Liberte.\"",category=0},
[340]={id=340,name="\"L'Ephemere\"",plural="\"L'Ephemere\"",description="\nOne of the three movements in the\n\"Chanson de Liberte.\"",category=0},
[341]={id=341,name="\"L'Ancienne\"",plural="\"L'Ancienne\"",description="\nOne of the three movements in the\n\"Chanson de Liberte.\"",category=0},
[342]={id=342,name="\"Chanson de Liberte\"",plural="\"Chanson de Liberte\"",description="\nCarmelo has translated and arranged\nthe three movements--\"Un Moment,\"\n\"L'Ephemere,\" and \"L'Ancienne\"\n--to complete this legendary piece.",category=0},
[343]={id=343,name="weapon training guide",plural="weapon training guides",description="\nThis slip of parchment explains,\nin detail, the steps one must take\nto improve her weapon wielding skills.",category=2},
[344]={id=344,name="map to the Annals of Truth",plural="maps to the Annals of Truth",description="\nA map indicating the location of\nwhere you are to travel for your\nfinal trial.",category=2},
[345]={id=345,name="Annals of Truth",plural="Annals of Truth",description="\nInscribed upon this parchment are\nthe instructions on how to perform\nan advanced weapon technique.",category=0},
[346]={id=346,name="completion certificate",plural="completion certificates",description="\nThis certificate proves you have\nsuccessfully escorted your client to\nthe requested destination.",category=2},
[347]={id=347,name="Dynamis Debugger",plural="Dynamis Debuggers",description="\nFor GM use only!",category=2},
[348]={id=348,name="dropped item",plural="dropped items",description="\nAn item dropped by an airship\npassenger.\nNosy, aren't we?",category=2},
[349]={id=349,name="White Card",plural="White Cards",description="\nA flexible white card covered\nin the fluids of a Luminian.",category=2},
[350]={id=350,name="Red Card",plural="Red Cards",description="\nA flexible red card covered\nin the fluids of a Luminian.",category=2},
[351]={id=351,name="Black Card",plural="Black Cards",description="\nA flexible black card covered\nin the fluids of a Luminian.",category=2},
[352]={id=352,name="Holla gate crystal",plural="Holla gate crystals",description="\nA crystal taken from the\nCrag of Holla on the La Theine\nPlateau.\n\nNeeded to teleport to that crag.",category=2},
[353]={id=353,name="Dem gate crystal",plural="Dem gate crystals",description="\nA crystal taken from the\nCrag of Dem on the Konschtat\nHighlands.\n\nNeeded to teleport to that crag.",category=2},
[354]={id=354,name="Mea gate crystal",plural="Mea gate crystals",description="\nA crystal taken from the\nCrag of Mea in the Tahrongi\nCanyon.\n\nNeeded to teleport to that crag.",category=2},
[355]={id=355,name="Vahzl gate crystal",plural="Vahzl gate crystals",description="\nA new type of gate crystal found in\nXarcabard.\n\nNeeded to teleport to that area.",category=2},
[356]={id=356,name="Yhoator gate crystal",plural="Yhoator gate crystals",description="\nA new type of gate crystal found on\nElshimo Island.\n\nNeeded to teleport to the Yhoator\nJungle.",category=2},
