[484]={id=484,name="dark Mana Orb",plural="dark Mana Orbs",description="\nA Mana Orb drained of magic, given\nto you by Fenrir. He has asked you\nto pass it on to the children.",category=2},
[485]={id=485,name="moongate pass",plural="moongate passes",description="\nSimply carrying this pass with you\nunlocks the moongate found deep\nin Ro'Maeve.",category=2},
[486]={id=486,name="Hydra Corps Command Scepter",plural="Hydra Corps Command Scepters",description="\nA collapsible mythril scepter carried\nby Hydra Corps officers.",category=2},
