[490]={id=490,name="Hydra Corps Insignia",plural="Hydra Corps Insignias",description="\nThe symbol of the Hydra Corps:\na many-headed golden serpent\nwrapped around a sphere. ",category=2},
[491]={id=491,name="Hydra Corps Battle Standard",plural="Hydra Corps Battle Standards",description="\nThe battle standard of the Hydra\nCorps: a flag emblazoned with a\nmany-headed golden serpent.",category=2},
[492]={id=492,name="vial of shrouded sand",plural="vials of shrouded sand",description="\nThis vial contains sand that glows\nwith a mysterious hazy aura.\nIt is a mineral that comes from\nDynamis, the Shrouded Land.",category=2},
[493]={id=493,name="Diary of Mukunda",plural="Diary of Mukunda",description="\nThis diary contains nothing but\ncomplaints about Senator Alois.",category=0},
