[567]={id=567,name="Moglification: A.M.A.N. Trove",plural="Moglification: A.M.A.N. Trove",description="\nMoogle-powered assistance from your Mog House. Slightly increases the quality of rewards you earn when you trade a used orb to Greyson...maybe.",category=2},
[576]={id=576,name="Ballista License",plural="Ballista Licenses",description="\nYour participation in Ballista has been\napproved by the three nations of\nBastok, San d'Oria, and Windurst.",category=2},
[577]={id=577,name="Ballista Instawarp",plural="Ballista Instawarps",description="\nShow this ticket to any Ballista\nevent staff to receive a free warp\nback to your home point.\nAn Instawarp can only be used\nonce and cannot be used while\nparticipating in a Ballista match.",category=2},
[578]={id=578,name="Ballista Instaport",plural="Ballista Instaports",description="\nShow this ticket to any Ballista\nevent staff to receive a free\nteleport to the area where the\nnext match is taking place.\nAn Instaport can only be used\nonce and cannot be used while\nparticipating in a Ballista match.",category=2},
[579]={id=579,name="mysterious amulet",plural="mysterious amulets",description="\nThe strange boy gave you this amulet\nbefore leaving Dr. Monberaux's clinic.\nYour body tingles when you clench\nit in your hand.",category=2},
[580]={id=580,name="mysterious amulet",plural="mysterious amulets",description="\nThe strange boy gave you this amulet\nbefore leaving Dr. Monberaux's clinic.\nYou feel that the glow of its power\nis weaker than before.",category=2},
[581]={id=581,name="cracked Mimeo Mirror",plural="cracked Mimeo Mirrors",description="\nAn unusual mirror owned by\nHonoi-Gomoi. It is said to reflect\nthe memories of the person who\ngazes into its glassy surface. Or it\nwould, if it weren't so badly cracked.",category=2},
[582]={id=582,name="reliquiarium key",plural="reliquiarium keys",description="\nThis elaborately decorated key\nsupposedly opens the door to the\nSacrarium's reliquiarium.",category=2},
[583]={id=583,name="Mimeo Stone",plural="Mimeo Stones",description="\nA glowing stone found in the\nAttohwa Chasm. The light from the\nstone seems to be pointing to the\ntop of Parradamo Tor.",category=2},
[584]={id=584,name="mystic ice",plural="mystic ice",description="\nThis magical ice is said to harbor\nthe power to call forth powerful\nwinds.",category=4},
[585]={id=585,name="KEY ITEM",plural="KEY ITEMS",description="\nIt's spiffier than cheese!",category=2},
[586]={id=586,name="Mimeo Jewel",plural="Mimeo Jewels",description="\nA strange jewel obtained in the\nAttohwa Chasm. A tiny flame can\nsometimes be seen dancing within\nthe gem. Taking this jewel to a\ncertain place should transform it\ninto a different item.",category=2},
[587]={id=587,name="Mimeo Feather",plural="Mimeo Feathers",description="\nAn ancient power sleeping within the\nearth has metamorphosed the Mimeo\nJewel into this beautiful feather.\nThe first feather of three.",category=2},
[588]={id=588,name="second Mimeo Feather",plural="second Mimeo Feather",description="\nAn ancient power sleeping within the\nearth has metamorphosed the Mimeo\nJewel into this beautiful feather.\nThe second feather of three.",category=0},
[589]={id=589,name="third Mimeo Feather",plural="third Mimeo Feather",description="\nAn ancient power sleeping within the\nearth has metamorphosed the Mimeo\nJewel into this beautiful feather.\nThe third feather of three.",category=0},
[590]={id=590,name="light of Holla",plural="light of Holla",description="\nThis glow represents the courage\nradiating from your heart.",category=0},
[591]={id=591,name="light of Dem",plural="light of Dem",description="\nThis glow represents the justice\nradiating from your heart.",category=0},
[592]={id=592,name="light of Mea",plural="light of Mea",description="\nThis glow represents the trust\nradiating from your heart.",category=0},
[593]={id=593,name="light of Vahzl",plural="light of Vahzl",description="\nThis glow represents the hope\nradiating from your heart.",category=0},
[594]={id=594,name="light of Al'Taieu",plural="light of Al'Taieu",description="\nThis glow represents the compassion\nradiating from your heart.",category=0},
[595]={id=595,name="blue bracelet",plural="blue bracelets",description="\nThe mysterious bracelet you found\ndeep within Pso'Xja. It emits a faint\nblue glow that is only recognizable\nwhen you are in the ruins.",category=2},
[596]={id=596,name="green bracelet",plural="green bracelets",description="\nThe mysterious bracelet you found\ndeep within Pso'Xja. It emits a\nlight green sparkle that is only\nrecognizable when you are in the\nruins.",category=2},
[597]={id=597,name="dusty tome",plural="dusty tomes",description="\nA book obtained in Movalpolos. Its\npages appear worn from being turned\nmany times.",category=2},
[598]={id=598,name="pointed jug",plural="pointed jugs",description="\nA jug obtained in Movalpolos. You\ncan hear some kind of liquid\nsloshing around inside.",category=2},
[599]={id=599,name="cracked club",plural="cracked clubs",description="\nA club obtained in Movalpolos. The\ncracks along its length speak of\nfrequent use.",category=2},
[600]={id=600,name="peeling hairpin",plural="peeling hairpins",description="\nA hairpin obtained in Movalpolos. It\nappears worthless at first glance due\nto the peeling lacquer, but closer\ninspection reveals intricate carvings\non this masterful piece of jewelry. ",category=2},
[601]={id=601,name="old nametag",plural="old nametags",description="\nA nametag obtained in Movalpolos.\nDo the Moblins need these to tell\neach other apart?",category=3},
[602]={id=602,name="tiny wristlet",plural="tiny wristlets",description="\nSeveral white magnolias have been\ncarved in detail upon this small\nmetal wristlet.",category=2},
[603]={id=603,name="whispering conch",plural="whispering conches",description="\nThe soft sound of the ocean can\nbe heard when holding this\ndeep-sea shell to one's ear.",category=2},
[604]={id=604,name="Pso'Xja pass",plural="Pso'Xja passes",description="\nThe slip of paper reads: \"You have\nbeen hereby granted permission by\nthe Tenshodo to travel into the\ndeeper areas of the Pso'Xja ruins.\"",category=2},
[605]={id=605,name="piece of ripped floorplans",plural="pieces of ripped floorplans",description="\nYou believe the piece may be from\nthe floorplans of the area you found\nit in.",category=2},
[606]={id=606,name="limit breaker",plural="limit breakers",description="\nYou have been recognized by Nomad\nMoogles across Vana'diel as having\nsuccessfully broken your physical\nand mental limits.",category=2},
[607]={id=607,name="hyper altimeter",plural="hyper altimeters",description="\nAfter seven long years of\ndevelopment, the aeronautic\nengineers of Jeuno have finally\nconstructed an airship-specific\naltimeter that surpasses all those\nthat came before it.",category=2},
[608]={id=608,name="molybdenum box",plural="molybdenum boxes",description="\nA heavy-duty case made with the\nrare metal known as molybdenum.\nIt was given to you by Cid's\nassistant, Raibaht.",category=2},
[609]={id=609,name="alabaster hairpin",plural="alabaster hairpins",description="\nYou found this expensive-looking\nhairpin in the Tavnazian Safehold.\nSeveral intricate engravings appear\nwhen you hold it to the light.",category=3},
[610]={id=610,name="Dawn talisman",plural="Dawn talismans",description="\nThis talisman bears the same symbol\nas the holy tome printed by the San\nd'Orian Cathedral.",category=2},
[611]={id=611,name="Silver Comet's collar",plural="Silver Comet's collars",description="\nThis collar was found on the grave\nof a general's son in Batallia Downs.\nIt bears the name \"Silver Comet.\"",category=2},
[612]={id=612,name="envelope from Monberaux",plural="envelopes from Monberaux",description="\nDoctor Monberaux has asked you to\ndeliver this message to Ducal Guard\nCaptain Wolfgang. Inside is a tiny\nslip of paper with a drawing of what\nlooks like Batallia Downs and the\ninscription \"K9N.\"",category=3},
[613]={id=613,name="Delkfutt recognition device",plural="Delkfutt recognition devices",description="\nThis card-shaped key is needed to\nunlock a door in Delkfutt's Tower\nthat leads to a secret laboratory.",category=2},
[614]={id=614,name="deed to Purgonorgo Isle",plural="deeds to Purgonorgo Isle",description="\nThe deed dropped by the warmachine\non Purgonorgo Isle. It seems to bear\nsome relation to the purchase of the\ntropical island, but the language is\nbeyond your understanding.",category=0},
[615]={id=615,name="Phoenix armlet",plural="Phoenix armlets",description="\nEnormous power is contained within\nthis armlet. It should be strong\nenough to open the gate that lies\nin the deepest part of the Pso'Xja\nruins.",category=2},
[616]={id=616,name="Phoenix pearl",plural="Phoenix pearls",description="\nEnormous power is contained within\nthis pearl. It should be strong\nenough to seal the gate that lies\nin the deepest part of the Pso'Xja\nruins.",category=2},
[617]={id=617,name="manaclipper ticket",plural="manaclipper tickets",description="\nA manaclipper boarding pass issued\nby the Fishermen's Guild.",category=2},
[618]={id=618,name="barge ticket",plural="barge tickets",description="\nA barge boarding pass issued by the\nCarpenters' Guild.",category=2},
[619]={id=619,name="All-You-Can-Ride Pass",plural="All-You-Can-Ride Passes",description="\nFor GM use only!",category=3},
[620]={id=620,name="Tavnazian Archipelago supplies",plural="Tavnazian Archipelago supplies",description="\nDeliver these supplies to the guards\nmanning the Tavnazian Archipelago\nOutpost before the next conquest\nresults are tallied.\n",category=0},
[621]={id=621,name="Rivernewort",plural="Rivernewort",description="\nSaid only to be found on Cape\nRiverne, this rare spice is renowned\nfor its flavor-enhancing qualities.",category=4},
[622]={id=622,name="Tavnazian cookbook",plural="Tavnazian cookbooks",description="\nThis appears to be an extremely old\nbook on how to prepare several\ntraditional Tavnazian dishes. Since\nit was written before the Age of\nAdventurers, it does not detail\nhow to prepare the recipes using\nsynthesis.",category=2},
[623]={id=623,name="Washu's flask",plural="Washu's flasks",description="\nA flask you received from Washu.\nYou have been asked to fill it with\nwater from the giant clams in\nKorroloka Tunnel.",category=2},
[624]={id=624,name="flask of clam water",plural="flasks of clam water",description="\nThis flask is filled with water\ntaken from the giant clams in\nKorroloka Tunnel.",category=2},
[625]={id=625,name="pungent providence pot",plural="pungent providence pots",description="\nThe odor coming from this pot\nconvinces others that the bearer is\nactually a Goblin. The terrible smell\nalso serves to keep away pot\nenthusiasts...",category=2},
[626]={id=626,name="torn-out pages",plural="torn-out pages",description="\nSeveral pages from a book written\nby Lord Torresapet B Ordelle on\nthe life of Gwynham Ironheart.\nThese pages were said to have been\ntorn out by Gwynham's daughter\nEnid.",category=4},
[627]={id=627,name="Tonberry blackboard",plural="Tonberry blackboards",description="\nThis blackboard is used to\ncommunicate with Riche, a Tonberry\nwho is employed as a Carpenters'\nLanding barge captain.",category=2},
[628]={id=628,name="letter from Muckvix",plural="letters from Muckvix",description="\nA letter from Muckvix addressed to\nMagriffon, a tactician living in\nKazham.",category=2},
[629]={id=629,name="letter from Magriffon",plural="letters from Magriffon",description="\nA letter from Magriffon addressed\nto Muckvix, a Goblin living in Jeuno.\nThe letter supposedly contains a\nbrilliant idea.",category=2},
[630]={id=630,name="providence pot",plural="providence pots",description="\nThis pot is said to bring astounding\nfortune upon the bearer. An object\nof envy for all pot enthusiasts.",category=2},
[631]={id=631,name="care package",plural="care packages",description="\nThis gift is covered with beautiful\nwrapping paper, but it appears to\nhave been rewrapped many times.\nThe shape of the package suggests\na potion or medicine of some sort.",category=2},
[632]={id=632,name="glittering fragment",plural="glittering fragments",description="\nA brightly glittering fragment said\nto have been left by the ancients.\nTo be used as evidence that the\nMoblins have discovered a\nmothercrystal deep beneath the\nearth.",category=2},
[633]={id=633,name="storeroom key",plural="storeroom keys",description="\nThe key to a storeroom near the\nentrance of Norg. For some reason,\nthe key is covered in teeth marks.",category=2},
[634]={id=634,name="Zeelozok's earplug",plural="Zeelozok's earplugs",description="\nAn earplug dropped by Zeelozok in\nCastle Zvahl. It has been designed\nto emit sound waves.",category=2},
[635]={id=635,name="potion voucher",plural="potion vouchers",description="\nThis coupon will automatically be\nexchanged for one free temporary\nitem at the start of your next\nBallista match.\n\n※Match level restrictions may\n　prevent the exchange.",category=2},
[636]={id=636,name="hi-potion voucher",plural="hi-potion vouchers",description="\nThis coupon will automatically be\nexchanged for one free temporary\nitem at the start of your next\nBallista match.\n\n※Match level restrictions may\n　prevent the exchange.",category=2},
