[652]={id=652,name="barge multi-ticket",plural="barge multi-tickets",description="\nA barge boarding pass issued by the\nCarpenters' Guild.\nCan be used multiple times.",category=2},
[653]={id=653,name="manaclipper multi-ticket",plural="manaclipper multi-tickets",description="\nA manaclipper boarding pass issued\nby the Fishermen's Guild.\nCan be used multiple times.",category=2},
[654]={id=654,name="fighter's armor claim slip",plural="fighter's armor claim slips",description="\n\"Holding\n\n 1 set of warrior artifact armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[655]={id=655,name="temple attire claim slip",plural="temple attire claim slips",description="\n\"Holding\n\n 1 set of monk artifact armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[656]={id=656,name="healer's attire claim slip",plural="healer's attire claim slips",description="\n\"Holding\n\n 1 set of white mage artifact armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[657]={id=657,name="wizard's attire claim slip",plural="wizard's attire claim slips",description="\n\"Holding\n\n 1 set of black mage artifact armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[658]={id=658,name="warlock's armor claim slip",plural="warlock's armor claim slips",description="\n\"Holding\n\n 1 set of red mage artifact armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[659]={id=659,name="rogue's attire claim slip",plural="rogue's attire claim slips",description="\n\"Holding\n\n 1 set of thief artifact armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[660]={id=660,name="gallant armor claim slip",plural="gallant armor claim slips",description="\n\"Holding\n\n 1 set of paladin artifact armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[661]={id=661,name="chaos armor claim slip",plural="chaos armor claim slips",description="\n\"Holding\n\n 1 set of dark knight artifact armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[662]={id=662,name="beast armor claim slip",plural="beast armor claim slips",description="\n\"Holding\n\n 1 set of beastmaster artifact armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[663]={id=663,name="choral attire claim slip",plural="choral attire claim slips",description="\n\"Holding\n\n 1 set of bard artifact armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[664]={id=664,name="hunter's attire claim slip",plural="hunter's attire claim slips",description="\n\"Holding\n\n 1 set of ranger artifact armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[665]={id=665,name="myochin armor claim slip",plural="myochin armor claim slips",description="\n\"Holding\n\n 1 set of samurai artifact armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[666]={id=666,name="ninja's garb claim slip",plural="ninja's garb claim slips",description="\n\"Holding\n\n 1 set of ninja artifact armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[667]={id=667,name="drachen armor claim slip",plural="drachen armor claim slips",description="\n\"Holding\n\n 1 set of dragoon artifact armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[668]={id=668,name="evoker's attire claim slip",plural="evoker's attire claim slips",description="\n\"Holding\n\n 1 set of summoner artifact armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=3},
[669]={id=669,name="vessel of light",plural="vessels of light",description="\nA sacred vessel kept in Tavnazia for\ngenerations. Originally one of the\ncrystal devices created by the\nancients, it is a weapon used to\nsmite the Emptiness with the light\nof the crystals. Also known as the\nEye of Altana.",category=2},
[670]={id=670,name="censer of abandonment",plural="censers of abandonment",description="\nThe aroma of incense burned in this\nvessel is said to attract Empty\nliving deep within Promyvion - Holla.",category=2},
[671]={id=671,name="censer of antipathy",plural="censers of antipathy",description="\nThe aroma of incense burned in this\nvessel is said to attract Empty\nliving deep within Promyvion - Dem.",category=2},
[672]={id=672,name="censer of animus",plural="censers of animus",description="\nThe aroma of incense burned in this\nvessel is said to attract Empty\nliving deep within Promyvion - Mea.",category=2},
[673]={id=673,name="censer of acrimony",plural="censers of acrimony",description="\nThe aroma of incense burned in this\nvessel is said to attract Empty\nliving deep within Promyvion - Vahzl.",category=2},
[674]={id=674,name="monarch beard",plural="monarch beards",description="\nA scale ripped from the jaw of a\nmighty wyrm while it was\nsleeping. Can be used to provoke\nthe fury of a dragon.",category=2},
[675]={id=675,name="astral covenant",plural="astral covenants",description="\nPlacing this sheet of parchment\non the altar of the Shrouded Maw\nis said to open a portal to a\nparallel dimension.",category=3},
[676]={id=676,name="shaft 2716 operating lever",plural="shaft 2716 operating levers",description="\nUse this lever to open the gate\nleading into Mine Shaft #2716.",category=2},
[677]={id=677,name="zephyr fan",plural="zephyr fans",description="\nThis seemingly normal fan has the\npower to temporarily stop the torrential\nwinds that block the path leading\ninto the Bearclaw Pinnacle caves.",category=2},
[678]={id=678,name="miasma filter",plural="miasma filters",description="\nAllows its wearer to bear the\npoisonous gasses surrounding\nBoneyard Gully.",category=2},
[679]={id=679,name="particularly poignant petal",plural="particularly poignant petals",description="\nWhile supposedly a powerful\nmedicine, its odor alone is\nenough to make one ill.",category=2},
[680]={id=680,name="antique amulet",plural="antique amulets",description="\nAn amulet that belonged to\nDespachiaire's late wife.\nThe origin of this old piece\nof jewelry is unknown.",category=3},
[681]={id=681,name="cathedral medallion",plural="cathedral medallions",description="\nAn antique amulet that has\nbeen polished to a sheen.\nAn inscription is faintly visible\non the face of the amulet.",category=2},
[682]={id=682,name="gold Ballista chevron",plural="gold Ballista chevrons",description="\nPresented only to those who\nhave displayed excellence on\nthe Ballista battlefield.\n\n※Must be returned to a Herald\nafter a set period indicated in\nthe official Ballista rulebook.",category=2},
[683]={id=683,name="mythril Ballista chevron",plural="mythril Ballista chevrons",description="\nPresented only to those who\nhave displayed excellence on\nthe Ballista battlefield.\n\n※Must be returned to a Herald\nafter a set period indicated in\nthe official Ballista rulebook.",category=2},
