[686]={id=686,name="bloody Ballista chevron",plural="bloody Ballista chevrons",description="\nPresented only to those warriors\nwho have displayed excellence\non the Ballista battlefield.\n\n※Must be returned to a Herald\nafter a set period indicated in\nthe official Ballista rulebook.",category=2},
[687]={id=687,name="orange Ballista chevron",plural="orange Ballista chevrons",description="\nPresented only to those monks\nwho have displayed excellence\non the Ballista battlefield.\n\n※Must be returned to a Herald\nafter a set period indicated in\nthe official Ballista rulebook.",category=3},
