[699]={id=699,name="purple Ballista chevron",plural="purple Ballista chevrons",description="\nPresented only to those dragoons\nwho have displayed excellence\non the Ballista battlefield.\n\n※Must be returned to a Herald\nafter a set period indicated in\nthe official Ballista rulebook.",category=2},
[700]={id=700,name="rainbow Ballista chevron",plural="rainbow Ballista chevrons",description="\nPresented only to those summoners\nwho have displayed excellence\non the Ballista battlefield.\n\n※Must be returned to a Herald\nafter a set period indicated in\nthe official Ballista rulebook.",category=2},
[701]={id=701,name="letters from Ulmia and Prishe",plural="letters from Ulmia and Prishe",description="\nA bundle of letters from Ulmia and\nPrishe addressed to the people of\nthe safehold. Prishe has scrawled a\nsmiley face on the back of each\nof the envelopes.",category=2},
[702]={id=702,name="Petra eater voucher",plural="Petra eater vouchers",description="\nThis coupon will automatically be\nexchanged for one free temporary\nitem at the start of your next\nBallista match.\n\n※Match level restrictions may\n　prevent the exchange.",category=2},
[703]={id=703,name="catholicon voucher",plural="catholicon vouchers",description="\nThis coupon will automatically be\nexchanged for one free temporary\nitem at the start of your next\nBallista match.\n\n※Match level restrictions may\n　prevent the exchange.",category=2},
[704]={id=704,name="red oil",plural="red oil",description="\nThis rare variety of oil was once\nwidely used to lubricate intricate\nmachinery such as mannequins.\nHowever, due to the oil's\ngrotesque apperance, production\nceased many years ago.",category=4},
[705]={id=705,name="Marble Bridge coaster",plural="Marble Bridge coasters",description="\nThanks to the schedule written up\non the back of this coaster,\nyou'll know if you can enter\nthe Marble Bridge the moment\nyou step into Upper Jeuno.",category=2},
[706]={id=706,name="lamp lighter's membership card",plural="lamp lighter's membership cards",description="\nWhen in Lower Jeuno, this card\nentitles you to hear the recruiting\nannouncement for lamp lighter\nvolunteers.",category=2},
[707]={id=707,name="shaft gate operating dial",plural="shaft gate operating dials",description="\nWhen fitted into the gate leading\nto Mine Shaft #2716, this jeweled\ndial can be used to rotate the\npassages, allowing travel to different\nrooms.",category=2},
[708]={id=708,name="mysterious amulet",plural="mysterious amulets",description="\nThe amulet given to you by Prishe.\nYour body tingles when you clench\nit in your hand.",category=2},
[709]={id=709,name="mire incense",plural="mire incense",description="\nThis natural variety of incense is\nformed from decaying marsh reeds.\nWhen lit, it gives off a strange odor\nthat is said to have supernatural\nproperties.",category=4},
[710]={id=710,name="Brand of Dawn",plural="Brands of Dawn",description="\nThe sign of the Dawn Goddess,\nburned into your mind in the\nGarden of Ru'Hmet.",category=2},
[711]={id=711,name="Brand of Twilight",plural="Brands of Twilight",description="\nThe sign of the Twilight God,\nburned into your mind in the\nGarden of Ru'Hmet.",category=2},
[712]={id=712,name="ornamented scroll",plural="ornamented scrolls",description="\nStrange diagrams fill this aged\nparchment scroll decorated with\na beautifully carved jade fastener.",category=3},
[713]={id=713,name="Better Humes and Mannequins",plural="Better Humes and Mannequins",description="\nA tattered copy of a magazine\nonce popular among mannequin\ncraftsmen. Its pages are filled\nwith numerous sketches of various\nmannequin poses.",category=0},
[714]={id=714,name="Petra Shovel",plural="Petra Shovels",description="\nWhen carrying this during a Ballista\nmatch, any temporary item you\nquarry will be automatically placed\ninto your inventory. An item\nwill also be automatically thrown\naway if you are unable to carry it.",category=2},
[715]={id=715,name="Caliginous Blade",plural="Caliginous Blades",description="\nGubokka found this blade on the Hume\nwarrior Vigsterkr. It was used by the\nman who saved Vigsterkr's life.",category=2},
[716]={id=716,name="Tear of Altana",plural="Tears of Altana",description="\nA divine tear residing within your heart\nthat fills you with love eternal.",category=0},
[717]={id=717,name="Ballista Band",plural="Ballista Bands",description="\nWhen wearing this during a Ballista\nmatch, you will have the choice\nof keeping or throwing away the\nfirst Petra you quarry.",category=2},
[718]={id=718,name="Shaded Cruse",plural="Shaded Cruses",description="\nA golden pot that appears to be of\ngreat value. Wazozo has kept it\nhidden well, claiming it as her prized\ntreasure. However, it was recently\nshattered into several pieces.",category=0},
[719]={id=719,name="letter from Shikaree X",plural="letters from Shikaree X",description="\nI challenge you to a duel in\nBoneyard Gully.\nLet's see what you're made of!\n\nShikaree X",category=2},
[720]={id=720,name="Monarch Linn Patrol Permit",plural="Monarch Linn Patrol Permits",description="\nA permit given to you by\nJustinius.\nAllows the bearer access to\nMonarch Linn.",category=2},
[721]={id=721,name="letter from Shikaree Y",plural="letters from Shikaree Y",description="\nI challenge you to a duel in\nBoneyard Gully.\nNot afraid of me, are you,\nsugarplum?\n\nShikaree Y",category=2},
[722]={id=722,name="letter from the Mithran Trackers",plural="letters from the Mithran Trackers",description="\nYou are cordially invited to a\ntraining session in Boneyard Gully.\nWe await your arrival.\n\nMhag\nShikaree Y\nShikaree X",category=2},
[723]={id=723,name="communication from Tzee Xicu",plural="communications from Tzee Xicu",description="\nA missive written by the Yagudo\nleader, Tzee Xicu the Manifest.\nIt is stored in a oddly shaped\ncontainer that resembles one of\nthe Orcs' cryptexes.",category=2},
[724]={id=724,name="Orcish seeker bats",plural="Orcish seeker bats",description="\nThese extremely intelligent bats\nare used by Orcish troopers and\ncursemakers to spy on enemies\nand gather information.",category=0},
[725]={id=725,name="vault quipus",plural="vault quipus",description="\nA colorful knotted rope normally\nused by the Yagudo to relay\nmessages. According to Hooknox,\nthis one can be used as\na key...",category=2},
[726]={id=726,name="Goblin recommendation letter",plural="Goblin recommendation letters",description="\nA letter of recommendation written\nby a Goblin scribe for Shieldwarrior\ndeserter Gu'Zho Thunderblade.\nYou cannot decipher the rows of\nstrange markings that cover this\nragged piece of parchment.",category=2},
[727]={id=727,name="costume kit",plural="costume kits",description="\nThe magical disguise kit beloved by\nMiledo-Shiraddo. The kit contains a\n\"knitted cap\" allowing the wearer to\nappear as a child, a pair of\n\"spectacles\" to transform into an\nold man, and a pair of \"silver heels\"\nfor the shape of an attractive lady.",category=2},
[728]={id=728,name="jar of reversion dust",plural="jars of reversion dust",description="\nAn item created for those who have\nmeddled in shapechanging.\nUsing this magical dust will allow\nany being to return to their original\nform.",category=2},
[729]={id=729,name="remedy voucher",plural="remedy vouchers",description="\nThis coupon will automatically be\nexchanged for one free temporary\nitem at the start of your next\nBallista match.\n\n※Match level restrictions may\n　prevent the exchange.",category=2},
[730]={id=730,name="panacea voucher",plural="panacea vouchers",description="\nThis coupon will automatically be\nexchanged for one free temporary\nitem at the start of your next\nBallista match.\n\n※Match level restrictions may\n　prevent the exchange.",category=2},
[731]={id=731,name="smelling salts voucher",plural="smelling salts vouchers",description="\nThis coupon will automatically be\nexchanged for one free temporary\nitem at the start of your next\nBallista match.\n\n※Match level restrictions may\n　prevent the exchange.",category=2},
[732]={id=732,name="vitrallum",plural="vitrallum",description="\nA metal similar to the material used\nto create the Mirror of Blighted Gloom.\nRemains in liquid form at room\ntemperature.",category=4},
[733]={id=733,name="opalescent stone",plural="opalescent stones",description="\nThis stone can be ground\nand liquefied into paint\nthat glistens like a pearl.",category=3},
[734]={id=734,name="Cosmo-Cleanse",plural="Cosmo-Cleanse",description="\nA somewhat doubtful alchemy\nproduct of the Near East.",category=4},
[735]={id=735,name="old woman's portrait",plural="old woman's portraits",description="\nAngelica created this\nportrait using paint made\nfrom an opalescent stone.",category=3},
[736]={id=736,name="glimmering mica",plural="glimmering mica",description="\nThis flat piece of stone is perfect\nfor burning incense. When heated,\nit begins to glow with a soft,\nblue-white light.",category=4},
[737]={id=737,name="mistroot",plural="mistroot",description="\nWhen thrown onto a flame, this\nplant creates a cloud of wispy,\naromatic smoke.",category=4},
[738]={id=738,name="lunascent log",plural="lunascent logs",description="\nWhen this wood is dried and then\nburned, it gives off a fragrance\nreminiscent of a crisp winter night.",category=2},
[739]={id=739,name="Dynamis - Valkurm sliver",plural="Dynamis - Valkurm slivers",description="\nA darkly glowing sliver\nof black crystal.",category=2},
[740]={id=740,name="Dynamis - Buburimu sliver",plural="Dynamis - Buburimu slivers",description="\nA darkly glowing sliver\nof black crystal.",category=2},
[741]={id=741,name="Dynamis - Qufim sliver",plural="Dynamis - Qufim slivers",description="\nA darkly glowing sliver\nof black crystal.",category=2},
[742]={id=742,name="Dynamis - Tavnazia sliver",plural="Dynamis - Tavnazia slivers",description="\nA darkly glowing sliver\nof black crystal.",category=2},
[743]={id=743,name="red Sentinel badge",plural="red Sentinel badges",description="\nA list of characters are visible\non the surface of the badge.\n\nS: G8, J9, I8, I8, K5\nN: E4, J8, J8, H8, I9\nP: J8, H8, H10, H8, G7\nC: I9, H9, I9, F7, H7",category=2},
[744]={id=744,name="blue Sentinel badge",plural="blue Sentinel badges",description="\nA list of characters are visible\non the surface of the badge.\n\nMi: H6, I7, H5, I6, H9\nMa: I9, J10, K10, E11, E10\nP: F6, J5, F8, E6, F5\nMe: G7, G8, K7, I8, G8",category=2},
[745]={id=745,name="green Sentinel badge",plural="green Sentinel badges",description="\nA list of characters are visible\non the surface of the badge.\n\nWat: G4, G9, F9, F10, F8\nWal: J11, J6, K7, H3, F5\nP: M6, F6, E7, E7, G7\nWo: I5, I10, J3, J13, H10",category=2},
[746]={id=746,name="white Sentinel badge",plural="white Sentinel badges",description="\nA list of characters are visible\non the surface of the badge.\n\nR: H9, G8, G7, I6, H7\nU: G7, G8, G8, H9, H9\nL: G10, H10, I7, J7, H9\nP: I8, G8, I8, H8, H8",category=2},
[747]={id=747,name="eye of flames",plural="eyes of flames",description="\nAn inexplicable and inescapable\ngaze that you can sense but\ncannot see.",category=3},
[748]={id=748,name="eye of tremors",plural="eyes of tremors",description="\nAn inexplicable and inescapable\ngaze that you can sense but\ncannot see.",category=3},
[749]={id=749,name="eye of tides",plural="eyes of tides",description="\nAn inexplicable and inescapable\ngaze that you can sense but\ncannot see.",category=3},
[750]={id=750,name="eye of gales",plural="eyes of gales",description="\nAn inexplicable and inescapable\ngaze that you can sense but\ncannot see.",category=3},
[751]={id=751,name="eye of frost",plural="eyes of frost",description="\nAn inexplicable and inescapable\ngaze that you can sense but\ncannot see.",category=3},
[752]={id=752,name="eye of storms",plural="eyes of storms",description="\nAn inexplicable and inescapable\ngaze that you can sense but\ncannot see.",category=3},
[753]={id=753,name="red invitation card",plural="red invitation cards",description="\nAn invitation card received from a\nSalaheem's Sentinels representative.\nYou remember something about their\nheadquarters being in a place called\nAl Zahbi...",category=2},
[754]={id=754,name="blue invitation card",plural="blue invitation cards",description="\nAn invitation card received from a\nSalaheem's Sentinels representative.\nYou remember something about their\nheadquarters being in a place called\nAl Zahbi...",category=2},
[755]={id=755,name="green invitation card",plural="green invitation cards",description="\nAn invitation card received from a\nSalaheem's Sentinels representative.\nYou remember something about their\nheadquarters being in a place called\nAl Zahbi...",category=2},
[756]={id=756,name="white invitation card",plural="white invitation cards",description="\nAn invitation card received from a\nSalaheem's Sentinels representative.\nYou remember something about their\nheadquarters being in a place called\nAl Zahbi...",category=2},
[757]={id=757,name="healing powder voucher",plural="healing powder vouchers",description="\nThis coupon will automatically be\nexchanged for one free temporary\nitem at the start of your next\nBallista match.\n\n※Match level restrictions may\n　prevent the exchange.",category=2},
[758]={id=758,name="Brenner Shovel",plural="Brenner Shovels",description="\nWhen carrying this during a Brenner\nmatch, any temporary item you\nquarry will be automatically placed\ninto your inventory. An item\nwill also be automatically thrown\naway if you are unable to carry it.",category=2},
[759]={id=759,name="Brenner Band",plural="Brenner Bands",description="\nWhen wearing this during a Brenner\nmatch, you will have the choice\nof keeping or throwing away the\nfirst Petra you quarry.",category=2},
[760]={id=760,name="Silver Sea ferry ticket",plural="Silver Sea ferry tickets",description="\nA ticket that allows you to board\nthe ferry ship between Al Zahbi\nand Nashmau.",category=2},
[761]={id=761,name="moonlight ore",plural="moonlight ore",description="\nA chunk of light ore infused with\nthe energy of the Ro'Maeve ruins.\nIt pulses with powerful lunar\nradiance...",category=2},
[762]={id=762,name="Leujaoam Assault orders",plural="Leujaoam Assault orders",description="\nA document that authorizes you to\ntake part in a Leujaoam Sanctum\nAssault mission.",category=2},
[763]={id=763,name="Mamool Ja Assault orders",plural="Mamool Ja Assault orders",description="\nA document that authorizes you to\ntake part in a Mamool Ja Training\nGrounds Assault mission.",category=2},
[764]={id=764,name="Lebros Assault orders",plural="Lebros Assault orders",description="\nA document that authorizes you to\ntake part in a Lebros Cavern Assault\nmission.",category=2},
[765]={id=765,name="Periqia Assault orders",plural="Periqia Assault orders",description="\nA document that authorizes you to\ntake part in a Periqia Assault\nmission.",category=2},
[766]={id=766,name="Ilrusi Assault orders",plural="Ilrusi Assault orders",description="\nA document that authorizes you to\ntake part in an Ilrusi Atoll Assault\nmission.",category=3},
[767]={id=767,name="Dkhaaya's research journal",plural="Dkhaaya's research journals",description="\nA journal filled with years of\nDkhaaya's research notes on the\nOlduum civilization. The pages are\ncovered in incomprehensible\ndrawings accompanied by\nDkhaaya's scribbled musings.",category=2},
[768]={id=768,name="electrocell",plural="electrocells",description="\nA small metallic container without\na lid. According to Dkhaaya's\nresearch, it is possible to store\nthe power of lighting within the\nelectrocell. The process of\nharnessing the energy remains\nundeciphered.",category=3},
[769]={id=769,name="electropot",plural="electropots",description="\nA pot made of magnetic materials.\nAccording to Dkhaaya's research, it\nis possible to draw iron sand into\nthe pot through its spout.",category=3},
[770]={id=770,name="electrolocomotive",plural="electrolocomotives",description="\nA toy-like, metallic object with four\ncarriages. The results of Dkhaaya's\nresearch into the workings of the\nelectrolocomotive have been applied\nin the animation of automatons.",category=3},
[771]={id=771,name="Mark of Zahak",plural="Marks of Zahak",description="\nA symbol depicting the Serpentking\nZahak, a two-headed snake whose\nlikeness graces the national flag of\nAht Urhgan. This mark represents\nthe awakening of a blue mage's\npowers.",category=2},
[772]={id=772,name="vial of luminous water",plural="vials of luminous water",description="\nUsually a cloudy liquid, the water in\nthis vial begins to glow brightly\nwhen exposed to the rays of the\nsun.\nA type of love potion.",category=2},
[773]={id=773,name="image recorder",plural="image recorders",description="\nThis device captures images\nusing a flash of bright light and\nan Ahriman lens.",category=3},
[774]={id=774,name="cast metal plate",plural="cast metal plates",description="\nA long, thin plate of metal you found\nin Mount Zhayolm. A distinctive\npattern is inscribed upon its surface.",category=2},
[775]={id=775,name="supplies package",plural="supplies packages",description="\nA bronze box entrusted to you by\nNaja Salaheem. It is sealed with\nanimal glue, so you cannot see\nwhat it contains. You can hear\nsomething soft rolling around\ninside when you shake the box.",category=2},
[776]={id=776,name="rainbow berry",plural="rainbow berries",description="\nAn invisible, legendary fruit.",category=2},
[777]={id=777,name="sapphire Ballista chevron",plural="sapphire Ballista chevrons",description="\nPresented only to those blue\nmages who have displayed\nexcellence on the Ballista\nbattlefield.\n\n※Must be returned to a Herald\nafter a set period indicated in\nthe official Ballista rulebook.",category=2},
[778]={id=778,name="coral Ballista chevron",plural="coral Ballista chevrons",description="\nPresented only to those corsairs\nwho have displayed excellence\non the Ballista battlefield.\n\n※Must be returned to a Herald\nafter a set period indicated in\nthe official Ballista rulebook.",category=2},
[779]={id=779,name="silk Ballista chevron",plural="silk Ballista chevrons",description="\nPresented only to those\npuppetmasters who have displayed\nexcellence on the Ballista\nbattlefield.\n\n※Must be returned to a Herald\nafter a set period indicated in\nthe official Ballista rulebook.",category=2},
[780]={id=780,name="PSC Wildcat badge",plural="PSC Wildcat badges",description="\nA bronze Private Second Class\nmercenary badge from \"Salaheem's\nSentinels.\" A scintillant moat carp\nis emblazoned in its center.",category=2},
[781]={id=781,name="boarding permit",plural="boarding permits",description="\n\"The holder of this permit has\nbeen authorized for travel to the\nNear East in order to take up post\nas a mercenary. The Empire of Aht\nUrhgan has a duty to inform our\nlands should the owner of this\npermit perish while abroad.\n     The Commissioner of Mhaura\"",category=2},
[782]={id=782,name="runic portal use permit",plural="runic portal use permits",description="\nThis permit authorizes the use of\nthe runic portals in the Chamber of\nPassage.",category=2},
[783]={id=783,name="PFC Wildcat badge",plural="PFC Wildcat badges",description="\nA bronze Private First Class\nmercenary badge from \"Salaheem's\nSentinels.\" Two scintillant moat\ncarps are emblazoned in its center.",category=2},
[784]={id=784,name="SP Wildcat badge",plural="SP Wildcat badges",description="\nA bronze Superior Private\nmercenary badge from \"Salaheem's\nSentinels.\" Three scintillant moat\ncarps are emblazoned in its center.",category=2},
[785]={id=785,name="Raillefal's letter",plural="Raillefal's letters",description="\nA letter you agreed to deliver for\nRaillefal the sage (or was it\nmercenary?).\nYou can barely make out the words\n\"Chateau d'Oraguille\" on the\nenvelope.",category=2},
[786]={id=786,name="Ephramadian gold coin",plural="Ephramadian gold coins",description="\nAn exquisite gold coin you retrieved\nfrom the grave of a fallen knight.\nIt bears the crest of a crowned\ndolphin.",category=3},
[787]={id=787,name="Imperial Army I.D. tag",plural="Imperial Army I.D. tags",description="\nA metal tag inscribed with an\nImperial Army identification number.\nNeeded to sign up for Assault\nmissions.",category=3},
[788]={id=788,name="Raillefal's note",plural="Raillefal's notes",description="\nYou can barely make out the words\n\"I return to my homeland.\"",category=2},
[789]={id=789,name="Dark Rider hoofprint",plural="Dark Rider hoofprints",description="\nA hardened chunk of clay imprinted\nby the hoof of a huge warhorse.",category=2},
[790]={id=790,name="bag of gold pieces",plural="bags of gold pieces",description="\nThis bag is so heavy that it\nrequires two hands to carry\nfrom one place to another.\nThere must be a fortune inside...",category=2},
[791]={id=791,name="forgotten hexagun",plural="forgotten hexaguns",description="\nAn old hexagun found in Talacca\nCove. It is broken and unusable.",category=2},
[792]={id=792,name="plasma oil",plural="plasma oil",description="\nA special type of oil required to\nanimate automatons.",category=2},
[793]={id=793,name="plasma rock",plural="plasma rocks",description="\nA crystallized chunk of plasma oil.",category=2},
[794]={id=794,name="LC Wildcat badge",plural="LC Wildcat badges",description="\nA silver Lance Corporal\nmercenary badge from \"Salaheem's\nSentinels.\" A scintillant moat\ncarp is emblazoned in its center.",category=2},
[795]={id=795,name="C Wildcat badge",plural="C Wildcat badges",description="\nA silver Corporal mercenary\nbadge from \"Salaheem's Sentinels.\"\nTwo scintillant moat carps are\nemblazoned in its center.",category=2},
[796]={id=796,name="pot of Tsetseroon's stew",plural="pots of Tsetseroon's stew",description="\nThis stew is giving off an\nindescribably foul scent.\nCould this possibly be edible...?",category=2},
[797]={id=797,name="Assault armband",plural="Assault armbands",description="\nThis armband designates you as the\nleader of an Assault mission.\nIt bears the symbol of a curved\nsword.",category=3},
[798]={id=798,name="antique automaton",plural="antique automatons",description="\nAn automaton found on Arrapago\nReef. It is no longer functioning.",category=3},
[799]={id=799,name="red bell",plural="red bells",description="\nA Mamool Ja bell, painted red.\nIt makes a clanging sound when swung.",category=2},
[800]={id=800,name="blue bell",plural="blue bells",description="\nA Mamool Ja bell, painted blue.\nIt makes a tinkling sound when swung.",category=2},
[801]={id=801,name="musical score - 1st page",plural="musical score - 1st page",description="\nA scroll covered in Moblin letters and\npictographs. You cannot read the\nMoblin words, but the pictographs have\nbeen drawn to be understandable to\nTrolls. The score seems to represent\na rhythm of some sort.",category=2},
[802]={id=802,name="musical score - 2nd page",plural="musical score - 2nd page",description="\nA scroll covered in Moblin letters and\npictographs. You cannot read the\nMoblin words, but the pictographs have\nbeen drawn to be understandable to\nTrolls. The score seems to represent\na rhythm of some sort.",category=2},
[803]={id=803,name="Merrow homunculus",plural="Merrow homunculli",description="\nA flask containing a tiny Merrow.\nShe is small enough to fit on the palm\nof your hand, but appears to be an\nactual living being. You can hear the\nsoft sound of her breathing as she\nsleeps...",category=2},
[804]={id=804,name="Lamia homunculus",plural="Lamia homunculli",description="\nA flask containing a tiny Lamia.\nShe is small enough to fit on the palm\nof your hand, but appears to be an\nactual living being. When you peer\ninside, she glares at you angrily...",category=2},
[805]={id=805,name="Munahda's package",plural="Munahda's packages",description="\n\"Furnishings. Handle with care.\" is\nwritten on the top of this box.\nIt rattles when shaken.",category=2},
[806]={id=806,name="white handkerchief",plural="white handkerchiefs",description="\nThis handkerchief was given to you\nby a chocobo trainer. It smells\nfaintly of soap.",category=2},
[807]={id=807,name="confidential Imperial order",plural="confidential Imperial orders",description="\nA top-secret order written in runes\nand graced with the mark of Zahak.\nThis order will break the seal at\nthe staging point, but the contents\nwill vanish if it falls into the hands\nof the enemy.",category=2},
[808]={id=808,name="secret Imperial order",plural="secret Imperial orders",description="\nA top-secret order written in runes\nand graced with the mark of Zahak.\nThis order will break the seal at\nthe staging point, but the contents\nwill vanish if it falls into the hands\nof the enemy.",category=2},
[809]={id=809,name="handkerchief",plural="handkerchiefs",description="\nThis handkerchief has the Vana'diel\nChocobo Society logo imprinted on\nit.",category=2},
[810]={id=810,name="dirty handkerchief",plural="dirty handkerchiefs",description="\nA used handkerchief that smells\nfaintly of sweat and chocobos.",category=2},
[811]={id=811,name="Replay Debugger",plural="Replay Debuggers",description="\nFor GM use only!",category=2},
[812]={id=812,name="astral compass",plural="astral compasses",description="\nA compass that detects powerful\nastral emanations and displays the\nlocation on a map. An improved\nversion of the crystal compass\ncreated by the Imperial Alchemists'\nGuild.",category=3},
[813]={id=813,name="vial of spectral scent",plural="vials of spectral scent",description="\nA scent made by Pyopyoroon that is\nmeant to attract ghosts. The\ncontents of the vial have been\nmixed with the digestive fluids of a\nrare malboro.",category=2},
[814]={id=814,name="empty test tube #1",plural="empty test tube #1",description="\nAn empty test tube you received\nfrom the alchemist Nafiwaa. Used to\ncollect water from a Mythralline\nSpring.",category=3},
[815]={id=815,name="empty test tube #2",plural="empty test tube #2",description="\nAn empty test tube you received\nfrom the alchemist Nafiwaa. Used to\ncollect water from a Mythralline\nSpring.",category=3},
[816]={id=816,name="empty test tube #3",plural="empty test tube #3",description="\nAn empty test tube you received\nfrom the alchemist Nafiwaa. Used to\ncollect water from a Mythralline\nSpring.",category=3},
[817]={id=817,name="empty test tube #4",plural="empty test tube #4",description="\nAn empty test tube you received\nfrom the alchemist Nafiwaa. Used to\ncollect water from a Mythralline\nSpring.",category=3},
[818]={id=818,name="empty test tube #5",plural="empty test tube #5",description="\nAn empty test tube you received\nfrom the alchemist Nafiwaa. Used to\ncollect water from a Mythralline\nSpring.",category=3},
[819]={id=819,name="test tube #1",plural="test tube #1",description="\nA test tube containing\nocher-colored water from a\nMythralline Spring in the Wajaom\nWoodlands.",category=2},
[820]={id=820,name="test tube #2",plural="test tube #2",description="\nA test tube containing\npurple-colored water from a\nMythralline Spring in the Wajaom\nWoodlands.",category=2},
[821]={id=821,name="test tube #3",plural="test tube #3",description="\nA test tube containing bluish\ngreen water from a Mythralline\nSpring in the Wajaom Woodlands.",category=2},
[822]={id=822,name="test tube #4",plural="test tube #4",description="\nA test tube containing yellowish\ngreen water from a Mythralline\nSpring in the Wajaom Woodlands.",category=2},
[823]={id=823,name="test tube #5",plural="test tube #5",description="\nA test tube containing milky-white\nwater from a Mythralline Spring\nin Bhaflau Thickets.",category=2},
[824]={id=824,name="quartz transmitter",plural="quartz transmitters",description="\nA tiny device that transmits a signal\nto a corresponding crystal compass.\nNo bigger than a coin, the\ntransmitter emits a powerful astral\npulse and runs on mythralline liquid.\nThere are many Imperial citizens who\nunknowingly carry these transmitters.",category=2},
[825]={id=825,name="S Wildcat badge",plural="S Wildcat badges",description="\nA silver Sergeant mercenary\nbadge from \"Salaheem's Sentinels.\"\nThree scintillant moat carps are\nemblazoned in its center.",category=2},
[826]={id=826,name="SM Wildcat badge",plural="SM Wildcat badges",description="\nA mythril Sergeant Major mercenary\nbadge from \"Salaheem's Sentinels.\"\nA scintillant salmon is emblazoned\nin its center.",category=2},
[827]={id=827,name="CS Wildcat badge",plural="CS Wildcat badges",description="\nA mythril Chief Sergeant mercenary\nbadge from \"Salaheem's Sentinels.\"\nTwo scintillant salmons are\nemblazoned in its center.",category=2},
[828]={id=828,name="chunk of glittering ore",plural="chunks of glittering ore",description="\nAn unidentified chunk of glittering\nore, extracted under duress at the\nPalborough Mines.",category=2},
[829]={id=829,name="Brand of the Springserpent",plural="Brands of the Springserpent",description="\nA blue magic brand you received\nfrom the Immortal stationed at the\nIlrusi Atoll staging point.",category=2},
[830]={id=830,name="Brand of the Galeserpent",plural="Brands of the Galeserpent",description="\nA blue magic brand you received\nfrom the Immortal stationed at the\nDvucca Isle staging point.",category=2},
[831]={id=831,name="Brand of the Flameserpent",plural="Brands of the Flameserpent",description="\nA blue magic brand you received\nfrom the Immortal stationed at the\nHalvung staging point.",category=2},
[832]={id=832,name="Brand of the Skyserpent",plural="Brands of the Skyserpent",description="\nA blue magic brand you received\nfrom the Immortal stationed at the\nMamool Ja staging point.",category=2},
[833]={id=833,name="Brand of the Stoneserpent",plural="Brands of the Stoneserpent",description="\nA blue magic brand you received\nfrom the Immortal stationed at the\nAzouph Isle staging point.",category=2},
[834]={id=834,name="magus order slip",plural="magus order slips",description="\nThis order slip must be presented to\nclaim your completed piece of magus\narmor.",category=2},
[835]={id=835,name="sealed Immortal envelope",plural="sealed Immortal envelopes",description="\nThere is an address written on the\nenvelope:\nImperial Livery\n2nd Floor, Balrahn Way\nIt is sealed with the Mark of Zahak.",category=2},
[837]={id=837,name="story of an impatient chocobo",plural="stories of an impatient chocobo",description="\nA story Hantileon tells the chocobos\nunder his care.",category=2},
[838]={id=838,name="story of a curious chocobo",plural="stories of a curious chocobo",description="\nA story Brutus tells the chocobos\nunder his care.",category=2},
[839]={id=839,name="story of a worrisome chocobo",plural="stories of a worrisome chocobo",description="\nA story Zopago tells the chocobos\nunder his care.",category=2},
[840]={id=840,name="story of a youthful chocobo",plural="stories of a youthful chocobo",description="\nA story Pulonono tells the chocobos\nunder her care.",category=2},
[841]={id=841,name="story of a happy chocobo",plural="stories of a happy chocobo",description="\nA story Bashraf tells the chocobos\nunder his care.",category=2},
[842]={id=842,name="Mamool Ja mandate",plural="Mamool Ja mandates",description="\nThis short wooden slat is inscribed\nwith incomprehensible Mamool Ja\nletters. The official-looking mark at\nthe bottom appears to be granting\nthe bearer some sort of authority or\npermission.",category=2},
[843]={id=843,name="Valkeng's memory chip",plural="Valkeng's memory chips",description="\nA small chip handed to you by\nShamarhaan. Numerous tiny lambent\ncells glimmer on its surface.",category=2},
[844]={id=844,name="toggle switch",plural="toggle switches",description="\nA bronze switch that looks to have\nbeen made by moblins. It makes a\nclanking sound when used.",category=2},
[845]={id=845,name="Leleroon's letter (green)",plural="Leleroon's letters (green)",description="\nA letter from Leleroon addressed\nto a member of the Seagull Phratrie.\nIt smells faintly like a Qiqirn.\nThe address is difficult to make\nout, but it seems to say \"Big treee\nnation.\"",category=2},
[846]={id=846,name="Leleroon's letter (blue)",plural="Leleroon's letters (blue)",description="\nA letter from Leleroon addressed\nto a member of the Seagull Phratrie.\nIt smells faintly like a Qiqirn.\nThe address is difficult to make\nout, but it seems to say \"Mountain\nmen, strooong and rocks nation.\"",category=2},
[847]={id=847,name="Leleroon's letter (red)",plural="Leleroon's letters (red)",description="\nA letter from Leleroon addressed\nto a member of the Seagull Phratrie.\nIt smells faintly like a Qiqirn.\nThe address is difficult to make\nout, but it seems to say \"Fooorest\nand castle nation.\"",category=2},
[848]={id=848,name="life float",plural="life floats",description="\nA long, thin inflatable made of\nmanta leather. New Seagull Phratrie\nmembers must wear this, but will be\nleft behind if they fall overboard\nduring a battle. Such knowledge\ntests their will to become corsairs.",category=2},
[849]={id=849,name="wheel lock trigger",plural="wheel lock triggers",description="\nA variety of firing mechanism for a\ntype of gun once popular with the\ncorsairs. This style is no longer\nwidely used due to the fact that it\nuses complex Ephramadian gears\nthat make mass production difficult.",category=2},
[850]={id=850,name="story of a diligent chocobo",plural="stories of a diligent chocobo",description="\nA Far Eastern tale of a hard-working\nchocobo. One day, while digging on his\nfarm, the chocobo finds buried treasure.\nHowever, the kingdom's wicked bugard\nsultan becomes envious of the chocobo\nand locks him up in the palace dungeons.\nBut thanks to a rose that he plants by\nthe window of the cell, his friends are\nable to find and save him. The end.",category=2},
[851]={id=851,name="prairie chocograph",plural="prairie chocographs",description="\nThe Vana'diel Chocobo Society hereby\ngrants [insert name here] permission\nto participate in the Chocobo Hot and\nCold Game in the following areas:\n1. La Theine Plateau\n2. Konschtat Highlands\n3. Tahrongi Canyon\n                         Valid until death.",category=2},
[852]={id=852,name="bush chocograph",plural="bush chocographs",description="\nThe Vana'diel Chocobo Society hereby\ngrants [insert name here] permission\nto participate in the Chocobo Hot and\nCold Game in the following areas:\n1. Jugner Forest\n2. Pashhow Marshlands\n3. Meriphataud Mountains\n                         Valid until death.",category=2},
[853]={id=853,name="letter from Bernahn",plural="letters from Bernahn",description="\nThis elegantly written note has been\nplaced inside an envelope of\nsurpassing quality.\nIt is addressed to Galiwao.",category=2},
[854]={id=854,name="Remnants Permit",plural="Remnants Permits",description="\nAn odd circle of papyrus filled\ncompletely with complex cuneiform\ncharacters. This permit should allow\nyou entrance into the restricted\nareas of the Ruins of Alzadaal...",category=2},
[855]={id=855,name="lilac ribbon",plural="lilac ribbons",description="\nA beautiful lilac ribbon made of\nvelvet. There is a dark stain marring\nits perfection...",category=2},
[856]={id=856,name="coastal chocograph",plural="coastal chocographs",description="\nThe Vana'diel Chocobo Society hereby\ngrants [insert name here] permission\nto participate in the Chocobo Hot and\nCold Game in the following areas:\n1. Buburimu Peninsula\n                         Valid until death.",category=2},
[857]={id=857,name="dune chocograph",plural="dune chocographs",description="\nThe Vana'diel Chocobo Society hereby\ngrants [insert name here] permission\nto participate in the Chocobo Hot and\nCold Game in the following areas:\n1. Valkurm Dunes\n                         Valid until death.",category=2},
[858]={id=858,name="jungle chocograph",plural="jungle chocographs",description="\nThe Vana'diel Chocobo Society hereby\ngrants [insert name here] permission\nto participate in the Chocobo Hot and\nCold Game in the following areas:\n1. Yuhtunga Jungle\n2. Yhoator Jungle\n                         Valid until death.",category=2},
[859]={id=859,name="desert chocograph",plural="desert chocographs",description="\nThe Vana'diel Chocobo Society hereby\ngrants [insert name here] permission\nto participate in the Chocobo Hot and\nCold Game in the following areas:\n1. Eastern Altepa Desert\n2. Western Altepa Desert\n                         Valid until death.",category=2},
[860]={id=860,name="Periqia Assault area entry permit",plural="Periqia Assault area entry permits",description="\nA provisional document that\nauthorizes you to enter the Periqia\nAssault area.",category=2},
[861]={id=861,name="warrior's armor claim slip",plural="warrior's armor claim slips",description="\n\"Holding\n\n 1 set of warrior relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[862]={id=862,name="melee attire claim slip",plural="melee attire claim slips",description="\n\"Holding\n\n 1 set of monk relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[863]={id=863,name="cleric's attire claim slip",plural="cleric's attire claim slips",description="\n\"Holding\n\n 1 set of white mage relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[864]={id=864,name="sorcerer's attire claim slip",plural="sorcerer's attire claim slips",description="\n\"Holding\n\n 1 set of black mage relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[865]={id=865,name="duelist's armor claim slip",plural="duelist's armor claim slips",description="\n\"Holding\n\n 1 set of red mage relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[866]={id=866,name="assassin's attire claim slip",plural="assassin's attire claim slips",description="\n\"Holding\n\n 1 set of thief relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=3},
[867]={id=867,name="valor armor claim slip",plural="valor armor claim slips",description="\n\"Holding\n\n 1 set of paladin relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[868]={id=868,name="abyss armor claim slip",plural="abyss armor claim slips",description="\n\"Holding\n\n 1 set of dark knight relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=3},
[869]={id=869,name="monster armor claim slip",plural="monster armor claim slips",description="\n\"Holding\n\n 1 set of beastmaster relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[870]={id=870,name="bard's attire claim slip",plural="bard's attire claim slips",description="\n\"Holding\n\n 1 set of bard relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[871]={id=871,name="scout's attire claim slip",plural="scout's attire claim slips",description="\n\"Holding\n\n 1 set of ranger relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[872]={id=872,name="saotome armor claim slip",plural="saotome armor claim slips",description="\n\"Holding\n\n 1 set of samurai relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[873]={id=873,name="koga garb claim slip",plural="koga garb claim slips",description="\n\"Holding\n\n 1 set of ninja relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[874]={id=874,name="wyrm armor claim slip",plural="wyrm armor claim slips",description="\n\"Holding\n\n 1 set of dragoon relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[875]={id=875,name="summoner's attire claim slip",plural="summoner's attire claim slips",description="\n\"Holding\n\n 1 set of summoner relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[876]={id=876,name="scourshroom",plural="scourshrooms",description="\nA rare mushroom that only grows\nwithin the Aydeewa Subterrane.\nBoiled together with olive oil, it is\nthe main ingredient in the potent\ncleaner known as \"rustkiller.\"",category=2},
[877]={id=877,name="percipient eye",plural="percipient eyes",description="\nA translucent blue stone hanging\nfrom a leather cord. Enables the\nbearer to pierce the spell of\nconcealment upon the Ephramadian\ntreasure in Talacca Cove.",category=2},
[878]={id=878,name="Nyzul Isle Assault orders",plural="Nyzul Isle Assault orders",description="\nA document that authorizes you to\ntake part in a Nyzul Isle Assault\nmission.",category=2},
[879]={id=879,name="runic disc",plural="runic discs",description="\nAn enigmatic disc you obtained on\nNyzul Isle.\nRequired to operate the Rune of\nTransfer.",category=2},
[880]={id=880,name="runic key",plural="runic keys",description="\nAn enigmatic key you obtained on\nFloor 100 of Nyzul Isle.",category=2},
[881]={id=881,name="Gysahl Medal",plural="Gysahl Medals",description="\nThis bronze medal of honor has been\nawarded to you by the CRA for your\naccomplishments in chocobo racing.",category=2},
[882]={id=882,name="Rossweisse's feather",plural="Rossweisse's feathers",description="\nA transparent feather from the wing\nof the valkyrie, Rossweisse.",category=2},
[883]={id=883,name="Grimgerde's feather",plural="Grimgerde's feathers",description="\nA transparent feather from the wing\nof the valkyrie, Grimgerde.",category=2},
[884]={id=884,name="Siegrune's feather",plural="Siegrune's feathers",description="\nA transparent feather from the wing\nof the valkyrie, Siegrune.",category=2},
[885]={id=885,name="Helmwige's feather",plural="Helmwige's feathers",description="\nA transparent feather from the wing\nof the valkyrie, Helmwige.",category=2},
[886]={id=886,name="Schwertleite's feather",plural="Schwertleite's feathers",description="\nA transparent feather from the wing\nof the valkyrie, Schwertleite.",category=2},
[887]={id=887,name="Waltraute's feather",plural="Waltraute's feathers",description="\nA transparent feather from the wing\nof the valkyrie, Waltraute.",category=2},
[888]={id=888,name="Ortlinde's feather",plural="Ortlinde's feathers",description="\nA transparent feather from the wing\nof the valkyrie, Ortlinde.",category=3},
[889]={id=889,name="Gerhilde's feather",plural="Gerhilde's feathers",description="\nA transparent feather from the wing\nof the valkyrie, Gerhilde.",category=2},
[890]={id=890,name="Brunhilde's feather",plural="Brunhilde's feathers",description="\nA transparent feather from the wing\nof the valkyrie, Brunhilde.",category=2},
[891]={id=891,name="Mark of the Einherjar",plural="Marks of the Einherjar",description="\nThe following rune inscription has\nbeen carved on this crimson stone:\n\nSauuage Einherjar, thou hast bien\ngraunted audiens at ye Yhates of\nye Underverden.",category=2},
[892]={id=892,name="photopticator",plural="photopticators",description="\nThis improved recording device\ncan capture up to five seconds\nof moving images.",category=2},
[893]={id=893,name="luminian dagger",plural="luminian daggers",description="A short mythril blade given to you\nby Nashmeira. The pommel of the\ndagger is wrought in luminian and\ngraced by the Mark of Zahak.",category=2},
[894]={id=894,name="SL Wildcat badge",plural="SL Wildcat badges",description="\nA gold Second Lieutenant mercenary\nbadge from \"Salaheem's Sentinels.\"\nA scintillant tuna is emblazoned\nin its center.",category=2},
[895]={id=895,name="Biyaada's letter",plural="Biyaada's letters",description="\nAn introduction letter penned by\nBiyaada, the senior adjutant to the\nSkyserpent General. It should prove\nhelpful when you meet the aides to\nthe other Serpent Generals.",category=2},
[896]={id=896,name="Officer Academy manual",plural="Officer Academy manuals",description="\n\"Be the best that you can be!\nPay your tuition fee to Abquhbah of\nSalaheem's Sentinels and prepare for\nthe excitement of Officer Academy!\"",category=3},
[897]={id=897,name="Allied Council Summons",plural="Allied Council Summons",description="\nYou have been summoned to the\nAllied Military Council being held in\nthe Grand Duke Palace in Jeuno.\nThe summons is signed by Trion,\nVolker, Shantotto, and Wolfgang.",category=3},
[898]={id=898,name="Nyzul Isle route",plural="Nyzul Isle route",description="\nA map hastily drawn by Travialce.\nIt shows the route Luzaf's captors\nused to take him through Nyzul Isle.",category=2},
[899]={id=899,name="mythril mirror",plural="mythril mirror",description="\nA circular mirror made of gleaming\nmythril. A finely-engraved pattern\non its surface refracts the light in\nunusual angles, making reflections\nhazy and unclear. A relief of the\nSerpentking Zahak is carved on the\nback of the mirror.",category=2},
[900]={id=900,name="FL Wildcat badge",plural="FL Wildcat badges",description="\nA gold First Lieutenant mercenary\nbadge from \"Salaheem's Sentinels.\"\nTwo scintillant tuna are emblazoned\nin its center.",category=2},
[908]={id=908,name="Chocobo Circuit grandstand pass",plural="Chocobo Circuit grandstand passes",description="\nThis pass allows free admission to\nthe Chocobo Circuit grandstand.\nIt does not appear to have an\nexpriration date.",category=2},
[909]={id=909,name="Captain Wildcat badge",plural="Captain Wildcat badges",description="\nA gold Captain mercenary badge\nfrom \"Salaheem's Sentinels.\"\nThree scintillant tuna are emblazoned\nin its center.",category=2},
[910]={id=910,name="pure white feather",plural="pure white feathers",description="\nA feather that suddenly appeared in\nyour grasp. It glows with a soft\nplatinum light.",category=2},
[911]={id=911,name="stardust pebble",plural="stardust pebbles",description="\nA brightly glowing stone found in\nLake Mechieume during the time of\nthe Great War. The pebbles were so\navidly sought after that not a single\none remains in the lake today.",category=2},
[912]={id=912,name="left map piece",plural="left map pieces",description="\nOne fragment of a map of Grauberg.\nThis piece only shows about a third\nof the entire area.",category=2},
[913]={id=913,name="middle map piece",plural="middle map pieces",description="\nOne fragment of a map of Grauberg.\nThis piece only shows about a third\nof the entire area.",category=2},
[914]={id=914,name="right map piece",plural="right map pieces",description="\nOne fragment of a map of Grauberg.\nThis piece only shows about a third\nof the entire area.",category=2},
[915]={id=915,name="sequined Ballista chevron",plural="sequined Ballista chevrons",description="\nPresented only to those dancers\nwho have displayed excellence on\nthe Ballista battlefield.\n\n※Must be returned to a Herald\nafter a set period indicated in\nthe official Ballista rulebook.",category=2},
[916]={id=916,name="velvet Ballista chevron",plural="velvet Ballista chevrons",description="\nPresented only to those scholars\nwho have displayed excellence on\nthe Ballista battlefield.\n\n※Must be returned to a Herald\nafter a set period indicated in\nthe official Ballista rulebook.",category=2},
[917]={id=917,name="battle rations",plural="battle rations",description="\nA heavy box marked...\n\n ★Republican Legion\n ★Fourth Division\n ★Seventh Cohors\n ★Eduard Watchtower, N. Gustaberg",category=2},
[918]={id=918,name="clump of animal hair",plural="clump of animal hair",description="\nMaterial used in the construction of\na string instrument. You're not sure\nwhat animal the hair comes from...",category=2},
[919]={id=919,name="xhifhut",plural="xhifhuti",description="\nA Goblin-made instrument\nconsisting of four main parts:\nstrings, body, bow, and head.\nThe sound created by the xhifhut\nclosely resembles the fricative\nnoises made within the Antica's\nnecks, and is thus often used\nfor inter-species communication.",category=2},
[920]={id=920,name="warning letter",plural="warning letters",description="\nA letter pressed into your hand by a\nstrange Galka while you stood\noutside Engelhart's store.\nIt simply reads, \"Stay out of this.\"",category=2},
[921]={id=921,name="red recommendation letter",plural="red recommendation letters",description="\nA letter recommending your\nadmission to the Knights of\nthe Iron Ram.",category=2},
[922]={id=922,name="blue recommendation letter",plural="blue recommendation letters",description="\nA letter recommending your\nadmission to the Fourth Division of\nthe Republican Legion.",category=2},
[923]={id=923,name="green recommendation letter",plural="green recommendation letters",description="\nA letter recommending your\nadmission to the Mithra Mercenary\nReserve's Cobra Unit.",category=2},
[924]={id=924,name="Bronze Ribbon of Service ∮",plural="Bronze Ribbons of Service",description="\nA tiny bronze medal attached to a\nred and white ribbon. Awarded for\nservice in the Allied Campaign.",category=2},
[925]={id=925,name="Brass Ribbon of Service ∮∮",plural="Brass Ribbons of Service",description="\nA tiny brass medal attached to a\nred and white ribbon. Awarded for\nservice on the campaign battlefield.",category=3},
[926]={id=926,name="Allied Ribbon of Bravery ∮∮∮",plural="Allied Ribbons of Bravery",description="\nA tiny silver medal attached to a\nred and white ribbon. Awarded for\noutstanding service on the campaign\nbattlefield.",category=3},
[927]={id=927,name="Allied Ribbon of Glory ∮∮∮∮",plural="Allied Ribbons of Glory",description="\nA tiny mythril medal attached to a\nred and white ribbon. Awarded for\nexemplary performance in campaign\noperations. The most prestigious\nribbon obtainable.",category=3},
[928]={id=928,name="Bronze Star ∮",plural="Bronze Stars",description="\nA bronze star engraved with clashing\nswords. Awarded for service on the\ncampaign front.",category=2},
[929]={id=929,name="Sterling Star ∮∮",plural="Sterling Stars",description="\nA silver star engraved with clashing\nswords. Awarded for bravery on the\ncampaign front.",category=2},
[930]={id=930,name="Mythril Star ∮∮∮",plural="Mythril Stars",description="\nA mythril star engraved with clashing\nswords. Awarded for outstanding\nservice on the campaign front.",category=2},
[931]={id=931,name="Golden Star ∮∮∮∮",plural="Golden Stars",description="\nA gold star engraved with clashing\nswords. Awarded for exemplary\nservice on the campaign front. The\nmost prestigious star obtainable.",category=2},
[932]={id=932,name="Copper Emblem of Service ∮",plural="Copper Emblems of Service",description="\nA solid copper emblem designed to\nresemble a crystal. Awarded for\nachievements within the Allied\nCampaign.",category=2},
[933]={id=933,name="Iron Emblem of Service ∮∮",plural="Iron Emblems of Service",description="\nA solid iron emblem designed to\nresemble a crystal. Awarded for\nrepeated achievements within the\nAllied Campaign.",category=3},
[934]={id=934,name="Steelknight Emblem ∮∮∮",plural="Steelknight Emblems",description="\nA solid steel emblem designed to\nresemble a crystal. Awarded for\noutstanding achievements within the\nAllied Campaign.",category=2},
[935]={id=935,name="Holyknight Emblem ∮∮∮∮",plural="Holyknight Emblems",description="\nA solid darksteel emblem designed\nto resemble a crystal. Awarded for\nexemplary achievements within the\nAllied Campaign.",category=2},
[936]={id=936,name="Brass Wings of Service ∮",plural="Brass Wings of Service",description="\nA pair of wings forged from brass.\nAwarded for continued service to\nthe Allied Campaign.",category=2},
[937]={id=937,name="Mythril Wings of Service ∮∮",plural="Mythril Wings of Service",description="\nA pair of wings forged from pure\nmythril. Awarded for extended\nservice to the Allied Campaign.",category=3},
[938]={id=938,name="Wings of Integrity ∮∮∮",plural="Wings of Integrity",description="\nA pair of wings forged from pure\ngold. Awarded for loyal service to\nthe Allied Campaign.",category=2},
[939]={id=939,name="Wings of Honor ∮∮∮∮",plural="Wings of Honor",description="\nA pair of wings forged from pure\nplatinum. Awarded for undying\nloyalty to the Allied Campaign. The\nmost prestigious wings obtainable.",category=2},
[940]={id=940,name="Starlight Medal ∮",plural="Starlight Medal",description="\nA ruby star set in the center of a\ngold medal. Awarded to champions\nof the Allied Campaign.",category=2},
[941]={id=941,name="Moonlight Medal ∮∮",plural="Moonlight Medals",description="\nA sapphire moon set in the center\nof a platinum medal. Awarded to\nheroes of the Allied Campaign.",category=2},
[942]={id=942,name="Dawnlight Medal ∮∮∮",plural="Dawnlight Medals",description="\nA remarkably scintillant medal of\npure luminium. Awarded to legends\nof the Allied Campaign.",category=2},
[943]={id=943,name="Medal of Altana ∮∮∮∮",plural="Medals of Altana",description="\nAn adaman medal engraved with the\noutline of the Dawn Goddess.\nAwarded to saviors of the Allied\nCampaign. The most prestigious\ndecoration obtainable.",category=2},
[944]={id=944,name="sliced pole",plural="sliced poles",description="\nA pole you found at an Orc lookout\nplatform in Jugner Forest. The pole\nhas been sliced length-wise, creating\na half-moon shape on its ends.",category=2},
[945]={id=945,name="supply order",plural="supply orders",description="\nA list of supplies requested by\nthe army's quartermaster.",category=2},
[946]={id=946,name="grimoire",plural="grimoires",description="\nA copy of an ancient magical tome\naugmented with various military\nstrategies.\nIts astral properties allow the\npossessor to command the grimoire\nto appear and disappear at will.",category=2},
[947]={id=947,name="Zonpa-Zippa's All-Purpose Putty",plural="Zonpa-Zippa's All-Purpose Putty",description="\nGuaranteed to perfectly patch up\nany problem, or your money back.",category=4},
[948]={id=948,name="Scoop-Dedicated Linkpearl",plural="Scoop-Dedicated Linkpearls",description="\nA linkpearl created by Naiko-Paneiko\nsolely for transmitting only the\nhottest in news, leads, and scoops.",category=2},
[949]={id=949,name="firepower case",plural="firepower cases",description="\nA case containing munitions for a\nvariety of firearms and artillery. A\nsign reading \"Keep Away From\nFire!\" is affixed to the front.",category=2},
[950]={id=950,name="charred propeller",plural="charred propellers",description="\nLinen cloth loosely hangs from the\nburnt remnants of a wooden frame.",category=2},
[951]={id=951,name="piece of shattered lumber",plural="pieces of shattered lumber",description="\nSeveral crystal shards lie deeply\nimbedded in this splinter of wood.",category=2},
[952]={id=952,name="oxidized plate",plural="oxidized plates",description="\nA brass plate bearing the letters\nE, O, and S.",category=3},
[953]={id=953,name="piece of kionite",plural="pieces of kinoite",description="\nA lustrous blue stone taken from\nVunkerl Inlet.",category=2},
[954]={id=954,name="Ranpi-Monpi Specialty",plural="Ranpi-Monpi Specialties",description="\nA specialty dish prepared for you\nby Ranpi-Monpi with a somewhat\nunseemly appearance. It has a very\nunique aroma...",category=2},
[955]={id=955,name="culinary knife",plural="culinary knives",description="\nA cooking knife given to you by\nRanpi-Monpi. It appears to be\nwell used, with many nicks and\nblemishes visible on the blade.",category=2},
[956]={id=956,name="fireblossom",plural="fireblossoms",description="\nA beautiful, perennial flower that\ngrows in Grauberg.",category=2},
[957]={id=957,name="\"The Healing Herb\"",plural="\"The Healing Herb\"",description="\nAn academic journal on herbalism,\npublished in the Far East.\nIt focuses primarily on the medicinal\nproperties of herbs.",category=2},
[958]={id=958,name="small starfruit",plural="small starfruits",description="\nA small starfruit secretly planted by\nthe young Ajido-Marujido.",category=2},
[959]={id=959,name="inky black Yagudo feather",plural="inky black Yagudo feathers",description="\nA Yagudo feather dropped by the\nyoung Ajido-Marujido. It is much\nlarger than a normal Yagudo feather,\nand radiates a distinct malevolence.",category=3},
[960]={id=960,name="campaign supplies",plural="campaign supplies",description="\nAn important package of\nsupplies to be delivered\nto your nation's stronghold.",category=2},
[961]={id=961,name="mine shaft key",plural="mine shaft keys",description="\nA key used by the Quadav in\nthe mines of Pashhow.",category=2},
[962]={id=962,name="\"The Essence of Dance\"",plural="\"The Essence of Dance\"",description="\nA textbook that provides practical\ninformation on dancing at the\nadvanced level.\nWritten by Annika Brilioth.",category=2},
[963]={id=963,name="Jugner gate crystal",plural="Jugner gate crystals",description="\nA forgotten gate crystal found in\nthe Jugner Forest of the past.\n\nNeeded to teleport to Jugner\nForest [S].",category=2},
[964]={id=964,name="Pashhow gate crystal",plural="Pashhow gate crystals",description="\nA forgotten gate crystal found in\nthe Pashhow Marshlands of the past.\n\nNeeded to teleport to Pashhow\nMarshlands [S].",category=2},
[965]={id=965,name="Meriphataud gate crystal",plural="Meriphataud gate crystals",description="\nA forgotten gate crystal found in\nthe Meriphataud Mountains of the\npast.\n\nNeeded to teleport to Meriphataud\nMountains [S].",category=2},
[966]={id=966,name="Vunkerl herb",plural="Vunkerl herbs",description="\nSupposedly the rare herb found\nonly in Vunkerl Inlet.",category=2},
[967]={id=967,name="Vunkerl herb memo",plural="Vunkerl herb memos",description="\n00:00～07:59  San d'Oria\n08:00～15:59  Bastok\n16:00～23:59  Windurst",category=2},
[968]={id=968,name="evil warding seal",plural="evil warding seals",description="\nA seal that wards off evil through the white magic of the San d'Orian Cathedral.",category=3},
[969]={id=969,name="ornate package",plural="ornate packages",description="\nA neatly wrapped package adorned\nwith the crest of the San d'Orian\nCathedral.",category=3},
[970]={id=970,name="sheaf of handmade incense",plural="sheaves of handmade incense",description="\nSpecial incense given to you by\nPecca-Pocca. Used as an offering\nto honor the memory of the\ndeparted.",category=2},
[971]={id=971,name="leather-bound book",plural="leather-bound books",description="\nA book Yoran-Oran borrowed from\nthe Library of Magic. The title,\n\"Forlorn Beauty,\" suggests it\nto be a romance novel.",category=2},
[972]={id=972,name="lynx pelt",plural="lynx pelts",description="\nAn old lynx pelt you found inside\nCastle Oztroja. It looks to have\nbeen dropped by someone.",category=2},
[973]={id=973,name="Wyatt's proposal",plural="Wyatt's proposals",description="\nA proposal for a collaborative\nperformance between troupes\nBrilioth and Valeriano.",category=2},
[974]={id=974,name="fort key",plural="fort keys",description="\nA key used to open doors in\nFort Karugo-Narugo",category=2},
[975]={id=975,name="Ulbrecht's sealed letter",plural="Ulbrecht's sealed letters",description="\nA letter entrusted to you by\nUlbrecht and addressed to Prof.\nSchultz. Sealed with a heavy\nmagic, it appears impervious to\nconventional letter-opening\nmethods.",category=2},
[976]={id=976,name="Schultz's sealed letter",plural="Schultz's sealed letters",description="\nA letter entrusted to you by Prof.\nSchultz to be delivered to Ulbrecht.\nSealed with a heavy magic, it seems\nto be impervious to conventional\nletter-opening techniques.",category=2},
[977]={id=977,name="unaddressed sealed letter",plural="unaddressed sealed letters",description="\nA letter consisting of a single sheet\nbearing cryptic writing. It reads:\n Only when nourished and bathed in\n deep crimson depths of the most\n magicked bloods, shall the true\n tome of stratagems be borne. And\n that which riseth forth...",category=2},
[978]={id=978,name="porting magic transcript",plural="porting magic transcripts",description="\nA transcript of a stratagem taken by\nErlene that involves instantaneous\ntravel over great distances. A similar\nstratagem seems to be in existence\nsomewhere in Grauberg...",category=2},
[979]={id=979,name="sample of Grauberg chert",plural="samples of Grauberg chert",description="\nA viable sample of the hornlike\nchert which dominates the\nGrauberg landscape. Useful in\nsome forms of research.",category=2},
[980]={id=980,name="Drogarogan bonemeal",plural="Drogarogan bonemeal",description="\nA fine powder procured from\nthe enormous structure known\nas Drogaroga's Spine. Useful in\nsome forms of research.",category=2},
[981]={id=981,name="Slug mucus",plural="Slug mucus",description="\nThe viscous mucus left in the\nwake of a moving Slug. Sticky,\nwet, and disgusting. Useful in\nsome forms of research.",category=2},
[982]={id=982,name="Djinn ember",plural="Djinn embers",description="\nThe last vestigial flames of a\ndeceased Djinn. They burn with\nan air of maliciousness. Useful\nin some forms of research.",category=2},
[983]={id=983,name="Rafflesia dreamspit",plural="Rafflesia dreamspit",description="\nThe slumber-inducing liquid\nvomited forth by Rafflesia\nplants upon catching live prey.\nUseful in some forms of\nresearch.",category=2},
[984]={id=984,name="Peiste dung",plural="Peiste dung",description="\nThe fecal discharge of a wild, \nhealthy Peiste, the scent of\nwhich defies description. Useful\nin some forms of research.",category=2},
[985]={id=985,name="Ulbrecht's mortarboard",plural="Ulbrecht's mortarboards",description="\nThe characteristic mortarboard of a\nscholar. Left behind by Ulbrecht in\nthe haste of his escape.",category=2},
[986]={id=986,name="Beastman Confederate crate",plural="Beastman Confederate crates",description="\nA wooden cargo crate abandoned by\nthe Beastman Confederate, whose\nseal is branded on the outer surface.\nIt is extremely heavy.",category=2},
[987]={id=987,name="military scrip",plural="military scrip",description="\nA military bill issued by the\nRoyal Knights during the Crystal\nWar. Certified to be convertible\ninto any currency.",category=2},
[988]={id=988,name="silvermine key",plural="silvermine keys",description="\nA key used to gain access to the\nabandoned Silvermines.",category=2},
[989]={id=989,name="red prize balloon",plural="red prize balloons",description="\nA radiant red balloon you\nreceived as a prize for\nclearing hard mode at\nSpot the Difference.",category=2},
[990]={id=990,name="blue prize balloon",plural="blue prize balloons",description="\nA brilliant blue balloon\nyou received as a prize\nfor clearing hard mode at\nthe Shooting Gallery.",category=2},
[991]={id=991,name="green prize ballon",plural="green prize ballons",description="\nA gleaming green balloon\nyou received as a prize\nfor clearing hard mode at\nthe Chocobo Chick Catchery.",category=2},
[992]={id=992,name="Travonce's escort award",plural="Travonce's escort awards",description="\nA slip given to you by Tavonce\nacknowledging your successful\ncompletion of an escort behest.",category=2},
[993]={id=993,name="Ken's escort award",plural="Ken's escort awards",description="\nA slip given to you by Ken\nacknowledging your successful\ncompletion of an escort behest.",category=2},
[994]={id=994,name="Emptiness investigation note",plural="Emptiness investigation notes",description="\nA memo reminding you to assist\nyour fellow in an investigation\nof the Emptiness.",category=3},
[995]={id=995,name="tigris stone",plural="tigris stones",description="\nThis stone disk taken from an\nOrcish officer bears a crudely\nengraved tiger crest. It can be\nused as an access pass to Darkheir\nGrradhod's command center in\nLa Vaule.",category=2},
[996]={id=996,name="diamond seal",plural="diamond seals",description="\nThis diamond taken from a Quadav\nofficer has been masterfully cut\ninto the shape of the Quadav\nroyal seal. It is said to be the\nkey to the Qulun Dome, Za'Dha\nAdamantking's seat of power.",category=2},
[997]={id=997,name="Xicu's rosary",plural="Xicu's rosaries",description="\nThis ceremonial rosary taken\nfrom a Yagudo officer is made\nwith polished coral beads. Using\nit as an offering will open a\nsecret passageway to the Altar\nRoom, the sanctuary of Soo Luma\nthe Ascended.",category=2},
[998]={id=998,name="maroon seal",plural="maroon seals",description="\nA maroon Far Eastern tally seal\ngiven to you by Sanraku the\ntraveling painter.",category=2},
[999]={id=999,name="apple green seal",plural="apple green seals",description="\nAn apple green Far Eastern tally\nseal given to you by Sanraku\nthe traveling painter.",category=3},
[1000]={id=1000,name="charcoal grey seal",plural="charcoal grey seals",description="\nA charcoal grey Far Eastern tally\nseal given to you by Sanraku\nthe traveling painter.",category=2},
[1001]={id=1001,name="deep purple seal",plural="deep purple seals",description="\nA deep purple Far Eastern tally\nseal given to you by Sanraku\nthe traveling painter.",category=2},
[1002]={id=1002,name="chestnut-colored seal",plural="chestnut-colored seals",description="\nA chestnut-colored Far Eastern\ntally seal given to you by\nSanraku the traveling painter.",category=2},
[1003]={id=1003,name="lilac-colored seal",plural="lilac-colored seals",description="\nA lilac-colored Far Eastern\ntally seal given to you by\nSanraku the traveling painter.",category=2},
[1004]={id=1004,name="cerise seal",plural="cerise seals",description="\nA cerise Far Eastern tally seal\ngiven to you by Sanraku the\ntraveling painter.",category=2},
[1005]={id=1005,name="salmon-colored seal",plural="salmon-colored seals",description="\nA salmon-colored Far Eastern\ntally seal given to you by\nSanraku the traveling painter.",category=2},
[1006]={id=1006,name="purplish grey seal",plural="purplish grey seals",description="\nA purplish grey Far Eastern\ntally seal given to you by\nSanraku the traveling painter.",category=2},
[1007]={id=1007,name="gold-colored seal",plural="gold-colored seals",description="\nA gold-colored Far Eastern\ntally seal given to you by\nSanraku the traveling painter.",category=2},
[1008]={id=1008,name="copper-colored seal",plural="copper-colored seals",description="\nA copper-colored Far Eastern\ntally seal given to you by\nSanraku the traveling painter.",category=2},
[1009]={id=1009,name="bright blue seal",plural="bright blue seals",description="\nA bright blue Far Eastern\ntally seal given to you by\nSanraku the traveling painter.",category=2},
[1010]={id=1010,name="pine green seal",plural="pine green seals",description="\nA pine green Far Eastern tally\nseal given to you by Sanraku\nthe traveling painter.",category=2},
[1011]={id=1011,name="amber-colored seal",plural="amber-colored seals",description="\nAn amber-colored Far Eastern\ntally seal given to you by\nSanraku the traveling painter.",category=3},
[1012]={id=1012,name="fallow-colored seal",plural="fallow-colored seals",description="\nA fallow-colored Far Eastern\ntally seal given to you by\nSanraku the traveling painter.",category=2},
[1013]={id=1013,name="taupe-colored seal",plural="taupe-colored seals",description="\nA taupe-colored Far Eastern\ntally seal given to you by\nSanraku the traveling painter.",category=2},
[1014]={id=1014,name="sienna-colored seal",plural="sienna-colored seals",description="\nA sienna-colored Far Eastern\ntally seal given to you by\nSanraku the traveling painter.",category=2},
[1015]={id=1015,name="lavender-colored seal",plural="lavender-colored seals",description="\nA lavender-colored Far Eastern\ntally seal given to you by\nSanraku the traveling painter.",category=2},
[1016]={id=1016,name="Sicklemoon salt",plural="Sicklemoon salts",description="\nA solar-evaporated salt harvested\nfrom coastlines along the\nSicklemoon Straits. If it comes\nin contact with the engraved\ntablet at the\nWajaom Woodlands...",category=4},
[1017]={id=1017,name="Silver Sea salt",plural="Silver Sea salts",description="\nA solar-evaporated salt harvested\nfrom coastlines along the\nSilver Sea. If it comes in contact\nwith the engraved tablet at\nMount Zhayolm...",category=4},
[1018]={id=1018,name="Cyan Deep salt",plural="Cyan Deep salts",description="\nA solar-evaporated salt harvested\nfrom coastlines along the\nCyan Deep. If it comes in contact\nwith the engraved tablet at\nCaedarva Mire...",category=4},
[1019]={id=1019,name="Orcish warmachine body",plural="Orcish warmachine bodies",description="\nThe wooden body of an Orcish\nwarmachine stripped from a\nwreck found in the Jugner Forest.\nIt is in surprisingly serviceable\ncondition. ",category=3},
[1020]={id=1020,name="Paparoon's sealed invitation",plural="Paparoon's sealed invitations",description="\nA formal letter composed in a\nregal hand and bearing the\nimperial seal of the serpent.\nIt bears a signature in the\nwritten in the exotic Qiqirn\nlanguage.",category=2},
[1021]={id=1021,name="Data Analyzer and Logger EX",plural="Data Analyzer and Logger EX",description="\nA peculiar plush doll Rakuru-Rakoru\nfrom the Orastery has lent to you.\nDespite its endearing nickname,\n\"Dale,\" it is in fact a high-tech\ndevice that collects and analyzes\nmonster data from battles.",category=2},
[1022]={id=1022,name="Mayakov show ticket",plural="Mayakov show ticket",description="\nA ticket to admit one person to Troupe\nMayakov's dance performance. The\nshow is entitled \"Troupe Mayakov,\nTaking It to the Stars.\" It appears\nto be well worn with age and abuse,\nand could easily be mistaken for a\npiece of trash.",category=2},
[1023]={id=1023,name="Serpentking Zahak relief",plural="Serpentking Zahak reliefs",description="\nA detailed work in bas relief of\nthe Serpentking Zahak, in all his\ntwo-headed glory. The piece strikes\nyou as considerably old.",category=2},
[1024]={id=1024,name="Sakura racing badge",plural="Sakura racing badges",description="\nA luminescent tin badge, embossed\nwith an effigy in profile of none\nother that the adorable icon of\nchocobo racing herself, everyone's\nbeloved Sakura.",category=2},
[1025]={id=1025,name="Serpentking Zahak relief shard",plural="Serpentking Zahak relief shards",description="\nA mere fragment of what was\nno doubt an inspiring likeness of\nSerpentking Zahak. Sadly, only one\nhead remains. The piece strikes you\nas considerably old.",category=2},
[1026]={id=1026,name="\"Imperial Lineage\" chapter I",plural="\"Imperial Lineage\" chapter I",description="\nA chapter from an unabridged account\nof the genealogy of all Orcish\nsovereigns to date, as recorded by\nGoblin scribes. Those who recite the\nwork in its entirety are said to be\ngranted an audience with His Imperial\nMajesty, the Emperor himself.",category=3},
