[1041]={id=1041,name="The Words of Do'Nhu VIII",plural="The Words of Do'Nhu VIII",description="\nThe last of eight tablets inscribed\nwith the words of the Quadav god\nDo'Nhu. Legend has it that Do'Nhu's\ncounterpart deity, Gu'Dha, will\nappear before he who cantillates\nthe inscriptions on all tablets.",category=2},
[1042]={id=1042,name="Habalo's Eclogue - verse I",plural="Habalo's Eclogue - verse I",description="\nThe first verse of the eclogue penned\nby the first Yagudo Manifest, Ree\nHabalo. It is said that he who\nrecites all eight verses will be\nvisited by the Yagudo of legend.",category=2},
[1043]={id=1043,name="Habalo's Eclogue - verse II",plural="Habalo's Eclogue - verse II",description="\nThe second verse of the eclogue penned\nby the first Yagudo Manifest, Ree\nHabalo. It is said that he who\nrecites all eight verses will be\nvisited by the Yagudo of legend.",category=2},
[1044]={id=1044,name="Habalo's Eclogue - verse III",plural="Habalo's Eclogue - verse III",description="\nThe third verse of the eclogue penned\nby the first Yagudo Manifest, Ree\nHabalo. It is said that he who\nrecites all eight verses will be\nvisited by the Yagudo of legend.",category=2},
[1045]={id=1045,name="Habalo's Eclogue - verse IV",plural="Habalo's Eclogue - verse IV",description="\nThe fourth verse of the eclogue penned\nby the first Yagudo Manifest, Ree\nHabalo. It is said that he who\nrecites all eight verses will be\nvisited by the Yagudo of legend.",category=2},
[1046]={id=1046,name="Habalo's Eclogue - verse V",plural="Habalo's Eclogue - verse V",description="\nThe fifth verse of the eclogue penned\nby the first Yagudo Manifest, Ree\nHabalo. It is said that he who\nrecites all eight verses will be\nvisited by the Yagudo of legend.",category=2},
[1047]={id=1047,name="Habalo's Eclogue - verse VI",plural="Habalo's Eclogue - verse VI",description="\nThe sixth verse of the eclogue penned\nby the first Yagudo Manifest, Ree\nHabalo. It is said that he who\nrecites all eight verses will be\nvisited by the Yagudo of legend.",category=2},
[1048]={id=1048,name="Habalo's Eclogue - verse VII",plural="Habalo's Eclogue - verse VII",description="\nThe seventh verse of the eclogue\npenned by the first Yagudo Manifest,\nRee Habalo. It is said that he who\nrecites all eight verses will be\nvisited by the Yagudo of legend.",category=2},
[1049]={id=1049,name="Habalo's Eclogue - verse VIII",plural="Habalo's Eclogue - verse VIII",description="\nThe eighth and final verse of the\neclogue penned by the first Yagudo\nManifest, Ree Habalo. It is said that\nhe who recites all eight verses\nwill be visited by the Yagudo of\nlegend.",category=2},
[1050]={id=1050,name="signal firecracker",plural="signal firecrackers",description="\nA Bastokan signal firecracker\ndesigned to produce a loud, piercing\nbang claimed to be audible up to a\ndistance of ten malms. Used as a\nmeans of communication in tactical\nmissions where visual contact\nbetween operatives is limited.",category=2},
[1051]={id=1051,name="number eight shelter key",plural="number eight shelter keys",description="\nA mythril key etched only with\nthe number \"8.\"",category=2},
[1052]={id=1052,name="torn patches of leather",plural="torn patches of leather",description="\nThe grisly remains of Hampu-Kampu's\nbeautifully handcrafted handbag\nafter having met its cruel end at\nthe claws of young Tek Lengyon.",category=2},
[1053]={id=1053,name="repaired handbag",plural="repaired handbags",description="\nHampu-Kampu's handcrafted handbag\nhas been masterfully restored to\nits original mint condition by\nKipopo at the Tanners' Guild in\nSan d'Oria.",category=2},
[1054]={id=1054,name="mirage attire claim slip",plural="mirage attire claim slips",description="\n\"Holding\n\n 1 set of blue mage relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[1055]={id=1055,name="commodore attire claim slip",plural="commodore attire claim slips",description="\n\"Holding\n\n 1 set of corsair relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[1056]={id=1056,name="pantin attire claim slip",plural="pantin attire claim slips",description="\n\"Holding\n\n 1 set of puppetmaster relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=2},
[1057]={id=1057,name="etoile attire claim slip",plural="etoile attire claim slips",description="\n\"Holding\n\n 1 set of dancer relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=3},
[1058]={id=1058,name="argute attire claim slip",plural="argute attire claim slips",description="\n\"Holding\n\n 1 set of scholar relic armor\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=3},
[1059]={id=1059,name="argent attire claim slip",plural="argent attire claim slips",description="\n\"Holding\n\n 1 argent set\n\nfor the adventurer whose name is\ninscribed on the back of this slip.\"",category=3},
[1060]={id=1060,name="Conquest promotion voucher",plural="Conquest promotion vouchers",description="\nThese tickets are distributed as\na means to encourage adventurers\nto participate in the ever-ongoing\nconquest. It is equivalent to a\npredetermined number of conquest\npoints, and may be exchanged for\ngoods in the same manner.",category=2},
[1061]={id=1061,name="Cernunnos resin",plural="Cernunnos resin",description="\nA lump of solidified resin harvested\nfrom a treant species thought to be\nlong extinct. Known for its medicinal\nproperties.",category=2},
[1062]={id=1062,name="Count Borel's letter",plural="Count Borel's letters",description="\nA letter impressed with the seal\nof Halver M Borel.",category=2},
[1063]={id=1063,name="underpass hatch key",plural="underpass hatch keys",description="\nA key to unlock the hatch located\natop a defensive wall out in\nBatallia Downs. Needed to gain\naccess to Jeuno's underground.",category=3},
[1064]={id=1064,name="bottle of treant tonic",plural="bottles of treant tonic",description="\nA medicine prepared by Amaura,\nusing Cernunnos resin as its active\ningredient. While potent in its\nown right, its healing power is\nlimited to the alleviation of\nsymptoms.",category=2},
[1065]={id=1065,name="timber survey checklist",plural="timber survey checklists",description="\nA memo hastily scrawled by Ramua\nof the San d'Orian Carpenters' Guild,\nasking you to procure the following\nsamples from Jugner Forest:\n- arrowwood log, ash log, yew log,\n  willow log, walnut log",category=2},
[1066]={id=1066,name="snow-themed gift token",plural="snow-themed gift tokens",description="\nA Starlight Celebration gift token\nadorned with a frolicking snowflake\ndesign. Take it to your friendly\nneighborhood festival moogle to\nhave it exchanged for a lovely\npresent.",category=2},
[1067]={id=1067,name="star-themed gift token",plural="star-themed gift tokens",description="\nA Starlight Celebration gift token\nadorned with a twinkling star\ndesign. Take it to your friendly\nneighborhood festival moogle to\nhave it exchanged for a lovely\npresent.",category=2},
[1068]={id=1068,name="bell-themed gift token",plural="bell-themed gift tokens",description="\nA Starlight Celebration gift token\nadorned with a jingling bell\ndesign. Take it to your friendly\nneighborhood festival moogle to\nhave it exchanged for a lovely\npresent.",category=2},
[1069]={id=1069,name="flare grenade",plural="flare grenades",description="\nA tactical hand grenade that emits\na blinding flash of light.",category=2},
[1070]={id=1070,name="Ronfaure maple syrup",plural="Ronfaure maple syrup",description="\nThe mellow sweetness of this syrup,\nharvested from maple trees in\nRonfaure, has endeared itself to\nthe citizens of San d'Oria.",category=2},
[1071]={id=1071,name="long-life biscuits",plural="long-life biscuits",description="\nThese hard-baked biscuits serve as\nemergency rations during days of\ndisaster and dearth in San d'Oria.",category=2},
[1072]={id=1072,name="flask of Kingdom water",plural="flasks of Kingdom water",description="\nA flask of freshly drawn groundwater,\nchilled by its passage through the\nKingdom's extensive aquifer network.",category=2},
[1073]={id=1073,name="biscuit a la Rholont",plural="biscuits a la Rholont",description="\nNew life has been breathed into\nordinary long-life biscuits by way\nof aromatic slices of Chalaimbille\nand a generous drizzling of maple\nsyrup.",category=2},
[1074]={id=1074,name="letter to Count Aurchiat",plural="letters to Count Aurchiat",description="\nCaptain Rongelouts of the Iron Rams\nhas instructed you to deliver this\nletter to his Cardinal Stag\ncounterpart, Count Aurchiat.",category=2},
[1075]={id=1075,name="length of Jugner ivy",plural="lengths of Jugner ivy",description="\nThe robust resilience of this variety\nof creeper makes it an ideal choice\nfor use in rope making.",category=2},
[1076]={id=1076,name="darkfire cinder",plural="darkfire cinders",description="\nCurious jet-black cinders that\nsmolder with perpetual heat.\nA vital resource of the Allied\nForces, used in the creation of\nenchanted ammunition.",category=2},
[1077]={id=1077,name="floelight stone",plural="floelight stones",description="\nThese alabaster stones are chill to\nthe touch and emanate a faint,\nhazy light. A vital resource of the\nAllied Forces, used in the creation\nof enchanted arrowheads.",category=2},
[1078]={id=1078,name="liquid quicksilver",plural="liquid quicksilver",description="\nAn unusual substance resembling\nmolten metal. A requisite ingredient\nin the casting of enchanted\nammunition.",category=2},
[1079]={id=1079,name="gelid sulfur",plural="gelid sulfur",description="\nThough appearing at first glance to\nbe ordinary sulfur, it is cool to the\ntouch. A requisite ingredient in the\ncasting of enchanted ammunition.",category=2},
[1080]={id=1080,name="beastbane bullets",plural="beastbane bullets",description="The freshly cast bullets crackle\nwith a frozen flame...",category=2},
[1081]={id=1081,name="Gleipnir",plural="Gleipnir",description="\nThe mystic fetters fashioned by\nRimilala to subdue the Great Beast\nFenrir. Lighter and softer than silk,\nyet stronger than the hardest chains\nof darksteel.",category=2},
[1082]={id=1082,name="scintillant strand",plural="scintillant strands",description="\nA timeworn tatter of a peculiar\nsilken fiber. It shimmers with a\ncurious ethereal light...",category=2},
[1083]={id=1083,name="refulgent strand",plural="refulgent strands",description="\nA timeworn tatter of a peculiar\nsilken fiber. It shimmers with a\ncurious ethereal light...",category=2},
[1084]={id=1084,name="irradiant strand",plural="irradiant strands",description="\nA timeworn tatter of a peculiar\nsilken fiber. It shimmers with a\ncurious ethereal light...",category=3},
[1085]={id=1085,name="bowl of bland Goblin salad",plural="bowls of bland Goblin salad",description="\nBatagreens have been haphazardly\nsliced into irregularly sized chunks\nand drizzled with a runny,\nwatered-down bittern dressing to\nform this distinctly unappetizing\nsalad.",category=2},
[1086]={id=1086,name="jug of greasy Goblin juice",plural="jugs of greasy Goblin juice",description="\nFreshly squeezed rolanberries and\nfish oil...\nTwo great tastes that were\nnever meant to go together.",category=2},
[1087]={id=1087,name="chunk of smoked Goblin grub",plural="chunk of smoked Goblin grub",description="\nAn oversized hunk of meat that has\nbeen charred, seared, and smoked\nwell beyond the point of recognition\nand palatability.\nYou detect a hint of bonemeal-based\nGoblin seasoning.",category=2},
[1088]={id=1088,name="Seedspall Roseum",plural="Seedspall Roseum",description="\nA shard of the Seed Crystal\nretrieved from a veggie-loving\nGoblin. It tingles to the touch and\nradiates an otherworldly red-tinged\nlight.",category=2},
[1089]={id=1089,name="Seedspall Caerulum",plural="Seedspall Caerulum",description="\nA shard of the Seed Crystal\nretrieved from a health-conscious\nGoblin. It tingles to the touch and\nradiates an otherworldly blue-tinged\nlight.",category=2},
[1090]={id=1090,name="Seedspall Viridis",plural="Seedspall Viridis",description="\nA shard of the Seed Crystal\nretrieved from a particularly\ncarnivorous Goblin.\nIt tingles to the touch and radiates\nan otherworldly green-tinged light.",category=2},
[1091]={id=1091,name="Mark of Seed",plural="Marks of Seed",description="\nA glowing outline in the shape of a\nseed shines from the back of your\nhand. You feel as if it is beckoning\nyou to the Qu'Bia Arena.",category=0},
[1092]={id=1092,name="Amicitia Stone",plural="Amicitia Stone",description="\nA fragment of the Seed Crystal\nfound on the first floor of\nDelkfutt's Tower. It resembles a\ngarnet in hue and luster.",category=3},
[1093]={id=1093,name="Veritas Stone",plural="Veritas Stone",description="\nA fragment of the Seed Crystal\nfound on the second floor of\nDelkfutt's Tower. It resembles an\namethyst in hue and luster.",category=2},
[1094]={id=1094,name="Sapientia Stone",plural="Sapientia Stone",description="\nA fragment of the Seed Crystal\nfound on the third floor of\nDelkfutt's Tower. It resembles an\naquamarine in hue and luster.",category=2},
[1095]={id=1095,name="Sanctitas Stone",plural="Sanctitas Stone",description="\nA fragment of the Seed Crystal\nfound on the fourth floor of\nDelkfutt's Tower. It resembles a\ndiamond in hue and luster.",category=2},
[1096]={id=1096,name="Felicitas Stone",plural="Felicitas Stone",description="\nA fragment of the Seed Crystal\nfound on the fifth floor of\nDelkfutt's Tower. It resembles an\nemerald in hue and luster.",category=2},
[1097]={id=1097,name="Divitia Stone",plural="Divitia Stone",description="\nA fragment of the Seed Crystal\nfound on the sixth floor of\nDelkfutt's Tower. It resembles a\nmoonstone in hue and luster.",category=2},
[1098]={id=1098,name="Studium Stone",plural="Studium Stone",description="\nA fragment of the Seed Crystal\nfound on the seventh floor of\nDelkfutt's Tower. It resembles a\nruby in hue and luster.",category=2},
[1099]={id=1099,name="Amoris Stone",plural="Amoris Stone",description="\nA fragment of the Seed Crystal\nfound on the eighth floor of\nDelkfutt's Tower. It resembles a\nsardonyx in hue and luster.",category=3},
[1100]={id=1100,name="Caritas Stone",plural="Caritas Stone",description="\nA fragment of the Seed Crystal\nfound on the ninth floor of\nDelkfutt's Tower. It resembles a\nsapphire in hue and luster.",category=2},
[1101]={id=1101,name="Constantia Stone",plural="Constantia Stone",description="\nA fragment of the Seed Crystal\nfound on the tenth floor of\nDelkfutt's Tower. It resembles an\nopal in hue and luster.",category=2},
[1102]={id=1102,name="Spei Stone",plural="Spei Stone",description="\nA fragment of the Seed Crystal\nfound on the eleventh floor of\nDelkfutt's Tower. It resembles a\ntopaz in hue and luster.",category=2},
[1103]={id=1103,name="Salus Stone",plural="Salus Stone",description="\nA fragment of the Seed Crystal\nfound on the twelfth floor of\nDelkfutt's Tower. It resembles a\nlapis lazuli in hue and luster.",category=2},
[1104]={id=1104,name="Omnis Stone",plural="Omnis Stone",description="\nThe twelve stones resonate with\neach other, their lights coalescing\nto form an ethereal rainbow.\nClosely examining the lights, you\ncan make out a faint, flickering\nimage of the Stellar Fulcrum.",category=0},
[1105]={id=1105,name="Crimson Key",plural="Crimson Key",description="\nThis ancient key has been weathered\nby the years, save for the single\nflawless ruby that gleams softly\nfrom its resting place in the grip.",category=2},
[1106]={id=1106,name="Viridian Key",plural="Viridian Key",description="\nThis ancient key has been weathered\nby the years, save for the single\nflawless emerald that gleams softly\nfrom its resting place in the grip.",category=2},
[1107]={id=1107,name="Amber Key",plural="Amber Key",description="\nThis ancient key has been weathered\nby the years, save for the single\nflawless topaz that gleams softly\nfrom its resting place in the grip.",category=3},
[1108]={id=1108,name="Azure Key",plural="Azure Key",description="\nThis ancient key has been weathered\nby the years, save for the single\nflawless sapphire that gleams softly\nfrom its resting place in the grip.",category=3},
[1109]={id=1109,name="Ivory Key",plural="Ivory Key",description="\nThis ancient key has been weathered\nby the years, save for the single\nflawless pearl that gleams softly\nfrom its resting place in the grip.",category=2},
[1110]={id=1110,name="Ebon Key",plural="Ebon Key",description="\nThis ancient key has been weathered\nby the years, save for the single\nflawless onyx that gleams softly\nfrom its resting place in the grip.",category=2},
[1111]={id=1111,name="Delkfutt key",plural="Delkfutt keys",description="\nThis key is needed to gain access to\ncertain areas of Delkfutt's Tower.",category=2},
[1112]={id=1112,name="beastbane arrowheads",plural="beastbane arrowheads",description="\nThe freshly cast arrowheads\ncrackle with a frozen flame...",category=2},
[1113]={id=1113,name="red-labeled crate",plural="red-labeled crates",description="\nA small wooden crate adorned with\na nondescript red label, underneath\nwhich you can detect the remains of\na label of a different color.\nThough not heavy, you sense that\nthere is something within...",category=2},
[1114]={id=1114,name="blue-labeled crate",plural="blue-labeled crates",description="\nA small wooden crate adorned with\na nondescript blue label, underneath\nwhich you can detect the remains of\na label of a different color.\nThough not heavy, you sense that\nthere is something within...",category=2},
[1115]={id=1115,name="green-labeled crate",plural="green-labeled crates",description="\nA small wooden crate adorned with\na nondescript green label, underneath\nwhich you can detect the remains of\na label of a different color.\nThough not heavy, you sense that\nthere is something within...",category=2},
[1116]={id=1116,name="\"Elite Training: Introduction\"",plural="\"Elite Training: Introduction\"",description="\nA transcript of pages 1-10 of the\nelite training section of the Field\nManual. Trade this along with\nbeastmen's seals, gil, or a piece\nof equipment at designated locations\nin order to commence your training.",category=3},
[1117]={id=1117,name="\"Elite Training: Chapter 1\"",plural="\"Elite Training: Chapter 1\"",description="\nA transcript of pages 11-20 of the\nelite training section of the Field\nManual. Trade this along with\nbeastmen's seals, gil, or a piece\nof equipment at designated locations\nin order to commence your training.",category=2},
[1118]={id=1118,name="\"Elite Training: Chapter 2\"",plural="\"Elite Training: Chapter 2\"",description="\nA transcript of pages 21-30 of the\nelite training section of the Field\nManual. Trade this along with\nbeastmen's seals, gil, or a piece\nof equipment at designated locations\nin order to commence your training.",category=2},
[1119]={id=1119,name="\"Elite Training: Chapter 3\"",plural="\"Elite Training: Chapter 3\"",description="\nA transcript of pages 31-40 of the\nelite training section of the Field\nManual. Trade this along with\nbeastmen's seals, gil, or a piece\nof equipment at designated locations\nin order to commence your training.",category=2},
[1120]={id=1120,name="\"Elite Training: Chapter 4\"",plural="\"Elite Training: Chapter 4\"",description="\nA transcript of pages 41-50 of the\nelite training section of the Field\nManual. Trade this along with\nbeastmen's seals, gil, or a piece\nof equipment at designated locations\nin order to commence your training.",category=2},
[1121]={id=1121,name="\"Elite Training: Chapter 5\"",plural="\"Elite Training: Chapter 5\"",description="\nA transcript of pages 51-60 of the\nelite training section of the Field\nManual. Trade this along with\nbeastmen's seals, gil, or a piece\nof equipment at designated locations\nin order to commence your training.",category=2},
[1122]={id=1122,name="\"Elite Training: Chapter 6\"",plural="\"Elite Training: Chapter 6\"",description="\nA transcript of pages 61-70 of the\nelite training section of the Field\nManual. Trade this along with\nbeastmen's seals, gil, or a piece\nof equipment at designated locations\nin order to commence your training.",category=2},
[1123]={id=1123,name="\"Elite Training: Chapter 7\"",plural="\"Elite Training: Chapter 7\"",description="\nA transcript of pages 71-75 of the\nelite training section of the Field\nManual. Trade this along with\nbeastmen's seals, gil, or a piece\nof equipment at designated locations\nin order to commence your training.",category=2},
[1124]={id=1124,name="unadorned ring",plural="unadorned rings",description="\nBereft of a stone, this simple yet\nelegant ring exudes an air of\nmelancholy.",category=3},
[1125]={id=1125,name="Mog Kupon A-DBcd",plural="Mog Kupons A-DBcd",description="\nIssued by the Mog House Management Union (MHMU).\nTradeable for relic equipment from Dynamis - Beaucedine.",category=2},
[1126]={id=1126,name="Mog Kupon A-DXar",plural="Mog Kupons A-DXar",description="\nIssued by the Mog House Management Union (MHMU).\nTradeable for relic equipment from Dynamis - Xarcabard.",category=2},
[1127]={id=1127,name="Prismatic Key",plural="Prismatic Key",description="\nThis ancient key has been weathered\nby the years, save for the single\nflawless diamond that rests in the\ngrip. When light catches it, it\nreflects a dazzling, many-colored\nrainbow.",category=2},
[1128]={id=1128,name="shadow bug",plural="shadow bugs",description="\nA minute bug-shaped device that\nallows the close surveillance of\nthe chosen subject. Part of Cait\nSith's mysterious arsenal of\ngadgets.",category=2},
[1129]={id=1129,name="white coral key",plural="white coral keys",description="\nA delicate fragment of pure\nwhite coral adorns the head of\nthis timeworn key.",category=2},
[1130]={id=1130,name="blue coral key",plural="blue coral keys",description="\nA delicate fragment of marine\nblue coral adorns the head of\nthis timeworn key.",category=2},
[1131]={id=1131,name="peach coral key",plural="peach coral keys",description="\nA delicate fragment of\npeach-colored coral adorns\nthe head of this timeworn key.",category=2},
[1132]={id=1132,name="black coral key",plural="black coral keys",description="\nA delicate fragment of jet-black\ncoral adorns the head of this\ntimeworn key.",category=2},
[1133]={id=1133,name="red coral key",plural="red coral keys",description="\nA delicate fragment of deep\nred coral adorns the head of\nthis timeworn key.",category=2},
[1134]={id=1134,name="angel skin key",plural="angel skin keys",description="\nA delicate fragment of rare\nangel skin coral adorns the\nhead of this timeworn key.",category=3},
[1135]={id=1135,name="oxblood key",plural="oxblood keys",description="\nA delicate fragment of rare\noxblood coral adorns the\nhead of this timeworn key.",category=3},
[1136]={id=1136,name="sturdy metal strip",plural="sturdy metal strips",description="\nA sturdy-looking strip of mythril.\nWith the right tools, it could be\nused to reinforce the foundation\nof a Mog House.",category=2},
[1137]={id=1137,name="piece of rugged tree bark",plural="pieces of rugged tree bark",description="\nA thick and rugged sheet of\nchestnut bark. With the right tools,\nit could be used to repair the roof\nof a Mog House.",category=2},
[1138]={id=1138,name="savory lamb roast",plural="savory lamb roasts",description="\nThis roasted rump of lamb tantalizes\nyour nostrils with a mouthwatering\naroma. Even with the right tools...it\ncouldn't be used to repair a Mog\nHouse in any conceivable way.",category=2},
[1139]={id=1139,name="Orb of Swords",plural="Orbs of Swords",description="\nFound in the Horutoto Ruins,\nthis Mana Orb emanates a powerful\nmagical aura. The emblem of a\nsword gleams on its surface.",category=3},
[1140]={id=1140,name="Orb of Cups",plural="Orbs of Cups",description="\nFound in the Horutoto Ruins,\nthis Mana Orb emanates a powerful\nmagical aura. The emblem of a\nchalice gleams on its surface.",category=3},
[1141]={id=1141,name="Orb of Batons",plural="Orbs of Batons",description="\nFound in the Horutoto Ruins,\nthis Mana Orb emanates a powerful\nmagical aura. The emblem of a\nscepter gleams on its surface.",category=3},
[1142]={id=1142,name="Orb of Coins",plural="Orbs of Coins",description="\nFound in the Horutoto Ruins,\nthis Mana Orb emanates a powerful\nmagical aura. The emblem of a\ncoin gleams on its surface.",category=3},
[1143]={id=1143,name="ripe starfruit",plural="ripe starfruits",description="\nRipened to perfection, this piece\nof starfruit gives off the luscious\naroma of its sweet nectar.",category=2},
[1144]={id=1144,name="moldy, worm-eaten chest",plural="moldy, worm-eaten chests",description="\nThis filthy, worm-eaten chest\npurportedly contains your moogle\nfriend's entire life savings.",category=2},
[1145]={id=1145,name="stone of Surya",plural="stones of Surya",description="\nA ruby of flawless cut and luster,\ncreated by a legendary king to\nhonor one of the nine cosmic\nforces. It is said the complete set\nshall grant its owner entry into the\nhalls of darkness...",category=2},
[1146]={id=1146,name="stone of Chandra",plural="stones of Chandra",description="\nA pearl of flawless purity and luster,\ncreated by a legendary king to\nhonor one of the nine cosmic\nforces. It is said the complete set\nshall grant its owner entry into the\nhalls of darkness...",category=2},
[1147]={id=1147,name="stone of Mangala",plural="stones of Mangala",description="\nA red coral of flawless cut and\nluster, created by a legendary king\nto honor one of the nine cosmic\nforces. It is said the complete set\nshall grant its owner entry into the\nhalls of darkness...",category=2},
[1148]={id=1148,name="stone of Budha",plural="stones of Budha",description="\nAn emerald of flawless cut and\nluster, created by a legendary king\nto honor one of the nine cosmic\nforces. It is said the complete set\nshall grant its owner entry into the\nhalls of darkness...",category=2},
[1149]={id=1149,name="stone of Brihaspati",plural="stones of Brihaspati",description="\nA yellow sapphire of flawless cut\nand luster, created by a legendary\nking to honor one of the nine\ncosmic forces. It is said the\ncomplete set shall grant its owner\nentry into the halls of darkness...",category=2},
[1150]={id=1150,name="stone of Shukra",plural="stones of Shukra",description="\nA diamond of flawless cut and\nluster, created by a legendary king\nto honor one of the nine cosmic\nforces. It is said the complete set\nshall grant its owner entry into the\nhalls of darkness...",category=2},
[1151]={id=1151,name="stone of Shani",plural="stones of Shani",description="\nA blue sapphire of flawless cut\nand luster, created by a legendary\nking to honor one of the nine\ncosmic forces. It is said the\ncomplete set shall grant its owner\nentry into the halls of darkness...",category=2},
[1152]={id=1152,name="stone of Rahu",plural="stones of Rahu",description="\nA hessonite of flawless cut and\nluster, created by a legendary king\nto honor one of the nine cosmic\nforces. It is said the complete set\nshall grant its owner entry into the\nhalls of darkness...",category=2},
[1153]={id=1153,name="stone of Ketu",plural="stones of Ketu",description="\nA cat's-eye of flawless cut and\nluster, created by a legendary king\nto honor one of the nine cosmic\nforces. It is said the complete set\nshall grant its owner entry into the\nhalls of darkness...",category=2},
[1154]={id=1154,name="Trivia Challenge Kupon",plural="Trivia Challenge Kupons",description="\nA prize obtained by completing\n\"The Elemental Casket of Mystique\nand Mystery.\" It reads, \"This kupon\nentitles one (1) lucky contestant\nto participate in the 'Vrtra's\n64,000,000 Gil Question' challenge\nat our Xarcabard venue, kupo.\"",category=2},
[1155]={id=1155,name="Gauntlet Challenge Kupon",plural="Gauntlet Challenge Kupons",description="\nA prize obtained by completing\n\"Vrtra's 64,000,000 Gil Question.\"\nIt reads, \"This kupon entitles one\n(1) lucky contestant to participate\nin the 'Gauntlet of Fortitude'\nat our Castle Zvahl Baileys\nfestival venue, kupo.\"",category=2},
[1156]={id=1156,name="Festival Souvenir Kupon",plural="Festival Souvenir Kupons",description="\nA prize obtained by successfully\nnavigating \"The Gauntlet of\nFortitude.\" It reads, \"The lucky\nholder of this kupon is eligible for\na very special souvenir at our stalls\nsituated in Castle Zvahl Keep,\nkupo!\"",category=2},
[1157]={id=1157,name="pocket mogbomb",plural="pocket mogbombs",description="\nA small handbomb obtained from\n\"The Elemental Casket of Mystique\nand Mystery.\" The moogle emcee\nhas offered you a special prize for\nits return.",category=2},
[1158]={id=1158,name="Navaratna talisman",plural="Navaratna talismans",description="\nThe set of nine cosmic gems, joined\nby an otherworldly force to form a\ndazzling pendant. Dancing wisps of\nethereal light beckon you to the\nhalls of darkness...",category=2},
[1159]={id=1159,name="Mega Bonanza Kupon",plural="Mega Bonanza Kupons",description="\nA gaudily illustrated ticket with\nflowery letters that read, \"This\nkupon entitles one (1) incredibly\nlucky contestant to participate in\nthe exclusive Mega Mog\nBonanza-Rama-Palooza!\nHow exciting is that, kupo!?\"",category=2},
[1160]={id=1160,name="aroma bug",plural="aroma bugs",description="\nA minute bug-shaped device that\nreleases a distinctive fragrance\nfor a set duration. Part of Cait\nSith's mysterious arsenal of\ngadgets.",category=3},
[1161]={id=1161,name="umbra bug",plural="umbra bugs",description="\nA minute bug-shaped device that\nallows the bearer to enter a\nbarrier of Cait Sith's making.\nPart of Cait Sith's mysterious\narsenal of gadgets.",category=3},
[1162]={id=1162,name="north-bound petition",plural="north-bound petitions",description="\nSignatures you have gathered from\nKingdom knights adorn this sheet\nof parchment.",category=2},
[1163]={id=1163,name="Ponono's charm",plural="Ponono's charms",description="\nA charming little wristband\ncomprised of three intertwining\nstrands of vividly hued thread,\ncrafted by Ponono of the\nWindurstian Clothcrafters' guild.",category=2},
[1164]={id=1164,name="delicate wool thread",plural="delicate wool thread",description="\nA spool of fine wool thread\nentrusted to you by Ponono.\nMagically treated with her family's\nsecret recipe, it will take on a\nbrilliant hue if dipped in the waters\nof the Knightwell in West Ronfaure.",category=2},
[1165]={id=1165,name="delicate linen thread",plural="delicate linen thread",description="\nA spool of fine linen thread\nentrusted to you by Ponono.\nMagically treated with her family's\nsecret recipe, it will take on a\nbrilliant hue if dipped in the waters\nof the Fay Spring of Grauberg.",category=2},
[1166]={id=1166,name="delicate cotton thread",plural="delicate cotton thread",description="\nA spool of fine cotton thread\nentrusted to you by Ponono.\nMagically treated with her family's\nsecret recipe, it will take on a\nbrilliant hue if dipped in the waters\nof Lake Tepokalipuka in East\nSarutabaruta.",category=2},
[1167]={id=1167,name="enchanted wool thread",plural="enchanted wool threads",description="\nA spool of fine wool thread\nentrusted to you by Ponono. Having\nbeen dipped in the mystic waters of\nthe Knightwell, it now shimmers with\na brilliant red hue.",category=3},
[1168]={id=1168,name="enchanted linen thread",plural="enchanted linen threads",description="\nA spool of fine linen thread\nentrusted to you by Ponono. Having\nbeen dipped in the mystic waters of\nthe Fay Spring, it now shimmers with\na brilliant blue hue.",category=3},
[1169]={id=1169,name="enchanted cotton thread",plural="enchanted cotton threads",description="\nA spool of fine cotton thread\nentrusted to you by Ponono. Having\nbeen dipped in the mystic waters of\nLake Tepokalipuka, it now shimmers with\na brilliant green hue.",category=3},
[1170]={id=1170,name="wax seal",plural="wax seals",description="\nThe curious odor it emits is the\nonly feature that distinguishes this\ngoblin-fashioned replica of the\nofficial Bastokan seal from\nthe real thing.",category=2},
[1171]={id=1171,name="sack of victuals",plural="sacks of victuals",description="\nLovingly assembled for the\nincarcerated Zeid by his number one\nfan, Gentle Tiger, this cloth sack is\nstuffed chock full of Galkan\nsausages, meat jerky, and assorted\nother provisions sure to rouse the\nspirits of a down-on-his-luck Galka.",category=2},
[1172]={id=1172,name="commander's endorsement",plural="commander's endorsements",description="\nA letter of recommendation drafted\nby Captain Herbert, certifying you\nas loyal, fit, and able to serve as a\nsecurity officer in the President's\nretinue.",category=2},
[1173]={id=1173,name="succulent dragon fruit",plural="succulent dragon fruits",description="\nA particularly luscious and juicy\nspecimen of the tasty cactus fruit.\nThe preferred delicacy of the young\nMithran gourmand Syu Befrathi.",category=2},
[1174]={id=1174,name="shard of optistone",plural="shards of optistone",description="\nA shard of magicite retrieved from\ndeep in the heart of Davoi. Murky\nwhorls of menacing energy wrench\nand twist within.",category=2},
[1175]={id=1175,name="shard of aurastone",plural="shards of aurastone",description="\nA shard of magicite retrieved from\ndeep in the heart of Beadeaux.\nMurky whorls of menacing energy\nwrench and twist within.",category=2},
[1176]={id=1176,name="shard of orastone",plural="shards of orastone",description="\nA shard of magicite retrieved from deep in the heart of Castle Oztroja. Whorls of murky, menacing energy wrench and twist within.",category=2},
[1177]={id=1177,name="prospector's pan",plural="prospector's pan",description="\nA simple, unadorned pan of iron\nused to pan for gold and other\nprecious metals. Lent to you by\nTitus of the Alchemists' Guild.",category=2},
[1178]={id=1178,name="corked ampoule",plural="corked ampoule",description="\nA small bottle with a cork stopper\nto seal in the contents, entrusted\nto you by Titus of the Alchemists'\nGuild. You are to return it to him\nwith twenty grains of magical gold\ndust.",category=2},
[1179]={id=1179,name="ampoule of gold dust",plural="ampoule of gold dust",description="\nThis small bottle contains twenty\ngrains of gold dust retrieved from\nthe streams of Grauberg. Titus will\nbe thrilled to hear word of your\nsuccess!",category=3},
[1180]={id=1180,name="vial of military prism powder",plural="vials of military prism powder",description="\nStandard issue Kingdom prism powder,\nconcocted according to a secret\nformula for enhanced and longer\nlasting invisibility.",category=2},
[1181]={id=1181,name="lance fish",plural="lance fish",description="\nA saltwater fish whose streamlined\nshape gave birth to its moniker. Its\nsinewy flesh, while spurned by other\nraces, has made it a perennial\nfavorite among Gigas.",category=2},
[1182]={id=1182,name="paladin lobster",plural="paladin lobsters",description="\nA crustacean armored in an imposing\nshell of peerless hardiness that\ninspired its name. Its pungent\nflesh has earned it a home among\nthe Gigas' most sought-after\ndelicacies.",category=2},
[1183]={id=1183,name="scutum crab",plural="scutum crabs",description="\nWith a carapace resembling a shield,\nthe poisonous flesh of this crab is\nsaid to assault the Gigas palate\nwith a stimulating tang they find\nirresistible.",category=2},
[1184]={id=1184,name="Moogle key",plural="Moogle keys",description="\nA timeworn key wrought of an\nunknown metal, adorned with the\nsign of the Moogle constellation\non its discoid grip.",category=2},
[1185]={id=1185,name="Bird key",plural="Bird keys",description="\nA timeworn key wrought of an\nunknown metal, adorned with the\nsign of the Bird constellation\non its discoid grip.",category=2},
[1186]={id=1186,name="Cactuar key",plural="Cactuar keys",description="\nA timeworn key wrought of an\nunknown metal, adorned with the\nsign of the Cactuar constellation\non its discoid grip.",category=2},
[1187]={id=1187,name="Bomb key",plural="Bomb keys",description="\nA timeworn key wrought of an\nunknown metal, adorned with the\nsign of the Bomb constellation\non its discoid grip.",category=2},
[1188]={id=1188,name="Chocobo key",plural="Chocobo keys",description="\nA timeworn key wrought of an\nunknown metal, adorned with the\nsign of the Chocobo constellation\non its discoid grip.",category=2},
[1189]={id=1189,name="Tonberry key",plural="Tonberry keys",description="\nA timeworn key wrought of an\nunknown metal, adorned with the\nsign of the Tonberry constellation\non its discoid grip.",category=2},
[1190]={id=1190,name="Behemoth key",plural="Behemoth keys",description="\nA timeworn key wrought of an\nunknown metal, adorned with the\nsign of the Behemoth constellation\non its discoid grip.",category=2},
[1191]={id=1191,name="Domina's scarlet seal",plural="Domina's scarlet seals",description="\nAn enchanted sheet of parchment\nissued to you by Domina Shantotto,\nmounted on a counterseal that serves\nto contain its power until attached\nto the corresponding protocrystal.\nIt feels faintly warm to the touch.",category=2},
[1192]={id=1192,name="Domina's cerulean seal",plural="Domina's cerulean seals",description="\nAn enchanted sheet of parchment\nissued to you by Domina Shantotto,\nmounted on a counterseal that serves\nto contain its power until attached\nto the corresponding protocrystal.\nIt feels oddly moist to the touch.",category=2},
[1193]={id=1193,name="Domina's emerald seal",plural="Domina's emerald seals",description="\nAn enchanted sheet of parchment\nissued to you by Domina Shantotto,\nmounted on a counterseal that serves\nto contain its power until attached\nto the corresponding protocrystal.\nIt dances within your grip as if\nblown about by a breeze.",category=2},
[1194]={id=1194,name="Domina's amber seal",plural="Domina's amber seals",description="\nAn enchanted sheet of parchment\nissued to you by Domina Shantotto,\nmounted on a counterseal that serves\nto contain its power until attached\nto the corresponding protocrystal.\nAn earthy aroma emanates from it.",category=2},
[1195]={id=1195,name="Domina's violet seal",plural="Domina's violet seals",description="\nAn enchanted sheet of parchment\nissued to you by Domina Shantotto,\nmounted on a counterseal that serves\nto contain its power until attached\nto the corresponding protocrystal.\nA tingling sensation runs through\nyour hand at its touch.",category=2},
[1196]={id=1196,name="Domina's azure seal",plural="Domina's azure seals",description="\nAn enchanted sheet of parchment\nissued to you by Domina Shantotto,\nmounted on a counterseal that serves\nto contain its power until attached\nto the corresponding protocrystal.\nIt feels faintly chill to the touch.",category=2},
[1197]={id=1197,name="scarlet counterseal",plural="scarlet counterseals",description="\nDomina Shantotto's scarlet seal\nhas been attached to the fire\nprotocrystal and is no longer\nmounted on this sheet of magicked\nparchment. It should serve as\nproof of obedience to your empress.",category=2},
[1198]={id=1198,name="cerulean counterseal",plural="cerulean counterseals",description="\nDomina Shantotto's cerulean seal\nhas been attached to the water\nprotocrystal and is no longer\nmounted on this sheet of magicked\nparchment. It should serve as\nproof of obedience to your empress.",category=2},
[1199]={id=1199,name="emerald counterseal",plural="emerald counterseals",description="\nDomina Shantotto's emerald seal\nhas been attached to the wind\nprotocrystal and is no longer\nmounted on this sheet of magicked\nparchment. It should serve as\nproof of obedience to your empress.",category=3},
[1200]={id=1200,name="amber counterseal",plural="amber counterseals",description="\nDomina Shantotto's amber seal\nhas been attached to the earth\nprotocrystal and is no longer\nmounted on this sheet of magicked\nparchment. It should serve as\nproof of obedience to your empress.",category=3},
[1201]={id=1201,name="violet counterseal",plural="violet counterseals",description="\nDomina Shantotto's violet seal\nhas been attached to the lightning\nprotocrystal and is no longer\nmounted on this sheet of magicked\nparchment. It should serve as\nproof of obedience to your empress.",category=2},
[1202]={id=1202,name="azure counterseal",plural="azure counterseals",description="\nDomina Shantotto's azure seal\nhas been attached to the ice\nprotocrystal and is no longer\nmounted on this sheet of magicked\nparchment. It should serve as\nproof of obedience to your empress.",category=3},
[1203]={id=1203,name="black book",plural="black books",description="\nA well-worn book containing a record\nof Tenshodo transactions for the past\ncalendar year. Black tiger hide has\nbeen used to bind its pages together.",category=2},
[1204]={id=1204,name="luminous red fragment",plural="luminous red fragments",description="\nA peculiar triangular fragment formed\nof a luminous material seemingly not\nof this world. Although it transitions\nthrough a number of hues, red is\nits predominant color. Your keen sense\nof geometry tells you that six of\nthese will form a perfect hexagon.",category=2},
[1205]={id=1205,name="luminous beige fragment",plural="luminous beige fragments",description="\nA peculiar triangular fragment formed\nof a luminous material seemingly not\nof this world. Although it transitions\nthrough a number of hues, beige is\nits predominant color. Your keen sense\nof geometry tells you that six of\nthese will form a perfect hexagon.",category=2},
[1206]={id=1206,name="luminous green fragment",plural="luminous green fragments",description="\nA peculiar triangular fragment formed\nof a luminous material seemingly not\nof this world. Although it transitions\nthrough a number of hues, green is\nits predominant color. Your keen sense\nof geometry tells you that six of\nthese will form a perfect hexagon.",category=2},
