[1208]={id=1208,name="luminous purple fragment",plural="luminous purple fragments",description="\nA peculiar triangular fragment formed\nof a luminous material seemingly not\nof this world. Although it transitions\nthrough a number of hues, purple is\nits predominant color. Your keen sense\nof geometry tells you that six of\nthese will form a perfect hexagon.",category=2},
[1209]={id=1209,name="luminous blue fragment",plural="luminous blue fragments",description="\nA peculiar triangular fragment formed\nof a luminous material seemingly not\nof this world. Although it transitions\nthrough a number of hues, blue is\nits predominant color. Your keen sense\nof geometry tells you that six of\nthese will form a perfect hexagon.",category=2},
[1210]={id=1210,name="fire sap crystal",plural="fire sap crystals",description="\nThe sap of the Great Star Tree in\ncrystallized form, found within the\ngloom of the Toraimarai Canal. It is\nfaintly aglow with fire energy.",category=2},
[1211]={id=1211,name="water sap crystal",plural="water sap crystals",description="\nThe sap of the Great Star Tree in\ncrystallized form, found within the\ngloom of the Toraimarai Canal. It is\nfaintly aglow with water energy.",category=2},
