[1215]={id=1215,name="ice sap crystal",plural="ice sap crystals",description="\nThe sap of the Great Star Tree in\ncrystallized form, found within the\ngloom of the Toraimarai Canal. It is\nfaintly aglow with ice energy.",category=3},
[1216]={id=1216,name="light sap crystal",plural="light sap crystals",description="\nThe sap of the Great Star Tree in\ncrystallized form, found within the\ngloom of the Toraimarai Canal. It is\nfaintly aglow with light energy.",category=2},
[1217]={id=1217,name="dark sap crystal",plural="dark sap crystals",description="\nThe sap of the Great Star Tree in\ncrystallized form, found within the\ngloom of the Toraimarai Canal. It is\nfaintly aglow with dark energy.",category=2},
[1218]={id=1218,name="Tablet of Hexes: Greed",plural="Tablets of Hexes: Greed",description="\nThe first in a concatenation of\nancient stone tablets passed down\nover millennia by the Tonberry race,\nfound within the Temple of Uggalepih.\nEngraved in indecipherable runes, a\nsingle tablet is said to hold the\nanguish of a thousand tortured souls.",category=2},
[1219]={id=1219,name="Tablet of Hexes: Envy",plural="Tablets of Hexes: Envy",description="\nThe second in a concatenation of\nancient stone tablets passed down\nover millennia by the Tonberry race,\nfound within the Temple of Uggalepih.\nEngraved in indecipherable runes, a\nsingle tablet is said to hold the\nanguish of a thousand tortured souls.",category=2},
[1220]={id=1220,name="Tablet of Hexes: Malice",plural="Tablets of Hexes: Malice",description="\nThe third in a concatenation of\nancient stone tablets passed down\nover millennia by the Tonberry race,\nfound within the Temple of Uggalepih.\nEngraved in indecipherable runes, a\nsingle tablet is said to hold the\nanguish of a thousand tortured souls.",category=2},
