[1229]={id=1229,name="Tablet of Hexes: Rancor",plural="Tablets of Hexes: Rancor",description="\nThe twelfth in a concatenation of\nancient stone tablets passed down\nover millennia by the Tonberry race,\nfound within the Den of Rancor.\nEngraved in indecipherable runes, a\nsingle tablet is said to hold the\nanguish of a thousand tortured souls.",category=2},
[1230]={id=1230,name="Tablet of Hexes: Strife",plural="Tablets of Hexes: Strife",description="\nThe thirteenth in a concatenation of\nancient stone tablets passed down\nover millennia by the Tonberry race,\nfound within the Den of Rancor.\nEngraved in indecipherable runes, a\nsingle tablet is said to hold the\nanguish of a thousand tortured souls.",category=2},
[1231]={id=1231,name="Tablet of Hexes: Penury",plural="Tablets of Hexes: Penury",description="\nThe fourteenth in a concatenation of\nancient stone tablets passed down\nover millennia by the Tonberry race,\nfound within the Den of Rancor.\nEngraved in indecipherable runes, a\nsingle tablet is said to hold the\nanguish of a thousand tortured souls.",category=2},
[1232]={id=1232,name="Tablet of Hexes: Blight",plural="Tablets of Hexes: Blight",description="\nThe fifteenth in a concatenation of\nancient stone tablets passed down\nover millennia by the Tonberry race,\nfound within the Den of Rancor.\nEngraved in indecipherable runes, a\nsingle tablet is said to hold the\nanguish of a thousand tortured souls.",category=2},
[1233]={id=1233,name="Tablet of Hexes: Death",plural="Tablets of Hexes: Death",description="\nThe sixteenth in a concatenation of\nancient stone tablets passed down\nover millennia by the Tonberry race,\nfound within the Den of Rancor.\nEngraved in indecipherable runes, a\nsingle tablet is said to hold the\nanguish of a thousand tortured souls.",category=2},
[1234]={id=1234,name="synergy crucible",plural="synergy crucibles",description="\nThis compact receptacle designed\nfor use with a synergy furnace\nserves the dual purpose of shielding\nthe materials within from sudden\nsurges of elemental forces and\ndispensing fewell to facilitate the\nsynergy process.",category=2},
[1235]={id=1235,name="Mog Kupon AW-Abs",plural="Mog Kupons AW-Abs",description="\nIssued by the Mog House Management Union (MHMU).\nTradeable for spoils from Absolute Virtue.",category=2},
[1236]={id=1236,name="Mog Kupon AW-Pan",plural="Mog Kupons AW-Pan",description="\nIssued by the Mog House Management Union (MHMU).\nTradeable for items from Pandemonium Warden.",category=2},
[1237]={id=1237,name="magelight signal flare",plural="magelight signal flares",description="\nA magically powered signal flare\nof Windurstian design, used as a\nmeans of communication on the\nbattlefield.",category=2},
[1238]={id=1238,name="alchemical signal flare",plural="alchemical signal flares",description="\nAn alchemically constructed signal\nflare of Bastokan design, used as\na means of communication on the\nbattlefield.",category=3},
[1239]={id=1239,name="distress signal flare",plural="distress signal flares",description="\nA distress signal flare of San d'Orian\ndesign, the emitted light universally\nrecognized the Middle Lands over as\nan emergency call for aid.",category=2},
[1240]={id=1240,name="Imperial missive",plural="Imperial missives",description="\nA letter addressed to the four\nnations of the Middle Lands, penned\nby Ghatsad and bearing the seals of\nthe Empress and the Aht Urhgan\nArchaeological Research Institute.\nIt contains detailed data on the iron\ncolossus and a concise summary of\nthe Empire's plight.",category=3},
[1241]={id=1241,name="San d'Orian approval letter",plural="San d'Orian approval letters",description="\nA document bearing the official seal\nof House d'Oraguille, pledging the\nKingdom's support in the operation\nto reactivate the colossus.",category=2},
[1242]={id=1242,name="Bastokan approval letter",plural="Bastokan approval letters",description="\nA document bearing the\nwaterwheel-and-chimney seal of\nBastok, pledging the Republic's\nsupport in the operation to\nreactivate the colossus.",category=2},
[1243]={id=1243,name="Windurstian approval letter",plural="Windurstian approval letters",description="\nA document bearing a seal depicting\nthe Great Star Tree and the five\nministries, pledging the Federation's\nsupport in the operation to\nreactivate the colossus.",category=2},
[1244]={id=1244,name="Jeunoan approval letter",plural="Jeunoan approval letters",description="\nA document bearing a seal of the\nsun shining upon the three great\nbridges of Jeuno, pledging the Grand\nDuchy's support in the operation to\nreactivate the colossus.",category=2},
[1245]={id=1245,name="present for Megomak",plural="presents for Megomak",description="\nA box wrought of solid bronze,\nnondescript save for the embossed\ncaduceus that graces its lid.\nA sturdy lock prevents you from\nascertaining its contents, though\nGhatsad claims it will serve you well\nin your negotiations with the Moblin\nMegomak.",category=2},
[1246]={id=1246,name="lightning cell",plural="lightning cells",description="\nA chain of rusty metallic receptacles\nhaphazardly strung together with\nmottled wire. If Megomak speaks\ntrue, its underwhelming appearance\nbelies the capability to store and\ndischarge copious amounts of\nenergy.",category=2},
[1247]={id=1247,name="Megomak's shopping list",plural="Megomak's shopping lists",description="\nA grimy, tattered piece of\nparchment upon which \"plumbago: 3\nslabs\" has been hastily jotted\ndown in a near-illegible scrawl.",category=2},
[1248]={id=1248,name="whisper of radiance",plural="whispers of radiance",description="\nYou can sense its presence,\nbut it cannot be seen.",category=2},
[1249]={id=1249,name="talisman of the rebel gods",plural="talismans of the rebel gods",description="\nAn exquisitely wrought talisman\nbearing the twin emblems of\nEphramad, the crowned dolphin and\nthe Dark Rider. Painstakingly\nrestored, it looks just as it must\nhave when Kingdom soldiers carried\nit into battle.",category=2},
[1250]={id=1250,name="message from Yoyoroon",plural="messages from Yoyoroon",description="\n\"Yooo find loooky charm in\nAiry-pago, maybe yooo dooo?\"\nhas been scribbled in sloppy yet\nsomehow charming handwriting.\nA far more legible postscript reads,\n\"A treat or two from the Shararat\nTeahouse would be most welcome.\"",category=2},
[1251]={id=1251,name="whisper of gloom",plural="whispers of gloom",description="\nYou can sense its presence,\nbut it cannot be seen.",category=2},
[1252]={id=1252,name="spatial pressure barometer",plural="spatial pressure barometers",description="\nA handheld device outfitted with a\nbefuddling array of knobs and\nswitches. According to Ghatsad, you\nneed only keep it in your possession\nto collect all the necessary data\nfrom the Hazhalm spatial distortion.",category=2},
[1253]={id=1253,name="clear abyssite",plural="clear abyssite",description="\nA colorless, transparent stone of\notherworldly origin, its core aglitter\nwith innumerable refracted light.\nIt is said to react to beings that\noriginate from its home world.",category=2},
[1254]={id=1254,name="colorful abyssite",plural="colorful abyssite",description="\nContact with a creature native to\nits home world has caused this\nformerly colorless stone to take on\na hodgepodge of hues. You sense a\ngrowing power emanating from within.",category=2},
[1255]={id=1255,name="blue abyssite",plural="blue abyssite",description="\nThe confused hues of this\notherworldly stone have stabilized\nand become a rich blue. You sense\ntremendous power emanating from\nwithin.",category=2},
[1256]={id=1256,name="orange abyssite",plural="orange abyssite",description="\nThe confused hues of this\notherworldly stone have stabilized\nand become a vibrant orange. You\nsense tremendous power emanating\nfrom within.",category=3},
[1257]={id=1257,name="brown abyssite",plural="brown abyssite",description="\nThe confused hues of this\notherworldly stone have stabilized\nand become a mellow brown. You\nsense tremendous power emanating\nfrom within.",category=2},
[1258]={id=1258,name="yellow abyssite",plural="yellow abyssite",description="\nThe confused hues of this\notherworldly stone have stabilized\nand become a blazing yellow. You\nsense tremendous power emanating\nfrom within.",category=2},
[1259]={id=1259,name="purple abyssite",plural="purple abyssite",description="\nThe confused hues of this\notherworldly stone have stabilized\nand become a deep purple. You\nsense tremendous power emanating\nfrom within.",category=2},
[1260]={id=1260,name="black abyssite",plural="black abyssite",description="\nEven the darkest night pales to\ngray beside the abyssal black of\nthis stone. It feels ripe to burst\nwith unadulterated power.",category=2},
[1261]={id=1261,name="Magian trial log",plural="Magian trial logs",description="\nA mystical tome bestowed upon you by the Magian Mooglehood, said to record your attempts and exploits in the trials to the last detail.",category=2},
[1262]={id=1262,name="Mog Kupon A-Lum",plural="Mog Kupons A-Lum",description="\nIssued by the Mog House Management Union (MHMU).\nTradeable for spoils from notorious monsters in Lumoria.",category=2},
[1263]={id=1263,name="talisman key",plural="talisman keys",description="\nThe necessary alchemical\nenhancements having been\ncompleted by Ghatsad, this talisman\nnow possesses the power to\ntransport its bearer to the\ninnermost chambers of the Hazhalm\nTesting Grounds.",category=2},
[1264]={id=1264,name="letter from Halver",plural="letters from Halver",description="\nA congratulatory letter from Halver.\nIt bears the wax seal of the Kingdom\nof San d'Oria.",category=2},
[1265]={id=1265,name="letter from Naji",plural="letters from Naji",description="\nA congratulatory letter from Naji.\nIt comes adorned with an illustration\nlovingly drawn by the man himself.",category=2},
[1266]={id=1266,name="letter from Zubaba",plural="letters from Zubaba",description="\nA congratulatory letter from Zubaba.\nIt is impressed with the emblem of\nthe Federation of Windurst.",category=2},
[1267]={id=1267,name="letter from Maat",plural="letters from Maat",description="\nA congratulatory letter from Maat.\nThe odor of sweat clings stubbornly\nto it.",category=2},
[1268]={id=1268,name="letter from Despachiaire",plural="letters from Despachiaire",description="\nA congratulatory letter from\nDespachiaire. Its musty smell\nputs you in mind of a disused\nstoreroom.",category=2},
[1269]={id=1269,name="letter from Jakoh Wahcondalo",plural="letters from Jakoh Wahcondalo",description="\nA congratulatory letter from Jakoh\nWahcondalo. It exudes the faint odor\nof fish.",category=2},
[1270]={id=1270,name="Zvahl passkey",plural="Zvahl passkeys",description="\nCrafted from the same chill stone\nthat forms the foreboding walls of\nthe fortress itself, this key will\ngrant its bearer passage to the\ndeepest, dankest chambers of the\nShadow Lord's stronghold.",category=2},
[1271]={id=1271,name="traverser stone",plural="traverser stones",description="\nA magically imbued stone that\nallows travel to Abyssea. Also\nserves as a stabilizing agent that\nrealigns and anchors your essence\nto foreign dimensions.",category=2},
[1272]={id=1272,name="traverser stone",plural="traverser stones",description="\nA magically imbued stone that\nallows travel to Abyssea. Also\nserves as a stabilizing agent that\nrealigns and anchors your essence\nto foreign dimensions.",category=2},
[1273]={id=1273,name="traverser stone",plural="traverser stones",description="\nA magically imbued stone that\nallows travel to Abyssea. Also\nserves as a stabilizing agent that\nrealigns and anchors your essence\nto foreign dimensions.",category=2},
[1274]={id=1274,name="traverser stone",plural="traverser stones",description="\nA magically imbued stone that\nallows travel to Abyssea. Also\nserves as a stabilizing agent that\nrealigns and anchors your essence\nto foreign dimensions.",category=2},
[1275]={id=1275,name="traverser stone",plural="traverser stones",description="\nA magically imbued stone that\nallows travel to Abyssea. Also\nserves as a stabilizing agent that\nrealigns and anchors your essence\nto foreign dimensions.",category=2},
[1276]={id=1276,name="traverser stone",plural="traverser stones",description="\nA magically imbued stone that\nallows travel to Abyssea. Also\nserves as a stabilizing agent that\nrealigns and anchors your essence\nto foreign dimensions.",category=2},
[1277]={id=1277,name="poet god's key",plural="poet god's keys",description="This ornate bamboo key with its\nsharp jutting protrusions is at once\nghastly and beautiful. The surface is\ngraven with an excerpt from the\nlegendary eclogue of Ree Habalo,\nthe first Manifest of the Yagudo.",category=2},
[1278]={id=1278,name="Orcish infiltration kit",plural="Orcish infiltration kits",description="\nIncludes a meticulously recreated\nOrcish costume that is accurate\nright down to the ripe stench.\nFashioned by a genius San d'Orian\nengineer of undisclosed identity\nfor use in covert operations into\nFort Ghelsba.",category=3},
[1279]={id=1279,name="Atma of the Lion",plural="Atma of the Lion",description="\nThe crystalline agglomeration of\nan Abyssean fiend's soul, said to\nbe the source of its otherworldly\npowers.",category=3},
