[1545]={id=1545,name="crimson granules of time",plural="crimson granules of time",description="\nThought to have once flowed within\nthe prismatic hourglass, these\ngranules of sand cast a dark red\nlight.",category=4},
[1546]={id=1546,name="azure granules of time",plural="azure granules of time",description="\nThought to have once flowed within\nthe prismatic hourglass, these\ngranules of sand cast a deep blue\nlight.",category=4},
[1547]={id=1547,name="amber granules of time",plural="amber granules of time",description="\nThought to have once flowed within\nthe prismatic hourglass, these\ngranules of sand cast a yellowish\nlight.",category=4},
[1548]={id=1548,name="alabaster granules of time",plural="alabaster granules of time",description="\nThought to have once flowed within\nthe prismatic hourglass, these\ngranules of sand cast a pure white\nlight.",category=4},
[1549]={id=1549,name="obsidian granules of time",plural="obsidian granules of time",description="\nThought to have once flowed within\nthe prismatic hourglass, these\ngranules of sand cast an opaque,\nblack light.",category=4},
[1550]={id=1550,name="prismatic hourglass",plural="prismatic hourglass",description="\nThe granules inside this time piece\nglimmer with a myriad of colors, yet\nno matter how violently one upends\nthis device, they move not an inch.\nRumors abound that it holds some\nconnection to the Shrouded Land of\nDynamis.",category=0},
[1551]={id=1551,name="Mog Kupon W-R90",plural="Mog Kupons W-R90",description="\nIssued by the Mog House Management Union (MHMU).\nTradeable for level 90 relic weapons.",category=2},
[1552]={id=1552,name="Mog Kupon W-M90",plural="Mog Kupons W-M90",description="\nIssued by the Mog House Management Union (MHMU).\nTradeable for level 90 mythic weapons.",category=2},
[1553]={id=1553,name="Mog Kupon W-E90",plural="Mog Kupons W-E90",description="\nIssued by the Mog House Management Union (MHMU).\nTradeable for level 90 empyrean equipment.",category=2},
[1554]={id=1554,name="Mog Kupon A-E+2",plural="Mog Kupons A-E+2",description="\nIssued by the Mog House Management Union (MHMU).\nTradeable for Empyrean equipment +2.",category=2},
[1555]={id=1555,name="Mog Kupon I-Seal",plural="Mog Kupons I-Seal",description="\nIssued by the Mog House Management Union (MHMU).\nTradeable for seals used in the enhancement of job-specific equipment.",category=2},
[1556]={id=1556,name="beguiling petrifact",plural="beguiling petrifacts",description="\nA bewitching light shines forth from\nwithin the crystallized walls of this \nfragment ripped from a Voidwalker,\nas if beckoning its bearer to come\nhither.",category=2},
[1557]={id=1557,name="seductive petrifact",plural="seductive petrifacts",description="\nA tantalizing light shines forth from\nwithin the crystallized walls of this \nfragment ripped from a Voidwalker,\nas if appealing to its bearer's most \nardent desires.",category=2},
[1558]={id=1558,name="maddening petrifact",plural="maddening petrifacts",description="\nA crazed light shines forth from\nwithin the crystallized walls of this\nfragment ripped from a Voidwalker,\nas if seeking to breach the bearer's\nlast bastion of sanity.",category=2},
[1559]={id=1559,name="vat of martello fuel",plural="vats of martello fuel",description="\nA thick, viscous liquid infused with\nmagic that serves to power a\nmartello's restorative capabilities.\nHighly dense, it is considerably heavier\nthan it appears.",category=2},
[1560]={id=1560,name="fuel reservoir",plural="fuel reservoirs",description="\nA spare tank that can be installed in a\nmartello to increase its fuel capacity.\nCast of steel and of considerable size,\nit is extremely unwieldy to transport.",category=2},
[1561]={id=1561,name="empty fuel vat",plural="empty fuel vats",description="\nA vat for holding martello fuel, now empty.",category=2},
[1562]={id=1562,name="cracked fuel reservoir",plural="cracked fuel reservoirs",description="\nA martello fuel reservoir, cracked\nbeyond the point of utility due to\nexcessive wear and tear.",category=2},
[1563]={id=1563,name="vial of lambent potion",plural="vials of lambent potion",description="\n A bitter potion steeped in ground\n lambent scales, said to be a powerful\n restorative for memories and the mind.",category=2},
[1564]={id=1564,name="clear demilune abyssite",plural="clear demilune abyssites",description="\nA colorless, transparent stone of\notherworldly origin, shaped like a\ncrescent moon. Its core aglitter with\ninnumerable refracted light, it is\nsaid to react to the presence of\nAbyssean fiends.",category=2},
[1565]={id=1565,name="colorful demilune abyssite",plural="colorful demilune abyssites",description="\nContact with an Abyssean fiend has\ncaused this formerly colorless\ncrescent stone to take on a\nhodgepodge of hues.\nYou sense a growing power\nemanating from within.",category=2},
[1566]={id=1566,name="scarlet demilune abyssite",plural="scarlet demilune abyssites",description="\nThe confused hues of this\notherworldly crescent stone have\nstabilized and become a deep red.\nYou sense tremendous power\nemanating from within.",category=2},
[1567]={id=1567,name="azure demilune abyssite",plural="azure demilune abyssite",description="\nThe confused hues of this\notherworldly crescent stone have\nstabilized and become a rich blue.\nYou sense tremendous power\nemanating from within.",category=2},
[1568]={id=1568,name="viridian demilune abyssite",plural="viridian demilune abyssite",description="\nThe confused hues of this\notherworldly crescent stone have\nstabilized and become a vivid green.\nYou sense tremendous power\nemanating from within.",category=2},
[1569]={id=1569,name="anti-Abyssean grenade #01",plural="anti-Abyssean grenades #01",description="\nAn experimental grenade loaded with\nan explosive charge optimized for\nuse against Abyssean monsters.",category=3},
[1570]={id=1570,name="anti-Abyssean grenade #02",plural="anti-Abyssean grenades #02",description="\nAn experimental grenade loaded with\nan explosive charge optimized for\nuse against Abyssean monsters.",category=3},
[1571]={id=1571,name="anti-Abyssean grenade #03",plural="anti-Abyssean grenades #03",description="\nAn experimental grenade loaded with\nan explosive charge optimized for\nuse against Abyssean monsters.",category=3},
[1572]={id=1572,name="rainbow pearl",plural="rainbow pearls",description="\nA hefty round pearl whose color\ntransitions through a rainbow of\nhues. A key component in the\nrepairs of searing wards.",category=2},
[1573]={id=1573,name="chipped wind cluster",plural="chipped wind clusters",description="\nA cluster of wind crystals that is\nslightly the worse for wear. A key\ncomponent in the repairs of searing\nwards.",category=2},
[1574]={id=1574,name="piece of dried ebony lumber",plural="pieces of dried ebony lumber",description="\nA piece of processed ebony lumber\nthat has been magically purged of\nall moisture. A key component in\nthe repairs of searing wards.",category=2},
[1575]={id=1575,name="Captain Rashid's linkpearl",plural="Captain Rashid's linkpearls",description="\nA replacement linkpearl entrusted to\nyou by Captain Ayame, with\ninstructions that it be delivered to\nCaptain Rashid at Camp Courage.",category=2},
[1576]={id=1576,name="Captain Argus's linkpearl",plural="Captain Argus's linkpearls",description="\nA replacement linkpearl entrusted to\nyou by Captain Ayame, with\ninstructions that it be delivered to\nCaptain Argus at Camp Hope.",category=2},
[1577]={id=1577,name="Captain Helga's linkpearl",plural="Captain Helga's linkpearls",description="\nA replacement linkpearl entrusted to\nyou by Captain Ayame, with\ninstructions that it be delivered to\nCaptain Helga at Camp Vigilance.",category=2},
[1578]={id=1578,name="seal of the resistance",plural="seals of the resistance",description="\nA seal that identifies you as a\nresistance soldier dispatched by\nCaptain Ayame. Show this and state\nthe password of \"rose on the heath,\"\nand even the wariest resistance officer\nwill have no cause to doubt your\nidentity.",category=2},
[1579]={id=1579,name="sunbeam fragment",plural="sunbeam fragments",description="\nA sunbeam fragment found at the\nbottom of a ravine in the La Theine\nPlateau. Becomes invisible by night.",category=2},
[1580]={id=1580,name="Lugarhoo's eyeball",plural="Lugarhoo's eyeballs",description="\nThe left eyeball of Lugarhoo, the\nvicious gnole said to have savaged\nCurilla. The depth of its luster\nshifts with the lunar phase.",category=2},
[1581]={id=1581,name="vial of purification agent (blk.)",plural="vials of purification agents (blk.)",description="\nA vial you received from Miageau\nfilled with a chemical for treating\ncontaminated water. It is affixed\nwith a black label.",category=2},
[1582]={id=1582,name="vial of purification agent (brz.)",plural="vials of purification agents (brz.)",description="\nA vial you received from Miageau\nfilled with a chemical for treating\ncontaminated water. It is affixed\nwith a bronze label.",category=2},
[1583]={id=1583,name="vial of purification agent (slv.)",plural="vials of purification agents (slv.)",description="\nA vial you received from Miageau\nfilled with a chemical for treating\ncontaminated water. It is affixed\nwith a silver label.",category=2},
[1584]={id=1584,name="vial of purification agent (gld.)",plural="vials of purification agents (gld.)",description="\nA vial you received from Miageau\nfilled with a chemical for treating\ncontaminated water. It is affixed\nwith a gold label.",category=2},
[1585]={id=1585,name="black-labeled vial",plural="black-labeled vials",description="\nThis vial contains a water sample\ndrawn from a La Theine pond after\nit had been treated with a\npurification agent.",category=2},
[1586]={id=1586,name="bronze-labeled vial",plural="bronze-labeled vials",description="\nThis vial contains a water sample\ndrawn from a La Theine pond after\nit had been treated with a\npurification agent.",category=2},
[1587]={id=1587,name="silver-labeled vial",plural="silver-labeled vials",description="\nThis vial contains a water sample\ndrawn from a La Theine pond after\nit had been treated with a\npurification agent.",category=2},
[1588]={id=1588,name="gold-labeled vial",plural="gold-labeled vials",description="\nThis vial contains a water sample\ndrawn from a La Theine pond after\nit had been treated with a\npurification agent.",category=2},
[1589]={id=1589,name="rainbow-colored linkpearl",plural="rainbow-colored linkpearls",description="\nA colorful linkpearl you received\nfrom Glenne. It appears optimized\nfor use by intelligence operatives.",category=2},
[1590]={id=1590,name="grey abyssite",plural="grey abyssite",description="\nThe confused hues of this\notherworldly stone have stabilized\nand become an ashen grey. You\nsense tremendous power emanating\nfrom within.",category=2},
[1591]={id=1591,name="ripe starfruit",plural="ripe starfruits",description="\nA starfruit from the stores of the\nManustery. By its color and mouth-\nwatering aroma, you would swear it\nwas freshly picked.",category=2},
[1592]={id=1592,name="vial of flower-wower fertilizer",plural="vials of flower-wower fertilizer",description="\nDeveloped by the Rhinostery and\n(supposedly) perfected by\nPiketo-Puketo of the Culinarians'\nGuild, this liquid is said to \"inject\neven the droopy-woopiest plants with a\nshotaru of vim and vigor!\"",category=2},
[1593]={id=1593,name="Tahrongi tree nut",plural="Tahrongi tree nuts",description="\nA hard-shelled nut roughly the size\nof your fist. It would appear that\nthe fertilizer was as effective as\nadvertised...",category=2},
[1594]={id=1594,name="bucket of compound compost",plural="buckets of compound compost",description="\nA gooey, fetid substance of\ndecaying plant and animal waste\nmatter prepared by Rhinostery\nresearchers. Said to be a preferred\nsnack of mandragora and similar\nspecies.",category=2},
[1595]={id=1595,name="cup of Tahrongi cactus water",plural="cups of Tahrongi cactus water",description="\nA clear liquid that gives off a\nfaintly floral aroma. It is believed\nto be a natural remedy for an\nassortment of ailments and\nafflictions.",category=2},
[1596]={id=1596,name="hastily scrawled poster",plural="hastily scrawled posters",description="\nThis grimy, smudged parchment\nbears a drawing of two indescript\nstick figures that appear to have\nbeen drawn by an artistically\nchallenged child. A near-illegible\nscrawl underneath reads,\n\"Deer Boss! We r fyne. Come\nfynd us quicklee! -Cha 'n Bopa\"",category=2},
[1597]={id=1597,name="bloodied arrow",plural="bloodied arrows",description="\nThis broken arrow was retrieved\nfrom the body of a particularly\nfearsome fiend that had been\nterrorizing Abyssea - Tahrongi.\nThe arrowhead has been snapped\nclean off.",category=2},
[1598]={id=1598,name="crimson bloodstone",plural="crimson bloodstones",description="\nThis gemlike substance of\ncoagulated blood was cut from the\nbody of a monstrous fiend that had\nbeen roaming Abyssea - Tahrongi.\nIt resembles an oversized,\nsemitransparent piece of cruor.",category=2},
[1599]={id=1599,name="Kupofried's medallion",plural="Kupofried's medallions",description="\nThe new form taken by your\nhard-earned gil, if Kupofried the\nmoogle is to be believed. Allows\nthe use of veridical confluxes\nlocated in Vana'diel and the\nWalk of Echoes.",category=2},
[1600]={id=1600,name="pinch of moist Dangruf sulfur",plural="pinches of moist Dangruf sulfur",description="\nWith access to the Dangruf Wadi\nsealed off by landslides, even a\npinch of this rather ordinary sulfur\nfetches a prohibitive price.",category=2},
[1601]={id=1601,name="Naji's gauger plate",plural="Naji's gauger plates",description="\nEntrusted to you by Naji, upon this\nplate is burned the soulprint of a\nmassive purple-skinned fiend. This\nvital intel must be delivered to\nCaptain Helga without delay.",category=2},
[1602]={id=1602,name="Naji's linkpearl",plural="Naji's linkpearls",description="\nA linkpearl that Captain Helga has\nordered you to deliver to the\nintelligence expert Naji. It will allow\nhim to relay his latest findings to\nCaptain Ayame at Central Command.",category=2},
[1603]={id=1603,name="pot of martial relish",plural="pots of martial relish",description="\nAn irresistibly tasty hot relish made\nfrom an age-old recipe, said to grant\nthe resilience of a thousand thorned\nroses.",category=2},
[1604]={id=1604,name="Thierride's bean creation",plural="Thierride's bean creation",description="\nRusty Anchor Pub owner Thierride's\nlatest culinary creation. The rising\nsteam fills your nostrils with the rich\naroma of freshly baked beans.",category=2},
[1605]={id=1605,name="tiny memory fragment",plural="tiny memory fragments",description="\nThe fragment of Lilisette's memory\nyou obtained at the Rusty Anchor\nPub. It glows feebly, as if struggling\nfor purchase on existence.",category=2},
[1606]={id=1606,name="large memory fragment",plural="large memory fragments",description="\nThe fragments of Lilisette's memory\nyou found scattered across present-\nday Vana'diel have melded together\nto form this larger piece. It radiates\nwarmly with the promise of life.",category=2},
[1607]={id=1607,name="fey stone",plural="fey stones",description="\nA night immersed in the pristine\nwaters of the fey spring has imbued\nyour philosopher's stone with\ncounter-curse properties...hopefully.",category=2},
[1608]={id=1608,name="large memory fragment",plural="large memory fragments",description="\nThe fragment of Lilisette's memory\nyou obtained in past Southern San\nd'Oria. Born of a daughter's desire\nto save her father from the jaws of\ndeath, it emanates an aura of hope\nand sorrow.",category=2},
[1609]={id=1609,name="torn recipe page",plural="torn recipe pages",description="\nRoughly torn off a tome, this lone\npage contains the recipe for what\nappears to be a traditional Tavnazian\ndish. It is soiled from its time out in\nthe wilderness.",category=2},
[1610]={id=1610,name="mineral gauge for dummies",plural="mineral gauges for dummies",description="\nDeveloped by Sieglinde the alchemist,\nthis stick-shaped contraption is used\nto analyze the mineral composition\nof soil. Simply thrust it into the\nearth, and the result will be displayed\nby way of a colored light.",category=2},
[1611]={id=1611,name="tube of alchemical fertilizer",plural="tubes of alchemical fertilizer",description="\nA liquid fertilizer especially blended\nby Sieglinde the alchemist, complete\nwith its own injector tube. Although\npotent, it suffers from severely short\nshelf-life.",category=2},
[1612]={id=1612,name="large memory fragment",plural="large memory fragments",description="\nThe fragment of Lilisette's memory\nyou obtained in past Batallia Downs.\nA recollection of Lilisette's escapades\nas matchmaker for Ragelise and Portia,\nit emanates a bittersweet aura.",category=2},
[1613]={id=1613,name="large memory fragment",plural="large memory fragments",description="\nA fragment of Lilisette's memory you\nobtained in past Vana'diel. Born of\nher longing to be close to a dear friend,\nit emanates an aura of fondness.",category=2},
[1614]={id=1614,name="pulse martello repair pack",plural="pulse martello repair packs",description="\nA shipment of supplies lost en route\nto the Attohwa resistance outpost.\nContains materials used in the\nmaintenance of the pulse martello.",category=2},
[1615]={id=1615,name="clone ward reinforcement pack",plural="clone ward reinforcement packs",description="\nA shipment of supplies lost en route\nto the Attohwa resistance outpost.\nContains materials used in the\nreinforcement of clone wards.",category=2},
[1616]={id=1616,name="pack of outpost repair tools",plural="packs of outpost repair tools",description="\nA shipment of supplies lost en route\nto the Attohwa resistance outpost.\nContains tools used in the\nmaintenance of traps and other\ndefensive structures.",category=2},
[1617]={id=1617,name="Parradamo supply pack",plural="Parradamo supply packs",description="\nA pack containing a linkpearl and\nemergency rations, to be delivered\nto one of the scouts that have\ngone missing at Parradamo Tor.",category=2},
[1618]={id=1618,name="Parradamo supply pack",plural="Parradamo supply packs",description="\nA pack containing a linkpearl and\nemergency rations, to be delivered\nto one of the scouts that have\ngone missing at Parradamo Tor.",category=2},
[1619]={id=1619,name="Parradamo supply pack",plural="Parradamo supply packs",description="\nA pack containing a linkpearl and\nemergency rations, to be delivered\nto one of the scouts that have\ngone missing at Parradamo Tor.",category=2},
[1620]={id=1620,name="Parradamo supply pack",plural="Parradamo supply packs",description="\nA pack containing a linkpearl and\nemergency rations, to be delivered\nto one of the scouts that have\ngone missing at Parradamo Tor.",category=2},
[1621]={id=1621,name="Parradamo supply pack",plural="Parradamo supply packs",description="\nA pack containing a linkpearl and\nemergency rations, to be delivered\nto one of the scouts that have\ngone missing at Parradamo Tor.",category=2},
[1622]={id=1622,name="gasponia stamen",plural="gasponia stamina",description="\nThe bulbous stamen of the gasponia\nflower, vividly colored in noxious\nhues of red and yellow.",category=2},
[1623]={id=1623,name="rockhopper",plural="rockhoppers",description="\nA rare, distant relative of the\ngrasshopper that makes its habitat\nin mountainous regions.",category=2},
[1624]={id=1624,name="phial of counteragent",plural="phials of counteragent",description="\nA formula concocted by Yoran-Oran\nto induce a reverse mutation in the\nvenomous gasponia flower.",category=2},
[1625]={id=1625,name="damaged stewpot",plural="damaged stewpots",description="\nA large, impressive-looking stewpot\nbearing the mark of the Windurst\nCulinarians' Guild. A fist-sized hole\nin its base renders it useless in its\ncurrent state... ",category=2},
[1626]={id=1626,name="Naruru's stewpot",plural="Naruru's stewpots",description="\nA large, impressive-looking stewpot\nbearing the mark of the Windurst\nCulinarians' Guild, restored just\nlike nouveau by zee ezteemed\nRanpi-Monpi.",category=2},
[1627]={id=1627,name="magicked hempen sack",plural="magicked hempen sacks",description="\nThis seemingly nondescript hempen\nsack has been magically primed for\nuse in transporting pulse martello\nand clone ward repair materials.",category=2},
[1628]={id=1628,name="magicked flaxen sack",plural="magicked flaxen sacks",description="\nThis seemingly nondescript flaxen\nsack has been magically primed for\nuse in transporting ensorceled battle\nprovisions.",category=2},
[1629]={id=1629,name="paralysis trap fluid",plural="paralysis trap fluids",description="\nThis luminous solution serves as the\nfuel for rear traps.",category=2},
[1630]={id=1630,name="paralysis trap fluid bottle",plural="paralysis trap fluid bottles",description="\nThis trap fluid bottle has been\nemptied of its contents and should\nbe returned to the resistance sapper.",category=3},
[1631]={id=1631,name="weakening trap fluid",plural="weakening trap fluids",description="\nThis luminous solution serves as the\nfuel for fore traps.",category=2},
[1632]={id=1632,name="weakening trap fluid bottle",plural="weakening trap fluid bottles",description="\nThis trap fluid bottle has been\nemptied of its contents and should\nbe returned to the resistance sapper.",category=3},
[1633]={id=1633,name="Iron Eater's pearlsack",plural="Iron Eater's pearlsacks",description="\nA worn grey pearlsack entrusted to\nyou from Iron Eater.",category=3},
[1635]={id=1635,name="medical supply chest",plural="medical supply chests",description="\nA chest laden with medical supplies\nfor use on the battlefront.",category=2},
[1636]={id=1636,name="woodworker's belt",plural="woodworker's belt",description="\nCheupirudaux's pride and joy, this\nhandy, many-pocketed belt stores\nall the repair tools a woodworker\ncould ever need. Stuffed into one\npocket is a memo that reads, \"Two\nif it creaks, four if it wavers, five if\nit crumbles.\"",category=2},
[1637]={id=1637,name="espionage pearlsack",plural="espionage pearlsacks",description="\nThe pearls contained in this sack\nare small in size and dyed with\nspecks of dark green and brown,\nso as to fool the eyes of one's\nsubject.",category=3},
[1638]={id=1638,name="chipped linkshell",plural="chipped linkshells",description="\nThough weathered somewhat by\nthe elements, this linkshell appears\nserviceable.",category=2},
[1639]={id=1639,name="grimy linkshell",plural="grimy linkshells",description="\nThough weathered somewhat by\nthe elements, this linkshell appears\nserviceable.",category=2},
[1640]={id=1640,name="cracked linkshell",plural="cracked linkshells",description="\nThough weathered somewhat by\nthe elements, this linkshell appears\nserviceable.",category=2},
[1641]={id=1641,name="pocket supply pack",plural="pocket supply packs",description="\nA supply pack entrusted to you by\nDeraquien. Containing a basic set of\nlightweight metals, it is designed for\nhassle-free transport. Deliver it to\nElmemague at the outpost, and do\nso on foot, as it will not withstand\nthe stress of conflux teleportation.",category=2},
[1642]={id=1642,name="standard supply pack",plural="standard supply packs",description="\nA supply pack entrusted to you by\nDeraquien. Containing a standard\nassortment of materials, it is\ntransportable with only moderate\ndifficulty. Deliver it to Elmemague\nat the outpost, and do so on foot,\nas it will not withstand the stress\nof conflux teleportation.",category=2},
[1643]={id=1643,name="hefty supply pack",plural="hefty supply packs",description="\nA supply pack entrusted to you by\nDeraquien. Containing a full set of\nhigh-density metals, it is positively\nexhausting to carry. Deliver it to\nElmemague at the outpost, and do\nso on foot, as it will not withstand\nthe stress of conflux teleportation.",category=2},
[1644]={id=1644,name="pack of molten slag",plural="pack of molten slag",description="\nWhatever materials were once\ncontained in this supply pack, they\nare little more than refuse now,\nhaving been reduced to a molten\nmess by the energies of a veridical\nconflux. You should report the\nfailure of your mission to Deraquien.",category=2},
[1645]={id=1645,name="letter of receipt",plural="letter of receipt",description="\nA letter from Captain Elmemague\nat the outpost, certifying the\nsuccessful delivery of a set of\nbuilding materials. Return it to\nDeraquien for your reward.",category=2},
[1646]={id=1646,name="smudged letter",plural="smudged letters",description="\nA letter from Teigero-Bangero\naddressed to his missing wife and\nchild. The ink is smudged in\nnumerous places, most likely from\nthe despondent father's tears...",category=2},
[1647]={id=1647,name="yellow linkpearl",plural="yellow linkpearls",description="\nA linkpearl of vivid yellow entrusted\nto you by Naruru for her husband\nTeigero-Bangero. It shines bright,\nbefitting the sunny disposition\nthis loving wife and mother once\npossessed...",category=2},
[1648]={id=1648,name="jester's hat",plural="jester's hats",description="\nA motley cap that was the favorite\nof Panta-Putta, Teigero-Bangero\nand Naruru's willful young son. He\nnow wanders Abyssea - Misareaux in\nsearch of his lost mother and\nfather...",category=2},
[1649]={id=1649,name="jade demilune abyssite",plural="jade demilune abyssite",description="\nThe confused hues of this\notherworldly crescent stone have\nstabilized and become a vivid green.\nYou sense tremendous power\nemanating from within.",category=2},
[1650]={id=1650,name="sapphire demilune abyssite",plural="sapphire demilune abyssite",description="\nThe confused hues of this\notherworldly crescent stone have\nstabilized and become a rich blue.\nYou sense tremendous power\nemanating from within.",category=2},
[1651]={id=1651,name="crimson demilune abyssite",plural="crimson demilune abyssite",description="\nThe confused hues of this\notherworldly crescent stone have\nstabilized and become a deep red.\nYou sense tremendous power\nemanating from within.",category=2},
[1652]={id=1652,name="emerald demilune abyssite",plural="emerald demilune abyssite",description="\nThe confused hues of this\notherworldly crescent stone have\nstabilized and become a rich green.\nYou sense tremendous power\nemanating from within.",category=3},
