[2032]={id=2032,name="Anima Synthesis",plural="Anima Synthesis",description="\nThis forbidden type of alchemy is\nused to drain elemental energy from\nremnants of lost memories, and\ntransform it into a partially\nmaterialized \"quasispirit\" known as\nanima.",category=0},
[2033]={id=2033,name="Alchemic Purification",plural="Alchemic Purification",description="\nThis special alchemy ability allows\nyou to enchant catalysts with\nthe power of white magic.",category=0},
[2034]={id=2034,name="Alchemic Ensorcellment",plural="Alchemic Ensorcellment",description="\nThis special alchemy ability allows\nyou to enchant catalysts with\nthe power of black magic.",category=0},
[2035]={id=2035,name="Trituration",plural="Trituration",description="\nThis special alchemy ability allows\nyou to place ingredients in a\ntriturator, making it easier to\nprocess more medicines with one\ncrystal.",category=0},
[2036]={id=2036,name="Concoction",plural="Concoction",description="\nThis special alchemy ability allows\nyou to concentrate ingredients to\ncreate medicines in the form of a\nsolid drop. These drops have the\nsame effect as their liquid\nequivalents.",category=0},
[2037]={id=2037,name="Iatrochemistry",plural="Iatrochemistry",description="\nThis special alchemy ability allows\nyou to augment an automaton using\nthe techniques of chemical medicine.",category=0},
[2038]={id=2038,name="miasmal counteragent recipe",plural="miasmal counteragent recipe",description="\nThe alchemist Harith's recipe\nfor a counteragent to clear up\nthe miasmas in Attohwa Chasm.\nIt reads:\nWater crystal, one seashell,\none onz of salinator, two\nvials of distilled water.",category=2},
[2039]={id=2039,name="Way of the Alchemist",plural="Way of the Alchemist",description="\nA deceptively slim volume\ncontaining a staggering wealth of\nknowledge for the expert alchemist.\nYou are particularly struck by a\nchapter entitled \"Talk Like an\nAlchemist: How to Sound Positively\nProfound.\"",category=0},
[2040]={id=2040,name="Raw Fish Handling",plural="Raw Fish Handling",description="\nThis special cooking ability\nallows you to prepare raw fish\nwhile maintaining your ingredients'\nfreshness.",category=0},
[2041]={id=2041,name="Noodle Kneading",plural="Noodle Kneading",description="\nThis special cooking ability\nallows you to prepare flour\nand water into tasty pasta.",category=0},
[2042]={id=2042,name="Patissier",plural="Patissier",description="\nThis special cooking ability\nallows you to prepare tasty\nsweets and cakes.",category=0},
[2043]={id=2043,name="Stewpot Mastery",plural="Stewpot Mastery",description="\nThis special cooking ability\nallows you to prepare hearty\nstews.",category=0},
[2044]={id=2044,name="Way of the Culinarian",plural="Way of the Culinarian",description="\nA deceptively slim volume\ncontaining a staggering wealth of\nknowledge for the the expert chef.\nYou are particularly struck by a\nchapter entitled \"The Svelte Chef:\nHow to Enjoy Your Own Creations\nWithout Putting On the Ponzes!\"",category=0},
[2045]={id=2045,name="culinarian's argentum tome",plural="culinarian's argentum tomes",description="A priceless tome given out to the most accomplished craftsmen that details a variety of secret recipes.",category=2},
[2046]={id=2046,name="culinarian's aurum tome",plural="culinarian's aurum tomes",description="A priceless tome given out to the most accomplished craftsmen that details a variety of secret recipes.",category=2},
[2047]={id=2047,name="Spiffy Synth.",plural="Spiffy Synth.",description="DESCRIPTION",category=0},
[2048]={id=2048,name="Voidwatch alarum",plural="Voidwatch alarums",description="\nA missive bearing the Jeunoan seal.\nIt reads, \"In the name of the Grand \nDuke, you are hereby summoned to\narms for the Voidwatch operation.\nReport with all haste to the Palace\nfor further briefing.\"",category=2},
[2049]={id=2049,name="Voidwatcher's emblem: Jeuno",plural="Voidwatcher's emblems: Jeuno",description="\nAn unadorned bronze badge\nsignifying that the wearer is\nauthorized to participate in\nVoidwatch operations conducted\nin the Jeuno region.",category=2},
[2050]={id=2050,name="Voidwatcher's emblem: Qufim",plural="Voidwatcher's emblems: Qufim",description="\nAn unadorned bronze badge\nsignifying that the wearer is\nauthorized to participate in\nVoidwatch operations conducted\nin the Qufim region.",category=2},
[2051]={id=2051,name="loadstone",plural="loadstones",description="\nStriking this enigmatic stone causes it\nto grow heavy for a brief period of\ntime. The process behind its creation\nis a Goblin trade secret and shall\nnever be revealed to outsiders.",category=2},
[2052]={id=2052,name="soul gem",plural="soul gems",description="\nWhat started as an unknown mass\nexpelled from your body by means\nof a cryptic Far Eastern ritual is\nnow a brilliant, shimmering gemstone.\nLife energy flows and pulsates from\nwithin.",category=2},
[2053]={id=2053,name="soul gem clasp",plural="soul gem clasps",description="\nAn unadorned clasp said to have the power to release the energies harbored within a soul gem.",category=2},
[2054]={id=2054,name="tricolor Voidwatcher's emblem",plural="tricolor Voidwatcher's emblems",description="\nStripes of crimson, blue, and\ngreen on this simple yet stately\nbadge signify that its wearer is\nauthorized to participate in\nVoidwatch operations in the greater\nthree nations region.",category=2},
[2055]={id=2055,name="starlight Voidwatcher's emblem",plural="starlight Voidwatcher's emblems",description="\nA single ruby star is set in this\nsilver badge, authorizing its bearer\nto participate in the Voidwatch\neffort at Vunkerl Inlet, Grauberg,\nand Fort Karugo-Narugo.",category=2},
[2056]={id=2056,name="red present",plural="red presents",description="\nWrapped in exquisite yet simple red\nwrapping paper, this Starlight\nCelebration gift is sure to help warm\nthe cockles of anyone's heart.",category=2},
[2057]={id=2057,name="blue present",plural="blue presents",description="\nWrapped in exquisite yet simple blue\nwrapping paper, this Starlight\nCelebration gift is sure to calm\neven the most conflicted of souls.",category=2},
[2058]={id=2058,name="green present",plural="green presents",description="\nWrapped in exquisite yet simple green\nwrapping paper, this Starlight\nCelebration gift is sure to\nrefresh even the weariest of travelers.",category=2},
[2059]={id=2059,name="heart of the bushin",plural="heart of the bushin",description="\nThrough Atori-Tutori's tutelage,\nthe memories of great warriors past\nhave been burned deep into your\nbody and soul...",category=2},
[2060]={id=2060,name="hyacinth stratum abyssite",plural="hyacinth stratum abyssites",description="\nA violet-blue geode shaped like a\nsix-pointed star, carried by all who\nseek to participate in Voidwatch\noperations at planar rifts. Its exact\nproperties far beyond layman\ncomprehension, it is said to feed off\nthe energies of slain Voidwalkers to\ntake on heightened powers...",category=2},
[2061]={id=2061,name="hyacinth stratum abyssite II",plural="hyacinth stratum abyssites II",description="\nA violet-blue geode shaped like a\nsix-pointed star, carried by all who\nseek to participate in Voidwatch\noperations at planar rifts. Its exact\nproperties far beyond layman\ncomprehension, it is said to feed off\nthe energies of slain Voidwalkers to\ntake on heightened powers...",category=2},
[2062]={id=2062,name="amber stratum abyssite",plural="amber stratum abyssites",description="\nA brownish-yellow geode shaped like\na six-pointed star, carried by all who\nseek to participate in Voidwatch\noperations at planar rifts. Its exact\nproperties far beyond layman\ncomprehension, it is said to feed off\nthe energies of slain Voidwalkers to\ntake on heightened powers...",category=3},
[2063]={id=2063,name="amber stratum abyssite II",plural="amber stratum abyssites II",description="\nA brownish-yellow geode shaped like\na six-pointed star, carried by all who\nseek to participate in Voidwatch\noperations at planar rifts. Its exact\nproperties far beyond layman\ncomprehension, it is said to feed off\nthe energies of slain Voidwalkers to\ntake on heightened powers...",category=2},
[2064]={id=2064,name="clairvoy ant",plural="clairvoy ants",description="\nThis unique insect has been bred\nby the caits for the sole purpose\nof projecting images of its\nsurroundings back to them.",category=2},
[2065]={id=2065,name="Kupofried's corundum",plural="Kupofried's corundums",description="\nThis crystalline concoction,\nfashioned from voidstones by the\nclever Kupofried, seems to resonate\nwith a strange entity that resides\nbeyond the distortion within the\nWalk of Echoes.",category=2},
[2066]={id=2066,name="Kupofried's corundum",plural="Kupofried's corundums",description="\nThis crystalline concoction,\nfashioned from voidstones by the\nclever Kupofried, seems to resonate\nwith a strange entity that resides\nbeyond the distortion within the\nWalk of Echoes.",category=2},
[2067]={id=2067,name="Kupofried's corundum",plural="Kupofried's corundums",description="\nThis crystalline concoction,\nfashioned from voidstones by the\nclever Kupofried, seems to resonate\nwith a strange entity that resides\nbeyond the distortion within the\nWalk of Echoes.",category=2},
[2068]={id=2068,name="bronze astrarium",plural="bronze astraria",description="\nThough its gears and pinions have\nlong since come to rest, this\nclockwork calendar apparatus\nrecovered from the Nyzul Isle ruins\nremains a fascinating window into a\nlong-lost civilization.",category=2},
[2069]={id=2069,name="silver astrarium",plural="silver astraria",description="\nThough its gears and pinions have\nlong since come to rest, this\nclockwork calendar apparatus\nrecovered from the Nyzul Isle ruins\nremains a fascinating window into a\nlong-lost civilization.",category=2},
[2070]={id=2070,name="mythril astrarium",plural="mythril astraria",description="\nThough its gears and pinions have\nlong since come to rest, this\nclockwork calendar apparatus\nrecovered from the Nyzul Isle ruins\nremains a fascinating window into a\nlong-lost civilization.",category=2},
[2071]={id=2071,name="gold astrarium",plural="gold astraria",description="\nThough its gears and pinions have\nlong since come to rest, this\nclockwork calendar apparatus\nrecovered from the Nyzul Isle ruins\nremains a fascinating window into a\nlong-lost civilization.",category=2},
[2072]={id=2072,name="platinum astrarium",plural="platinum astraria",description="\nThough its gears and pinions have\nlong since come to rest, this\nclockwork calendar apparatus\nrecovered from the Nyzul Isle ruins\nremains a fascinating window into a\nlong-lost civilization.",category=2},
[2073]={id=2073,name="\"Demons in the Rye\" chronicle",plural="\"Demons in the Rye\" chronicles",description="\nThis brittle parchment contains\nthe last remaining record of some of\nthe first battles that took place\nbetween adventurers and the\nferocious beasts of\nRolanberry Fields.",category=2},
[2074]={id=2074,name="\"Monstrous Mayhem\" report",plural="\"Monstrous Mayhem\" reports",description="\nThis dossier recounts the\nharrowing events surrounding the\nappearance and subsequent slaying\nof certain enormous monsters that\nassaulted the three nations.",category=2},
[2075]={id=2075,name="\"Culling Is Caring\" poster",plural="\"Culling Is Caring\" posters",description="\nOnce hung far and wide throughout\nthe three nations and Jeuno, this\nposter exhorted every citizen in\nthe realm to do their part in\nquelling the beastman menace.",category=2},
[2076]={id=2076,name="\"Merry Moogle Memorial\" guide",plural="\"Merry Moogle Memorial\" guides",description="\nThe hastily assembled sentences\nscrawled haphazardly throughout\nthis itinerary served only to\nfurther confuse any moogle\nnot used to touring with others.",category=2},
[2077]={id=2077,name="Connor's Communique",plural="Connor's Communiques",description="\nAddressed to someone by the name\nof Shirba-Girba in ink that has\nfaded over the generations, the\npassages in this correspondence\nthat remain legible seem to touch\nupon a linkshell heirloom left\nbehind by the writer's father.",category=2},
[2078]={id=2078,name="\"Pernicious Presents\" brief",plural="\"Pernicious Presents\" briefs",description="\nThis brittle parchment contains the\nlast remaining record of some of\nthe first battles that took place\nbetween adventurers and the terrible\ntreants.",category=2},
[2079]={id=2079,name="Little Goblin's Adventure Vol.1",plural="copies of Little Goblin's Adventure Vol.1",description="\nThe whimsical prose of this first\nvolume of travel diaries could only\nhave been written by that cheeky\nGobbie who calls himself Fab.",category=2},
[2080]={id=2080,name="Little Goblin's Adventure Vol.2",plural="copies of Little Goblin's Adventure Vol.2",description="\nThe whimsical prose of this second\nvolume of travel diaries could only\nhave been written by that cheeky\nGobbie who calls himself Fab.",category=2},
