[2131]={id=2131,name="handcrafted spatula",plural="handcrafted spatulas",description="\nAt the behest of the MHMU, the\nCarpenters' Guild crafted a limited\nquantity of these wooden wonders\nand branded their handles with the\nguild's seal of quality.",category=2},
[2132]={id=2132,name="transmuted candle",plural="transmuted candles",description="\nAt the behest of the MHMU, the\nAlchemists' Guild crafted a limited\nquantity of these wax wonders via\nsome mysterious and clandestine\nprocess.",category=2},
[2133]={id=2133,name="gourmet whipped cream",plural="tubs of gourmet whipped cream",description="\nAt the behest of the MHMU, the\nCulinarians' Guild whipped up a\nlimited quantity of these creamy\ncuriosities by employing some\nmysterious and clandestine recipe.",category=2},
