[2143]={id=2143,name="shining fragment",plural="shining fragments",description="\nA whitish fragment of indeterminate\nmatter that appears to have been\nforcefully chipped off some larger\nobject. It exudes a faint glow.",category=2},
[2144]={id=2144,name="glossy fragment",plural="glossy fragments",description="\nA blackish fragment of indeterminate\nmatter that appears to have been\nforcefully chipped off some larger\nobject. It exudes a faint glow.",category=2},
[2145]={id=2145,name="grimoire page",plural="grimoire pages",description="\nA piece of parchment that\ntemporarily records your journeys in\nMeeble Burrows.",category=2},
[2146]={id=2146,name="Moblin pheromone sack",plural="Moblin pheromone sacks",description="\nA tiny sack containing a substance\nsaid to exude Moblin virility.\nA quick dab on the ears should fool the\nMeebles into letting you into the caves.",category=2},
[2147]={id=2147,name="golden wing",plural="golden wings",description="\nProof that you had what it takes to\nbeat the Adjunct course in\nSauromugue Champaign.",category=2},
[2148]={id=2148,name="moss-covered shard",plural="moss-covered shards",description="\nA trinket only those conquering the\nAssistant course in Sauromugue\nChampaign possess.",category=2},
[2149]={id=2149,name="essence of perfervidity",plural="essences of perfervidity",description="\nEssence contained in a glass bottle.\nLet none doubt your prowess,\nInstructor!",category=3},
[2150]={id=2150,name="branded wing",plural="branded wings",description="\nSeared into the feathery texture\nof this wing are the memories of your\nsuccess on the Associate Researcher\ncourse in Sauromugue Champaign.",category=2},
[2151]={id=2151,name="malicious horn",plural="malicious horns",description="\nOnly the most dedicated of Researchers\ncan lay claim to the bent igneous\nhorn of the Meeble Burrows' most\ndread beast in Sauromugue Champaign!",category=2},
[2152]={id=2152,name="sheet of San d'Orian tunes",plural="sheets of San d'Orian tunes",description="\nSheet music that can be played on\nan orchestrion.\n\nMusic List:\nThe Kingdom of San d'Oria\nChateau d'Oraguille\nRonfaure",category=2},
[2153]={id=2153,name="sheet of Bastokan tunes",plural="sheets of Bastok tunes",description="\nSheet music that can be played on\nan orchestrion.\n\nMusic List:\nThe Republic of Bastok\nMetalworks\nGustaberg",category=2},
[2154]={id=2154,name="sheet of Windurstian tunes",plural="sheets of Windurstian tunes",description="\nSheet music that can be played on\nan orchestrion.\n\nMusic List:\nThe Federation of Windurst\nHeavens Tower\nSarutabaruta",category=2},
[2155]={id=2155,name="geomagnetron",plural="geomagnetrons",description="\nThe specially charged stone has the\nability to store the kinetic units\nnecessary for waypoint travel.",category=2},
[2156]={id=2156,name="Adoulinian charter permit",plural="Adoulinian charter permits",description="\nThe bearer of this document is\nofficially certified for travel to\nAdoulin to participate in the\nAdoulinian colonization initiative.\nWhile in Adoulin, the bearer is\nentitled to all the protections\nafforded by Adoulin's government. In\nthe event of the bearer's untimely\ndeath, Adoulin bears the responsibility\nof notifying next of kin.\n",category=3},
[2157]={id=2157,name="Pioneer's Badge",plural="Pioneer's Badges",description="\nEmblazoned with the Sacred City of\nAdoulin's insignia, this tightly woven\npin proclaims to all who gaze upon\nit that its wearer is a pioneer.",category=2},
[2158]={id=2158,name="temporary geomagnetron",plural="temporary geomagnetrons",description="\nGiven to expectant pioneers,\nthis smooth, ash-colored stone has\nthe ability to record energies from\nfounts of power and to store the\nkinetic units necessary for warping.",category=2},
[2159]={id=2159,name="aged Matriarch Naakual crest",plural="aged Matriarch Naakual crests",description="\nAn emblem wrested from Colkhab,\none of the seven ferocious\ncreatures that protect the wilds of\nUlbuka. It has certainly seen better\ndays, as the design that was once\ncarved into it has been worn away\nover the years.",category=3},
[2160]={id=2160,name="aged Riptide Naakual crest",plural="aged Riptide Naakual crests",description="\nAn emblem wrested from Tchakka,\none of the seven ferocious\ncreatures that protect the wilds of\nUlbuka. It has certainly seen better\ndays, as the design that was once\ncarved into it has been worn\naway over the years.",category=3},
[2161]={id=2161,name="aged Firebrand Naakual crest",plural="aged Firebrand Naakual crests",description="\nAn emblem wrested from Achuka,\none of the seven ferocious\ncreatures that protect the wilds of\nUlbuka. It has certainly seen better\ndays, as the design that was once\ncarved into it has been worn\naway over the years.",category=3},
[2162]={id=2162,name="aged Ligneous Naakual crest",plural="aged Ligneous Naakual crests",description="\nAn emblem wrested from Yumcax,\none of the seven ferocious\ncreatures that protect the wilds of\nUlbuka. It has certainly seen better\ndays, as the design that was once\ncarved into it has been worn\naway over the years.",category=3},
[2163]={id=2163,name="aged Booming Naakual crest",plural="aged Booming Naakual crests",description="\nAn emblem wrested from Hurkan,\none of the seven ferocious\ncreatures that protect the wilds of\nUlbuka. It has certainly seen better\ndays, as the design that was once\ncarved into it has been worn\naway over the years.",category=3},
[2164]={id=2164,name="aged Flashfrost Naakual crest",plural="aged Flashfrost Naakual crests",description="\nAn emblem wrested from Kumhau,\none of the seven ferocious\ncreatures that protect the wilds of\nUlbuka. It has certainly seen better\ndays, as the design that was once\ncarved into it has been worn\naway over the years.",category=3},
[2165]={id=2165,name="aged Undying Naakual crest",plural="aged Undying Naakual crests",description="\nAn emblem wrested from Teodor, the\nUndying Naakual and former\nDeathborne Xol. It certainly has\nseen better days, as the design that\nwas once carved into it has been\nworn away over the years.",category=3},
[2166]={id=2166,name="prototype attuner",plural="prototype attuners",description="\nA crystal that stores kinetic units and\nallows the recording of geomagnetic\nfounts. Due to its nature as a \nprototype, its appearance is\nrather unrefined.",category=2},
[2167]={id=2167,name="watercraft",plural="watercrafts",description="\nThis boat enabling passage across\nthe treacherous Zoldeff River can\nbe folded in upon itself as if by\nmagic.",category=2},
[2171]={id=2171,name="restrainment resilience",plural="restrainment resiliences",description="\nA survival skill that grants the\nfortitude to overcome the\namnesiac effects of spinescent protuberances found throughout Eastern Ulbuka.",category=2},
[2179]={id=2179,name="cupful of dust-laden sap",plural="cupfuls of dust-containing sap",description="\nThis amber sap contains trace\namounts of dust left behind by\nfeeding twitherym.",category=2},
[2180]={id=2180,name="mantid bait",plural="pieces of mantid bait",description="\nTwitching slightly, this chapuli is\njust alive enough to serve as\nsuitable mantid bait.",category=2},
[2185]={id=2185,name="vial of toxic Zoldeff water",plural="vials of toxic zoldeff water",description="\nWater isn't supposed to be purple...\nbut in the Zoldeff River, it sure is!",category=2},
[2186]={id=2186,name="fistful of pristine sand",plural="fistfuls of pristine sand",description="\nSome otherworldly energies have\nprevented this sand from succumbing\nto the corruption of the Zoldeff\nRiver.",category=2},
[2190]={id=2190,name="rime ice fragment",plural="rime ice fragments",description="\nThis rime ice, found in\nMorimar Basalt Fields, lacks any\nkind of beauty or luster.",category=2},
[2192]={id=2192,name="broken harpoon",plural="broken harpoons",description="\nA harpoon that shows many signs of\nwear, the most prevalent being the\nhead that snapped completely in\nhalf. Luckily, the Inventors'\nCoalition should be able to make\nthis spear right as rain.",category=2},
[2193]={id=2193,name="extravagant harpoon",plural="extravagant harpoons",description="\nNot only can this harpoon spear\nfish, but thanks to the Inventors'\nCoalition, it can also expand and\nretract as well as move its head\nrhythmically in time with the waves.",category=3},
[2196]={id=2196,name="geomagnetic compass",plural="geomagnetic compasses",description="\nA device created by Anastase\nto assist in the discovery of\ngeomagnetic founts.",category=2},
[2197]={id=2197,name="ocular orb",plural="ocular orbs",description="\nA penumbral mist swirls within\nthis eye, proving your deeds in\nthe Adjunct Course in Batallia\nDowns.",category=3},
[2198]={id=2198,name="pile of noxious grime",plural="piles of noxious grime",description="\nA putrid substance that marks your\nsuccess in the Assistant Course\nin Batallia Downs.",category=2},
[2199]={id=2199,name="pulsating shard",plural="pulsating shards",description="\nA symbol filled with hidden\nmagic that displays your prowess\nin the Instructor Course\nin Batallia Downs.",category=2},
[2200]={id=2200,name="dinner invitation",plural="dinner invitations",description="\nA cordial entreaty to join the\nleaders of the Twelve Orders for\ndinner at Castle Adoulin once their\nassembly has adjourned.",category=2},
[2201]={id=2201,name="rockberry",plural="rockberries",description="\nA berry delicious treat for raptors.\nHard as rock and solid as stone,\nrockberries can only be eaten\nby animals with jaws of iron.",category=2},
[2202]={id=2202,name="rockberry",plural="rockberries",description="\nA berry delicious treat for raptors.\nHard as rock and solid as stone,\nrockberries can only be eaten\nby animals with jaws of iron.",category=2},
[2203]={id=2203,name="rockberry",plural="rockberries",description="\nA berry delicious treat for raptors.\nHard as rock and solid as stone,\nrockberries can only be eaten\nby animals with jaws of iron.",category=2},
[2204]={id=2204,name="\"Logging\"",plural="\"Logging\"",description="\nA survival skill that helps\nadventurers clear the twisted trees\nthat impede the progress of\ncolonization in Eastern Ulbuka.",category=2},
[2205]={id=2205,name="\"Watercrafting\"",plural="\"Watercrafting\"",description="\nA survival skill that grants the\ncapacity to use portable boats to\ncross treacherous waters in Eastern\nUlbuka.",category=2},
[2206]={id=2206,name="\"Demolishing\"",plural="\"Demolishing\"",description="\nA survival skill that grants the\nability to crush walls and boulders\nof hardened magma that prevent\nfurther passage in Eastern Ulbuka.",category=2},
[2207]={id=2207,name="toxin resilience",plural="toxin resiliences",description="\nA survival skill that grants the\nfortitude to withstand the otherwise\noverpowering poisons of pungent\nfungi located in Eastern Ulbuka.",category=2},
[2208]={id=2208,name="paresis resilience",plural="paresis resiliences",description="\nA survival skill that grants the\nstrength to counteract the\ndebilitating effects of numbing\nblossoms found throughout Eastern\nUlbuka.",category=2},
[2209]={id=2209,name="calor resilience",plural="calor resiliences",description="\nA survival skill that grants the\nhardihood to overcome the\nburning effects of steam spouts throughout Eastern Ulbuka.",category=2},
[2210]={id=2210,name="Hen. FS building mat. container",plural="containers of Hennetiel frontier station building materials",description="\nA collection of materials to assist\nin the construction of a frontier\nstation in Foret de Hennetiel.",category=2},
[2211]={id=2211,name="Mor. FS building mat. container",plural="containers of Morimar frontier station building materials",description="\nA collection of materials to assist\nin the construction of a frontier\nstation in the Morimar Basalt Fields.",category=2},
[2212]={id=2212,name="Hen. FS resource container",plural="containers of Hennetiel frontier station resources",description="\nA collection of materials from\nForet de Hennetiel that are bound\nfor the Couriers' Coalition.",category=2},
