[2793]={id=2793,name="\"Sakura and the Fountain\"",plural="copies of \"Sakura and the Fantastical Fountain\"",description="\nThe continuation of Markovic's epic saga follows the journeys of the erstwhile Sakura as she stumbles upon a fantastical fountain that promises to change her life forever. What fortunes await our feathered friend? Pioneers who read it report having their monster rearing rank increase by one.",category=2},
[2794]={id=2794,name="treatise on azimuth clothcraft",plural="treatises on azimuth clothcraft",description="\nThis bound red leather volume contains the secrets to crafting garments identical to those worn by Sih Renaye.",category=2},
