[2798]={id=2798,name="pale azure cloth",plural="pale azure cloths",description="\nThe otherworldly blue hue of this silken cloth pulses in the twilight.",category=2},
[2799]={id=2799,name="order slip: azimuth hood",plural="order slips: azimuth hood",description="\nThe wandering seamstress Helina gave you this piece of parchment as proof of payment for one azimuth hood. The crisp writing says to bring the slip back later to obtain the armor.",category=3},
