[2803]={id=2803,name="order slip: azimuth gaiters",plural="order slips: azimuth gaiters",description="\nThe wandering seamstress Helina gave you this piece of parchment as proof of payment for one pair of azimuth gaiters. The crisp writing says to bring the slip back later to obtain the armor.",category=3},
[2804]={id=2804,name="refined Ra'Kaznar fiber",plural="refined Ra'Kaznar fibers",description="\nThis taut thread, infused with an upswell of power from the depths of Outer Ra'Kaznar, doesn't break no matter how hard it's pulled.",category=2},
[2805]={id=2805,name="order slip: erilaz galea",plural="order slips: erilaz galea",description="\nThis receipt, redeemable for one erilaz galea, should be turned in to Octavernost after some time has passed.",category=3},
[2806]={id=2806,name="order slip: erilaz surcoat",plural="order slips: erilaz surcoat",description="\nThis receipt, redeemable for one erilaz surcoat, should be turned in to Octavernost after some time has passed.",category=3},
[2807]={id=2807,name="order slip: erilaz gauntlets",plural="order slips: erilaz gauntlets",description="\nThis receipt, redeemable for one pair of erilaz gauntlets, should be turned in to Octavernost after some time has passed.",category=3},
[2808]={id=2808,name="order slip: erilaz leg guards",plural="order slips: erilaz leg guards",description="\nThis receipt, redeemable for one pair of erilaz leg guards, should be turned in to Octavernost after some time has passed.",category=3},
[2809]={id=2809,name="order slip: erilaz greaves",plural="order slips: erilaz greaves",description="\nThis receipt, redeemable for one pair of erilaz greaves, should be turned in to Octavernost after some time has passed.",category=3},
[2810]={id=2810,name="purple purgation cloth",plural="purple purgation cloths",description="\nMarcellurin provided this large square cloth used as part of a purgation ritual. It has been dipped countless times in holy water, yet the lustrous purple shows no signs of fading.",category=2},
[2811]={id=2811,name="Margret's writ of summons",plural="Margret's writs of summons",description="\nCurved writing spelling out the sentence \"Meet me on Sverdhried Hillock\" adorns this over-the-top stationery.",category=2},
[2812]={id=2812,name="portrait of Melvien",plural="portraits of Melvien",description="\nThis piece by Margret depicts Melvien in his younger days. The abstract form and judicious use of color are quite striking.",category=2},
[2813]={id=2813,name="Melvien's turn",plural="Melvien's turns",description="\nThis memo dictates the changes in Melvien's personality as described to you by Estienneux. The cause: a tragic incident occuring ten-something years ago.",category=2},
[2814]={id=2814,name="Melvien's death?",plural="Melvien's deaths?",description="\nThis memo contains notes on the incident with Melvien ten-something years ago, as told through the eyes of Mastan. Melvien made a miraculous recovery, having been pronounced all but dead after being struck by lightning.",category=2},
[2815]={id=2815,name="Margret's memo",plural="Margret's memos",description="\nCurved writing spelling out the sentence \"Meet me by the storage container in Rala Waterways (H-6)\" adorns this over-the-top stationery.\n",category=2},
[2816]={id=2816,name="Margret's imposter's cipher",plural="Margret's imposter's ciphers",description="\nThe decorations on the stationery are frayed around the edges, and spell out in jagged lettering, \"Carry memories on your back and head for the strange light.\"",category=2},
[2817]={id=2817,name="Margret's imposter's cipher redux",plural="Margret's imposter's cipher reduxs",description="\nThe decorations on the stationery are frayed around the edges, and spell out in jagged lettering, \"I shall foul the very earth thou walkest on.\"\n",category=2},
[2818]={id=2818,name="fabricated pearl of impurity",plural="fabricated pearls of impurity",description="\nBlack eddies of impurity pulse within this otherwise gleaming pearl.",category=2},
[2819]={id=2819,name="fabricated pearl of miasma",plural="fabricated pearls of miasma",description="\nSickly green noxious threads threaten to erupt from this otherwise gleaming pearl.",category=2},
[2820]={id=2820,name="fabricated pearl of biting winds",plural="fabricated pearls of biting winds",description="\nA tiny tempest rages within this otherwise gleaming pearl.",category=2},
[2821]={id=2821,name="fabricated pearl of ashen wings",plural="fabricated pearls of ashen wings",description="\nAn ashen imprint of a torn wing mars the surface of this otherwise gleaming pearl.",category=2},
[2822]={id=2822,name="fabricated pearl of the false king",plural="fabricated pearls of the false king",description="\nNecrotic energies seep from the surface of this otherwise gleaming pearl.",category=2},
[2823]={id=2823,name="prototype pearl of ashen wings",plural="prototype pearls of ashen wings",description="\nThe marbled swirlings in this pearl can copy and replicate information gleaned from the memories of the bearer's battles. By itself, the pearl has no power to open up the extant gates in Outer Ra'Kaznar.",category=2},
[2824]={id=2824,name="prototype pearl of the false king",plural="prototype pearls of the false king",description="\nThe marbled swirlings in this pearl can copy and replicate information gleaned from the memories of the bearer's battles. By itself, the pearl has no power to open up the extant gates in Outer Ra'Kaznar.",category=2},
[2825]={id=2825,name="Gilgamesh's introductory letter",plural="Gilgamesh's introductory letters",description="\nThis letter of introduction, provided by Gilgamesh, serves as an unmistakable sign of his faith and trust in you. Present it to Vera in Mhaura or Isacio in Selbina and see if his words carry any weight.",category=2},
[2826]={id=2826,name="imperial chair",plural="imperial chairs",description="\nThis comfortable chair was fashioned by a renowned designer collective for the nobility of San d'Oria. Using the text command \"/sitchair 1\" enables the bearer to relax upon this luxurious furnishing.",category=3},
[2827]={id=2827,name="decorative chair",plural="decorative chairs",description="\nThis comfortable chair was fashioned by a renowned designer collective for Bastok's movers and shakers. Using the text command \"/sitchair 2\" enables the bearer to relax upon this luxurious furnishing.",category=2},
[2828]={id=2828,name="ornate stool",plural="ornate stools",description="\nThis comfortable stool was fashioned by a renowned designer collective for the upper echelons of Windurstian society to greet guests in Heavens Tower. Using the text command \"/sitchair 3\" enables the bearer to relax upon this luxurious furnishing.",category=3},
[2829]={id=2829,name="refined chair",plural="refined chairs",description="\nUsing the text command \"/sitchair 4\" enables the bearer to relax upon this luxurious furnishing given only to the most accomplished of adventurers.",category=2},
[2830]={id=2830,name="portable container",plural="portable containers",description="\nUsing the text command \"/sitchair 5\" enables the bearer to relax upon this luxurious furnishing.",category=2},
[2831]={id=2831,name="chocobo chair",plural="chocobo chairs",description="\nUsing the text command \"/sitchair 6\" enables the bearer to relax upon this luxurious furnishing.",category=2},
[2832]={id=2832,name="Ephramadian throne",plural="Ephramadian thrones",description="\nUsing the text command \"/sitchair 7\" enables the bearer to relax upon this luxurious furnishing.",category=2},
[2833]={id=2833,name="shadow throne",plural="shadow thrones",description="\nUsing the text command \"/sitchair 8\" enables the bearer to relax upon this luxurious furnishing.",category=2},
[2834]={id=2834,name="leaf bench",plural="leaf benches",description="\nUsing the text command \"/sitchair 9\" enables the bearer to relax upon this luxurious furnishing.",category=2},
[2835]={id=2835,name="astral cube",plural="astral cubes",description="\nUsing the text command \"/sitchair 10\" enables the bearer to relax upon this luxurious furnishing.",category=3},
[2836]={id=2836,name="chocobo chair II",plural="chocobo chairs II",description="\nUsing the text command \"/sitchair 11\" enables the bearer to relax upon this luxurious furnishing.",category=2},
[2837]={id=2837,name="Reisenjima Sanctorium orb",plural="Reisenjima Sanctorium orbs",description="\nA pale yellow orb given to you by Iroha that can light the way to the future.",category=2},
[2838]={id=2838,name="\"Sakura and the Magicked Net\"",plural="copies of \"Sakura and the Magicked Net\"",description="\nEntry three in the Sakura series, this volume details an enigmatic net that washed ashore and changed the course of chocobo evolution. Pioneers who read it report having their monster rearing rank increase by one.",category=2},
[2839]={id=2839,name="reaper",plural="reapers",description="\nAn enigmatic device used to harvest materials from within Escha and Reisenjima.",category=2},
[2840]={id=2840,name="forgotten memory",plural="forgotten memories",description="\nA vivid scene depicting the struggle between the dread jester Balamor and two adventurers. A valiant warrior suffered a grievous wound shielding his young daughter in the conflict, and his wife made an impossible decision to save her husband's life--a decision that cost them their daughter and led to the creation of an entirely new entity.",category=2},
[2841]={id=2841,name="＿",plural="＿",description="\n???",category=2},
[2842]={id=2842,name="weathered Haverton hat",plural="weathered Haverton hats",description="\nA long-brimmed hat bearing the crest of a raven. It shields the wearer's gaze from the sun, enabling them to fire off a swift barrage of arrows that always strike their mark. Only those with proven prowess are given the honor of donning such a priceless piece.",category=2},
[2843]={id=2843,name="lightsworm",plural="lightsworms",description="\nThis tiny glowing worm given to you by Cait Sith allows for safe passage into the Walk of Echoes.",category=2},
[2844]={id=2844,name="\"Sakura's Excellent Adventure\"",plural="copies of \"Sakura's Excellent Adventure\"",description="\nThe fourth volume in Markovic's magnum opus depicts Sakura chancing upon one of the famous Mog Tablets. Yet who is the shadowy figure that wrests the artifact from her clutches? Pioneers who read it report having their monster rearing rank increase by one.",category=2},
[2845]={id=2845,name="\"Sakura and the Cactus Corps\"",plural="copies of \"Sakura and the Cactus Corps\"",description="\nThe fifth volume in this endless series of adventures traces the origin of a mysterious letter sent to Sakura by Cactrot Rapido challenging her to a duel for the ages. The hopes of a nation rest on the chocobo's fluffy wings! Pioneers who read it report having their monster rearing rank increase by one.",category=2},
[2846]={id=2846,name="\"Sakura and the Holy Grail\"",plural="copies of \"Sakura and the Holy Grail\"",description="\nThe seemingly endless Sakura series reaches its thrilling conclusion! Sakura, having heard tales of a holy grail in Ulbuka, successfully makes a voyage to the western continent only to be besieged by crabs and Qiqirns on all sides! How will she ever work her way out of this one? Pioneers who read it report having their monster rearing rank increase by one.",category=2},
[2847]={id=2847,name="Siren's plume",plural="Siren's plumes",description="\nThis verdant green plume flutters delicately even when the skies are perfectly still, and its tip points unerringly toward the nearest crystal.",category=2},
[2848]={id=2848,name="Moglification: Resist Sleep",plural="Moglification: Resist Sleep",description="\nMoogle-powered assistance from your Mog House. Slightly improves your resistance to sleep effects.",category=2},
[2849]={id=2849,name="Moglification: Resist Poison",plural="Moglification: Resist Poison",description="Moogle-powered assistance from\nyour Mog House.\nSlightly improves your resistance to poison effects.",category=2},
