[2853]={id=2853,name="Moglification: Resist Petrification",plural="Moglification: Resist Petrification",description="Moogle-powered assistance from\nyour Mog House.\nSlightly improves your resistance to petrification effects.",category=2},
[2854]={id=2854,name="Moglification: Resist Virus",plural="Moglification: Resist Virus",description="\nMoogle-powered assistance from\nyour Mog House.\nSlightly improves your resistance to virus effects.",category=2},
[2855]={id=2855,name="Moglification: Resist Curse",plural="Moglification: Resist Curse",description="\nMoogle-powered assistance from\nyour Mog House.\nSlightly improves your resistance to curse effects.",category=2},
[2880]={id=2880,name="iridal core of the ruins",plural="iridal cores of the ruins",description="\nThis core is said to resonate with a strange device found in Fei'Yin.",category=3},
[2881]={id=2881,name="iridal core of the tomb",plural="iridal cores of the tomb",description="\nThis core is said to resonate with a strange device found in King Ranperre's Tomb.",category=3},
[2882]={id=2882,name="iridal core of the pass",plural="iridal cores of the pass",description="\nThis core is said to resonate with a strange device found in Ranguemont Pass.",category=3},
[2883]={id=2883,name="arcus fiber",plural="arcus fibers",description="\nThis iridescent fiber contains vital essences of each of the eight elements.\n",category=3},
