[2926]={id=2926,name="\"Card Jailer Teodor\"",plural="copies of \"Card Jailer Teodor\"",description="\nThis tightly bound volume details all the tips and tricks for winning at the Mummers' Coalition game \"Boom or Bust\" and other such games of chance. Those in possession of such a playbook need only show it to the man in black for him to acquiesce in a test of wills.",category=2},
