[2957]={id=2957,name="Ark Angel GK's bangle",plural="Ark Angel GK's bangles",description="\nA grisly trinket that can be used to attract the attention of a particular monster residing deep within Escha.",category=2},
[2958]={id=2958,name="most curious curio",plural="most curious curios",description="\nThis tiny figure created by Koru-Moru can sense all manner of evil and ill will throughout Vana'diel. The three most vaunted academics in all of Windurst can put their heads together to interpret its signs.\n",category=2},
[2959]={id=2959,name="most confounding curio",plural="most confounding curios",description="\nThis tiny figure created by Koru-Moru could once sense all manner of evil and ill will throughout Vana'diel, but it appears to have fully stopped functioning due to an overload of energies. Perhaps it will regain its powers if you step away from the interference.",category=2},
[2960]={id=2960,name="macabre simulacrum",plural="macabre simulacra",description="\nA lurid white skull stares back at you from the back of this moth simulacrum. Those possessing one can enter Balamor's alternate universe via an infernal transposer.",category=2},
[2961]={id=2961,name="motionless plume",plural="motionless plumes",description="\nThe color and energy have been all but drained from this plume, which once contained a portion of Siren's essence. It may be revitalized upon reaching the skies.",category=2},
[2962]={id=2962,name="guffawshroom",plural="guffawshrooms",description="\nThe dotted patterns in this tiny shroom found in Sih Gates are arranged in a cute smiley-face pattern. Though mildly toxic, it can be crushed into a fine powder and used to treat a variety of maladies.",category=2},
[2963]={id=2963,name="job gesture: geomancer",plural="job gestures: geomancer",description="\nStrike a pose befitting a storied geomancer.",category=2},
[2964]={id=2964,name="job gesture: rune fencer",plural="job gestures: rune fencer",description="\nStrike a pose befitting an attuned rune fencer.",category=2},
[2965]={id=2965,name="golden shovel cordon",plural="golden shovel cordon",description="\nEmbroidered with a gleaming\ngolden shovel, this badge is given\nonly to pioneers who have gone\nabove and beyond the call of duty\nin advancing the colonization\ninitiative. Reduces the\nwaiting period for new\ncoalition imprimaturs.",category=2},
[2966]={id=2966,name="fabricated ward of impurity",plural="fabricated wards of impurity",description="\nBlack eddies of impurity dot the surface of this glowing rune.",category=2},
[2967]={id=2967,name="fabricated ward of miasma",plural="fabricated wards of miasma",description="\nSickly green noxious threads threaten to erupt from this glowing rune.",category=2},
[2968]={id=2968,name="fabricated ward of biting winds",plural="fabricated wards of biting winds",description="\nA tiny tempest rages within this glowing rune.",category=2},
[2969]={id=2969,name="fabricated ward of ashen wings",plural="fabricated wards of ashen wings",description="\nThe marbled swirlings in this glowing rune can copy and replicate information gleaned from the memories of the bearer's battles.",category=2},
[2970]={id=2970,name="fabricated ward of the false king",plural="fabricated wards of the false king",description="\nThe marbled swirlings in this glowing rune can copy and replicate information gleaned from the memories of the bearer's battles.",category=2},
[2971]={id=2971,name="song of hope",plural="songs of hope",description="\nIroha has called out to you in a vision, bequeathing unto you a divine radiance that can guide you ever forward. You may be able to learn more at the crag of Holla, Dem, or Mea.",category=2},
[2972]={id=2972,name="founder king's orb",plural="founder king's orbs",description="A precious artifact of the founder king that Balamor has long been hunting for. A fearsome upswell of magic threatens to burst from its glassy confines.",category=2},
[2973]={id=2973,name="Cait Sith's whisker",plural="Cait Sith's whiskers",description="A thin strand plucked directly from Cait Sith's regal visage. It possesses the power to ensure that the bearer cannot stray from his true path.",category=2},
[2974]={id=2974,name="extradimensional scar",plural="extradimensional scars",description="A small device presented by Selh'teus that lights the way in times of danger.\n",category=2},
[2975]={id=2975,name="breath of the avatars",plural="breaths of the avatars",description="A small portion of power that the avatars bestowed upon you in the stone circle in La Theine Plateau. Its soft embrace will enable to you pass through the crystal in Reisenjima even without having the ability to become a god of light.",category=2},
[2976]={id=2976,name="primary nazar",plural="primary nazars",description="\nA charm in the shape of an eye designed to ward off evil spirits.",category=2},
