[3025]={id=3025,name="Mog Kupon AW-Cos",plural="Mog Kupon AW-Cos",description="\nIssued by the Mog House Management Union (MHMU).\nTradeable for a variety of costumes.",category=2},
[3026]={id=3026,name="Phoenix's blessing",plural="Phoenix's blessings",description="\nA portion of Phoenix's vim and vigor entrusted to you by Iroha. She will always remain by your side, even though you may not be able to see her.",category=2},
[3027]={id=3027,name="packet of Midras's explosives",plural="packets of Midras's explosives",description="\nA custom blend of explosives for blasting through Palborough Mines' bedrock. While the explosive force is small, the chemical reaction it produces with the rock makes it perfect for clearing obstacles where delicacy is required.",category=2},
[3028]={id=3028,name="tarnished ring",plural="tarnished rings",description="\nA simple silver band found in Palborough Mines. It may have once belonged to a victim of the explosion.",category=2},
[3029]={id=3029,name="rusty locket",plural="rusty lockets",description="\nA worn and rusty locket found in Palborough Mines. It may have once belonged to a victim of the explosion.",category=2},
[3030]={id=3030,name="invitation to a feast most dire",plural="invitations to a feast most dire",description="\nA letter of invitation to a feast most dire given to you by Kupofried.\nContent level: 119\nApplicable battlefields: Horlais Peak, Waughroon Shrine, and Balga's Dais",category=2},
[3031]={id=3031,name="radialens",plural="radialenses",description="\nA special lens whose refractive properties can see through unholy veils to unmask threats within Reisenjima and Escha areas.",category=2},
[3032]={id=3032,name="mollifier",plural="mollifiers",description="\nQuells the anger of certain foes, preventing them from calling their leaders to aid them in battle.",category=2},
[3033]={id=3033,name="Mog Kupon AW-Kupo",plural="Mog Kupon AW-Kupo",description="\nIssued by the Mog House Management Union (MHMU).\nTradeable for kupo equipment.",category=2},
[3034]={id=3034,name="drained orb",plural="drained orbs",description="\nBalamor has drained a significant portion of the power once housed in the orb that Iroha gave to you.",category=2},
