[3051]={id=3051,name="Mog Patio design document",plural="Mog Patio design documents",description="\nThis plan, written by the Mog House Management Union, describes in intricate detail the parameters, requirements, and necessities regarding a Mog Patio. Those in possession of these plans can construct a Mog Patio if their Mog House has a second floor.",category=2},
[3052]={id=3052,name="Ambuscade Primer Volume One",plural="Ambuscade Primers Volume One",description="\nThe first installment of a primer detailing the ins and outs of Ambuscade, penned by the esteemed mage Abdhaljs and a particularly diligent member of the Adventurers' Mutual Aid Network (A.M.A.N.).",category=3},
[3053]={id=3053,name="Ambuscade Primer Volume Two",plural="Ambuscade Primers Volume Two",description="\nThe second installment of a primer detailing the ins and outs of Ambuscade, penned by the esteemed mage Abdhaljs and a particularly diligent member of the Adventurers' Mutual Aid Network (A.M.A.N.).",category=3},
[3055]={id=3055,name="trainer's whistle",plural="trainer's whistles",description="\nThis whistle enables the bearer to call forth their trusty steed--or its equivalent--to their side. Once properly registered, the adventurer will be able to ride the mount of their choice.",category=2},
