[3069]={id=3069,name="shimmering invitation",plural="shimmering invitations",description="\nThis missive, penned by the green thumb moogle, entreats the ephemeral moogle to join him in the Mog Gardens. In it he espouses all the wonderful parts of the gardens--the soothing shoreline, grass swaying in the wind, the fresh sun beating down on your rosy cheeks...in fact, the letter goes on for pages upon pages of endless exposition.",category=2},
[3070]={id=3070,name="Grunt Heard 'Round the World",plural="copies of \"Grunt Heard 'Round the World\"",description="\nThis tale of a kind-hearted Mithra and her chance meeting with a leafkin tells of how good friendships can lead to good business. Why exactly this has an ill effect on those playing Boom or Bust is a question best left to the philosophers.",category=2},
