[3166]={id=3166,name="broken flying machine",plural="broken flying machines",description="\nAn odd contraption once ridden by Eald'narche. It appears to be in quite the state of disrepair, but perhaps it can be restored to its former state.\n",category=2},
[3167]={id=3167,name="levitation device",plural="levitation devices",description="\nAn attachment likely to have been used in the flying machine, this device serves no purpose on its own. You may be able to get a hint for how to repair it by examining the strange apparatus in Fei'Yin.\n",category=2},
[3168]={id=3168,name="whirring engine",plural="whirring engines",description="\nAn attachment likely to have been used in the flying machine, this device vibrates softly as it rapidly spins.",category=2},
