[3170]={id=3170,name="Deed Voucher",plural="Deed Vouchers",description="A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for a full set of item level 109 artifact armor (head, chest, hands, legs, and feet) of your choosing.",category=2},
