[3181]={id=3181,name="tentacle touching ticket",plural="tentacle touching tickets",description="\nA ticket that permits the bearer to shake appendages with the members of the morbol idol group Shining Bless. Written in tiny chigoe-sized font at the back is a disclaimer: Vana'diel Productions and the M.H.M.U. bear no responsibility for any paralysis, silence, poison, blindness, weight, slow, sudden death, or any related trauma real or perceived that may occur during the performance.",category=2},
[3182]={id=3182,name="Invitation from Excenmille",plural="Invitations from Excenmille",description="\nI await you at the Peak of Horlais, where I hope you will do me the favor of crossing blades...or whatever means of warfare you deem necessary.",category=3},
[3183]={id=3183,name="Invitation from Naji",plural="Invitations from Naji",description="\nThink you've got what it takes to beat me? Then I'll be waiting at Waughroon Shrine--but don't get your hopes up!",category=3},
[3184]={id=3184,name="Invitation from Kupipi",plural="Invitations from Kupipi",description="\nI'm ve～ry pleased-weased to challenge you at Balga's Dais! Don't be lataru, or you'll be in for a good smacking!",category=3},
