[3202]={id=3202,name="Cheer: Mandragora Sproutling",plural="Cheers: Mandragora Sproutling",description="\nA cheer from Chacharoon based on\nthe pleasant memories of raising a\nmandragora sproutling.\nIncreases vitality by 2 and increases alter ego auto-regen by 2.",category=2},
[3203]={id=3203,name="Cheer: Mandragora",plural="Cheers: Mandragora",description="\nA cheer from Chacharoon based on\nthe pleasant memories of raising a\nmandragora.\nIncreases vitality by 3 and increases alter ego physical evasion by 6%.",category=2},
[3204]={id=3204,name="Cheer: Elder Mandragora",plural="Cheers: Elder Mandragora",description="\nA cheer from Chacharoon based on\nthe pleasant memories of raising an\nelder mandragora.\nIncreases vitality by 4, and increases alter ego auto-regen by 4 and physical evasion by 7%.",category=2},
[3205]={id=3205,name="Cheer: Lycopodium",plural="Cheers: Lycopodium",description="\nA cheer from Chacharoon based on\nthe pleasant memories of raising a\nlycopodium.\nIncreases charisma by 3 and increases alter ego physical defense by 4%.",category=2},
[3206]={id=3206,name="Cheer: Ake-Ome",plural="Cheers: Ake-Ome",description="\nA cheer from Chacharoon based on\nthe pleasant memories of raising an\nake-ome.\nIncreases charisma by 4, increases alter ego physical defense by 5%, and confers a capacity point bonus of 5%.",category=2},
[3207]={id=3207,name="Cheer: Adenium",plural="Cheers: Adenium",description="\nA cheer from Chacharoon based on\nthe pleasant memories of raising an\nadenium.\nIncreases Resist Sleep by 10 and increases alter ego auto-regen by 3 and magic evasion by 6% (effective at item level 100 and above).",category=2},
[3208]={id=3208,name="Cheer: Elder Adenium",plural="Cheers: Elder Adenium",description="\nA cheer from Chacharoon based on\nthe pleasant memories of raising an\nelder adenium.\nIncreases Resist Sleep by 10 and increases alter ego auto-regen by 4, magic evasion by 7% (effective at item level 100 and above), and Double Attack by 2%.",category=2},
[3209]={id=3209,name="Cheer: Korrigan",plural="Cheers: Korrigan",description="\nA cheer from Chacharoon based on\nthe pleasant memories of raising a\nkorrigan.\nIncreases Resist Poison by 10 and increases alter ego auto-regen by 3 and physical and ranged attack by 5%.",category=2},
[3210]={id=3210,name="Cheer: Pachypodium",plural="Cheers: Pachypodium",description="\nA cheer from Chacharoon based on\nthe pleasant memories of raising a\npachypodium.\nIncreases Resist Poison by 10 and alter ego auto-regen by 4, physical and ranged attack by 6%, and Double Attack by 2%.",category=2},
[3211]={id=3211,name="Cheer: Citrullus",plural="Cheers: Citrullus",description="\nA cheer from Chacharoon based on\nthe pleasant memories of raising a\ncitrullus.\nIncreases Resist Blind by 10 and alter ego auto-regen by 5 and haste by 5%.",category=2},
[3212]={id=3212,name="moglophone",plural="moglophones",description="\nA convenient device created by mysterious moogle magic that automatically sends information about \"the secret place\" to the moogle who devised it.",category=2},
