[3224]={id=3224,name="Primer on Martial Techniques",plural="Primers on Martial Techniques",description="\nA heavy, cloth-wrapped book on all manner of special techniques for mastering various armaments.\n",category=2},
[3225]={id=3225,name="Treatise on Martial Techniques",plural="Treatises on Martial Techniques",description="\nA heavy, cloth-wrapped book on an even greater number of special techniques for mastering various armaments.\n",category=2},
[3226]={id=3226,name="sheet of Al'Taieu tunes",plural="sheets of Al'Taieu tunes",description="\nSheet music that can be played on\nan orchestrion.\n\nMusic List:\nThe Celestial Capital - Al'Taieu",category=2},
[3227]={id=3227,name="sheet of Jeuno tunes",plural="sheets of Jeuno tunes",description="\nSheet music that can be played on\nan orchestrion.\n\nMusic List:\nThe Grand Duchy of Jeuno\nRu'Lude Gardens",category=2},
[3228]={id=3228,name="sheet of harvest tunes",plural="sheets of harvest tunes",description="\nSheet music that can be played on\nan orchestrion.\n\nMusic List:\nDevils' Delight",category=2},
[3229]={id=3229,name="star-crested summons",plural="star-crested summons",description="\nA special missive emblazoned with a white star. Each individual letter seems to glimmer with an inner glow. Intended recipient: Tosuka-Porika.",category=2},
[3230]={id=3230,name="strange doll",plural="strange dolls",description="\nThis doll, found in Giddeus, is ostensibly a magicked figure, but to your eyes it appears as harmless and cute as a child's toy. It is wholly lacking in the vengeful nature you would expect of the real thing.",category=2},
[3231]={id=3231,name="piece of evidence",plural="pieces of evidence",description="\nL uhtxluh wkh vshfldo hjj dqg d yhub vwurqj lqglylgxdo. Iluvw frphv wkh hjj.\n\n*A treble for when you're in trouble.",category=2},
[3232]={id=3232,name="sublime lucky egg",plural="sublime lucky eggs",description="\nAn egg inscribed with a special pattern said to bring good luck to the bearer. This one is of exceptional quality.",category=2},
[3233]={id=3233,name="magicked doll",plural="magicked dolls",description="\nA magicked doll liberated from Honoi-Gomoi. It is incredibly old, and of a color you're not sure you've ever seen before. Its eyes give a glimpse into its dark soul.",category=2},
[3234]={id=3234,name="moglophone II",plural="moglophones II",description="\nA convenient device created by mysterious moogle magic that automatically sends information about \"the secret place\" to the moogle who devised it. The range is shorter than the original model.",category=2},
[3235]={id=3235,name="moglophone II",plural="moglophones II",description="\nA convenient device created by mysterious moogle magic that automatically sends information about \"the secret place\" to the moogle who devised it. The range is shorter than the original model.",category=2},
