[3292]={id=3292,name="distorted fragment",plural="distorted fragments",description="\nA fragment of a once-powerful orbs. Enables the bearer to reforge artifacts to +3.\n",category=2},
[3293]={id=3293,name="Memorian, the Magicked Doll",plural="Memorians, the Magicked Dolls",description="\nA magicked doll crafted by Professor Koru-Moru that reacts to places or people whose memories have been manipulated by Uran-Mafran. It would behoove you to visit those you think may have been affected.",category=2},
[3294]={id=3294,name="depleted Memorian",plural="depleted Memorians",description="\nA magicked doll given to you by Professor Koru-Moru. It has successfully reacted to Uran-Mafran's magick and thus has wholly run out of juice.",category=2},
[3295]={id=3295,name="Trion's directive",plural="Trion's directives",description="\nThis note contains orders for Rahal, head of the Royal Knights, to Uran-Mafran, the mage from Windurst. Expectations for Altennia and her retinue are high.",category=2},
[3296]={id=3296,name="ember-encrusted orichalcum",plural="ember-encrusted orichalcum",description="\nThis lump of orichalcum has been purified by the flames of Ifrit's Cauldron.",category=3},
[3297]={id=3297,name="cloth-lined basket",plural="cloth-lined baskets",description="\nThis basket, adorned with a beautiful floral print cloth, once held hard-boiled eggs brought to Maat as a gift. You can't help but sense a familiar odor wafting from the reeds...",category=2},
[3298]={id=3298,name="map to the woman's home",plural="maps to the woman's home",description="\nMuckvix hastily scrawled this map on a yellowed piece of parchment. This should help you find the woman Maat was looking for. Perhaps Miladi-Nildi near the rental houses in Lower Jeuno can assist you in deciphering it.",category=2},
[3299]={id=3299,name="Maat's pillow",plural="Maat's pillows",description="\nA pink pillow left behind by Maat as he went on the warpath. The cute red and purple hearts that adorn it are brimming with positive energy.",category=2},
[3300]={id=3300,name="shiny Ra'Kaznarian plate",plural="shiny Ra'Kaznarian plates",description="\nA prismatic sheet of metal found in Outer Ra'Kaznar.",category=2},
[3301]={id=3301,name="dull Ra'Kaznarian plate",plural="dull Ra'Kaznarian plates",description="\nA nondescript sheet of metal that has clearly seen better days.",category=2},
[3302]={id=3302,name="Liber Daemonium",plural="Liber Daemoniums",description="\nA forbidden volume housed in Celennia Memorial Library. Author unknown. Countless tragedies are said to befall any who foolishly peruse its pages.",category=2},
[3303]={id=3303,name="bronze-hued tag",plural="bronze-hued tags",description="\nThe metallic tag, a symbol of infinite knowledge, gleams with an inner light. It doubles as a key to open the door to a research chamber in northeastern Outer Ra'Kaznar.",category=2},
[3304]={id=3304,name="Silver Knife membership card",plural="Silver Knife membership cards",description="\nThis card permits the bearer entry to the Silver Knife, a members-only auction house in Eastern Adoulin.",category=2},
[3305]={id=3305,name="courageous warrior's soul",plural="courageous warrior's souls",description="\nA mystical soul containing the essence of a couragous warrior. Enables the bearer to reforge warrior empyrean armor to +3.",category=2},
