[3327]={id=3327,name="Uran-Mafran's orb",plural="Uran-Mafran's orbs",description="\nUran-Mafran carelessly dropped this orb as he was fleeing from the scene. It appears to harbor the essence of life...the power of the crystals.",category=3},
[3328]={id=3328,name="Ruspix's plate",plural="Ruspix's plates",description="\nA plate of dubious origins developed by the surprisingly eloquent Ruspix. He claims that it can slowly accumulate energies from expended Ra'kaznarian plates. A wax seal on the back confirms yet again that it is an authentic Ruspix original.",category=2},
